{
  "name": "服薬管理アプリ",
  "description": "A simple and aesthetic medication management app featuring calendar views, inventory tracking, and daily reminders.",
  "requestFramePermissions": [
    "camera"
  ]
}

export type ViewMode = 'home' | 'meds' | 'settings';
export type CalendarMode = 'month' | 'week' | 'day';

export type UnitType = 
  | '包' 
  | '個' 
  | '錠' 
  | 'カプセル' 
  | '漢方' 
  | '吸入' 
  | '注射' 
  | '塗り薬' 
  | '貼り薬' 
  | 'スプレー' 
  | 'mg' 
  | 'ml' 
  | '点眼薬';

// カスタム文字列（例："3日に1回"）を許容するため string を追加
export type LabelType = string;

export interface HistoryEntry {
  id: string;
  timestamp: number;
  type: 'manual' | 'scan' | 'update';
  message: string;
}

export interface Medication {
  id: string;
  title: string;
  unit: UnitType;
  dosage: number; // 1回あたりの量
  label: LabelType;
  stock: number;
  memo: string;
  notificationTime?: string; // HH:mm
  color: string;
  history?: HistoryEntry[];
  lastUpdated?: number;
}

export interface MedicationLog {
  id: string;
  medicationId: string;
  timestamp: number; // Date.getTime()
  dateStr: string; // YYYY-MM-DD for easy grouping
}

import React, { useState, useEffect, useRef } from 'react';
import { Check, ChevronLeft, Trash2, Pill, Clock, X, ChevronDown, History } from 'lucide-react';
import { Medication, UnitType, LabelType } from '../types';
import { UNITS, LABELS } from '../constants';
import { format } from 'date-fns';
import { ja } from 'date-fns/locale';

interface MedicationFormProps {
  initialData?: Medication;
  onSave: (med: Medication) => void;
  onCancel: () => void;
  onDelete?: (id: string) => void;
  visibleUnits: string[];
  visibleLabels: string[];
}

// Generate Options
const HOURS = Array.from({ length: 24 }, (_, i) => i);
const MINUTES = Array.from({ length: 60 }, (_, i) => i);
const DOSAGE_OPTIONS = [0.5, 1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10];
const STOCK_OPTIONS = Array.from({ length: 101 }, (_, i) => i); // 0 to 100

// Custom Timing Options
const CUSTOM_DAYS = Array.from({ length: 30 }, (_, i) => i + 1); // 1 to 30 days
const CUSTOM_TIMES = Array.from({ length: 10 }, (_, i) => i + 1); // 1 to 10 times

// Scrollable Wheel Component
const ScrollWheel: React.FC<{ 
  items: number[]; 
  value: number; 
  onChange: (val: number) => void;
  format?: (val: number) => string;
}> = ({ items, value, onChange, format }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const highlightListRef = useRef<HTMLDivElement>(null);

  const ITEM_HEIGHT = 40;
  const CONTAINER_HEIGHT = 160;
  const PADDING = (CONTAINER_HEIGHT - ITEM_HEIGHT) / 2;

  useEffect(() => {
    if (containerRef.current) {
      const index = items.indexOf(value);
      if (index !== -1) {
        containerRef.current.scrollTop = index * ITEM_HEIGHT;
        if (highlightListRef.current) {
          highlightListRef.current.style.transform = `translateY(-${index * ITEM_HEIGHT}px)`;
        }
      }
    }
  }, []);

  const handleScroll = () => {
    if (containerRef.current && highlightListRef.current) {
      const scrollTop = containerRef.current.scrollTop;
      highlightListRef.current.style.transform = `translateY(-${scrollTop}px)`;
      const index = Math.round(scrollTop / ITEM_HEIGHT);
      if (items[index] !== undefined && items[index] !== value) {
        onChange(items[index]);
      }
    }
  };

  return (
    <div className="relative h-[160px] w-20 overflow-hidden select-none">
      <div 
        ref={containerRef}
        onScroll={handleScroll}
        className="h-full overflow-y-auto no-scrollbar snap-y snap-mandatory"
        style={{ paddingTop: PADDING, paddingBottom: PADDING }}
      >
        {items.map((item) => (
          <div 
            key={item} 
            className="h-[40px] flex items-center justify-center snap-center text-xl font-medium text-slate-300"
          >
            {format ? format(item) : item}
          </div>
        ))}
      </div>
      <div 
        className="absolute left-0 right-0 pointer-events-none overflow-hidden"
        style={{ top: PADDING, height: ITEM_HEIGHT }}
      >
        <div ref={highlightListRef} className="w-full">
           {items.map((item) => (
            <div 
              key={item} 
              className="h-[40px] flex items-center justify-center text-xl font-bold text-slate-900"
            >
              {format ? format(item) : item}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Time Picker Modal
const TimePickerModal: React.FC<{
  initialValue: string;
  onConfirm: (val: string) => void;
  onCancel: () => void;
}> = ({ initialValue, onConfirm, onCancel }) => {
  const [hour, setHour] = useState(initialValue ? parseInt(initialValue.split(':')[0]) : 8);
  const [minute, setMinute] = useState(initialValue ? parseInt(initialValue.split(':')[1]) : 0);

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onCancel}></div>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-[300px] relative z-10 animate-in zoom-in-95 duration-200 overflow-hidden">
        <div className="bg-slate-50 px-4 py-3 border-b border-slate-100 flex justify-between items-center">
          <span className="font-bold text-slate-900">時間を設定</span>
          <button onClick={onCancel} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
        </div>
        <div className="p-6 flex justify-center items-center gap-4 bg-white relative">
          <div className="absolute top-1/2 left-4 right-4 -translate-y-1/2 h-10 bg-slate-100 rounded-lg -z-10 pointer-events-none"></div>
          <ScrollWheel items={HOURS} value={hour} onChange={setHour} format={(val) => val.toString().padStart(2, '0')} />
          <span className="text-2xl font-bold text-slate-300 pb-1">:</span>
          <ScrollWheel items={MINUTES} value={minute} onChange={setMinute} format={(val) => val.toString().padStart(2, '0')} />
        </div>
        <div className="p-4 border-t border-slate-100 flex justify-end gap-3 bg-slate-50">
           <button onClick={() => onConfirm('')} className="text-red-500 font-bold text-sm px-3 py-2 mr-auto">解除</button>
           <button onClick={() => onConfirm(`${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`)} className="bg-emerald-600 text-white px-6 py-2 rounded-full font-bold shadow-md shadow-emerald-200">OK</button>
        </div>
      </div>
    </div>
  );
};

// Custom Timing Modal (Days & Frequency)
const CustomTimingModal: React.FC<{
  onConfirm: (val: string) => void;
  onCancel: () => void;
}> = ({ onConfirm, onCancel }) => {
  const [days, setDays] = useState(1);
  const [times, setTimes] = useState(1);

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onCancel}></div>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-[300px] relative z-10 animate-in zoom-in-95 duration-200 overflow-hidden">
        <div className="bg-slate-50 px-4 py-3 border-b border-slate-100 flex justify-between items-center">
          <span className="font-bold text-slate-900">カスタム頻度</span>
          <button onClick={onCancel} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
        </div>
        <div className="p-6 flex justify-center items-center gap-2 bg-white relative">
          <div className="absolute top-1/2 left-4 right-4 -translate-y-1/2 h-10 bg-slate-100 rounded-lg -z-10 pointer-events-none"></div>
          <div className="flex items-center">
            <ScrollWheel items={CUSTOM_DAYS} value={days} onChange={setDays} />
            <span className="text-sm font-bold text-slate-900 ml-1 whitespace-nowrap">日に</span>
          </div>
          <div className="flex items-center">
            <ScrollWheel items={CUSTOM_TIMES} value={times} onChange={setTimes} />
            <span className="text-sm font-bold text-slate-900 ml-1 whitespace-nowrap">回</span>
          </div>
        </div>
        <div className="p-4 border-t border-slate-100 flex justify-end gap-3 bg-slate-50">
           <button onClick={onCancel} className="text-slate-500 font-bold text-sm px-3 py-2">キャンセル</button>
           <button onClick={() => onConfirm(`${days}日に${times}回`)} className="bg-emerald-600 text-white px-6 py-2 rounded-full font-bold shadow-md shadow-emerald-200">OK</button>
        </div>
      </div>
    </div>
  );
};

export const MedicationForm: React.FC<MedicationFormProps> = ({ initialData, onSave, onCancel, onDelete, visibleUnits, visibleLabels }) => {
  const [title, setTitle] = useState(initialData?.title || '');
  const [dosage, setDosage] = useState(initialData?.dosage?.toString() || '1');
  const [unit, setUnit] = useState<UnitType>(initialData?.unit || '錠');
  const [label, setLabel] = useState<LabelType>(initialData?.label || '朝食後');
  const [stock, setStock] = useState(initialData?.stock?.toString() || '0');
  const [memo, setMemo] = useState(initialData?.memo || '');
  const [notificationTime, setNotificationTime] = useState(initialData?.notificationTime || '');

  const [isTimePickerOpen, setIsTimePickerOpen] = useState(false);
  const [isCustomTimingOpen, setIsCustomTimingOpen] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  // Determine which options to show
  const currentUnitOptions = UNITS.filter(u => visibleUnits.includes(u) || u === unit);
  const currentLabelOptions = LABELS.filter(l => visibleLabels.includes(l) || l === label || (l === 'カスタム' && visibleLabels.includes('カスタム')));

  const displayLabel = LABELS.includes(label) ? label : (label.includes('日に') ? label : 'カスタム');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return;

    const newEntry = {
      id: crypto.randomUUID(),
      timestamp: Date.now(),
      type: initialData ? 'update' as const : 'manual' as const,
      message: initialData ? '登録情報を更新しました' : '手動で登録しました'
    };

    onSave({
      id: initialData?.id || crypto.randomUUID(),
      title,
      dosage: parseFloat(dosage) || 1,
      unit,
      label,
      stock: parseInt(stock) || 0,
      memo,
      notificationTime: notificationTime || undefined,
      color: 'emerald',
      history: [...(initialData?.history || []), newEntry],
      lastUpdated: Date.now()
    });
  };

  const confirmDelete = () => {
    if (onDelete && initialData?.id) onDelete(initialData.id);
  };

  const handleLabelChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'カスタム') {
      setIsCustomTimingOpen(true);
    } else {
      setLabel(val);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-100 flex flex-col animate-in slide-in-from-bottom-5 duration-300">
      {/* Header */}
      <div className="bg-white px-4 py-3 flex items-center justify-between shadow-sm border-b border-slate-200 safe-top">
        <button type="button" onClick={onCancel} className="p-2 -ml-2 text-slate-900 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft size={24} /></button>
        <h2 className="text-lg font-bold text-slate-900">{initialData ? 'お薬の編集' : '新しいお薬'}</h2>
        <div className="w-10"></div> 
      </div>

      {/* Form Body */}
      <div className="flex-1 overflow-y-auto p-4 pb-48 safe-bottom">
        <div className="max-w-md mx-auto space-y-4">

          {/* Row 1: Name */}
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200">
            <label className="block text-xs font-bold text-slate-900 mb-1">お薬の名前</label>
            <input type="text" required value={title} onChange={(e) => setTitle(e.target.value)} placeholder="例: ロキソニン" className="w-full bg-transparent text-xl font-bold text-slate-900 placeholder:text-slate-300 outline-none" />
          </div>

          {/* Row 2: Dosage (Small), Unit (Medium), Timing (Large) */}
          <div className="grid grid-cols-[0.8fr_1fr_1.5fr] gap-3">
             {/* Dosage */}
             <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 relative">
                <label className="block text-xs font-bold text-slate-900 mb-1">1回の量</label>
                <select value={dosage} onChange={(e) => setDosage(e.target.value)} className="w-full bg-transparent text-xl font-bold text-slate-900 outline-none appearance-none">
                  {DOSAGE_OPTIONS.map(d => <option key={d} value={d}>{d}</option>)}
                </select>
                <ChevronDown size={14} className="absolute right-3 bottom-5 pointer-events-none text-slate-900" />
             </div>

             {/* Unit */}
             <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 relative">
                <label className="block text-xs font-bold text-slate-900 mb-1">単位</label>
                <select value={unit} onChange={(e) => setUnit(e.target.value as UnitType)} className="w-full bg-transparent text-xl font-bold text-slate-900 outline-none appearance-none pr-4">
                  {currentUnitOptions.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
                <Pill size={14} className="absolute right-3 bottom-5 pointer-events-none text-slate-900" />
             </div>

             {/* Timing */}
             <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 relative">
                <label className="block text-xs font-bold text-slate-900 mb-1">服薬タイミング</label>
                <select value={displayLabel} onChange={handleLabelChange} className="w-full bg-transparent text-lg font-bold text-slate-900 outline-none appearance-none pr-4">
                  {!LABELS.includes(label) && <option value={label}>{label}</option>}
                  {currentLabelOptions.map(l => <option key={l} value={l}>{l}</option>)}
                </select>
                <ChevronDown size={14} className="absolute right-3 bottom-5 pointer-events-none text-slate-900" />
             </div>
          </div>

          {/* Row 3: Stock & Notification */}
          <div className="grid grid-cols-2 gap-4">
             {/* Stock */}
             <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 relative">
                <label className="block text-xs font-bold text-slate-900 mb-1">現在の在庫</label>
                <select value={stock} onChange={(e) => setStock(e.target.value)} className="w-full bg-transparent text-xl font-bold text-slate-900 outline-none appearance-none">
                  {STOCK_OPTIONS.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
                <ChevronDown size={16} className="absolute right-4 bottom-5 pointer-events-none text-slate-900" />
             </div>

             {/* Notification */}
             <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 relative">
                <label className="block text-xs font-bold text-slate-900 mb-1">通知時間 (任意)</label>
                <button type="button" onClick={() => setIsTimePickerOpen(true)} className="w-full text-left bg-transparent text-xl font-bold outline-none">
                  {notificationTime ? <span className="text-slate-900">{notificationTime}</span> : <span className="text-slate-900">-- : --</span>}
                </button>
                <Clock size={16} className="absolute right-4 bottom-5 pointer-events-none text-slate-900" />
             </div>
          </div>

          {/* Row 4: Memo */}
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200">
            <label className="block text-xs font-bold text-slate-900 mb-1">メモ</label>
            <textarea rows={2} value={memo} onChange={(e) => setMemo(e.target.value)} placeholder="注意事項など..." className="w-full bg-transparent text-base font-medium text-slate-900 placeholder:text-slate-300 outline-none resize-none" />
          </div>

          {/* History Section */}
          {initialData?.history && initialData.history.length > 0 && (
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-3 text-slate-400">
                <History size={16} />
                <span className="text-xs font-bold uppercase tracking-wider">更新履歴</span>
              </div>
              <div className="space-y-3">
                {[...initialData.history].reverse().slice(0, 5).map(entry => (
                  <div key={entry.id} className="text-xs border-l-2 border-slate-100 pl-3 py-1">
                    <div className="text-slate-400 font-medium mb-0.5">{format(entry.timestamp, 'yyyy/MM/dd HH:mm', { locale: ja })}</div>
                    <div className="text-slate-700 font-bold">{entry.message}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Delete Button */}
          {initialData && onDelete && (
            <button type="button" onClick={() => setShowDeleteModal(true)} className="w-full py-3.5 bg-red-50 text-red-600 rounded-xl font-bold text-lg hover:bg-red-100 active:scale-[0.98] transition-all flex justify-center items-center gap-2 shadow-sm border border-red-100 mt-8">
              <Trash2 size={24} strokeWidth={2.5} /> このお薬を削除
            </button>
          )}
        </div>
      </div>

      {/* Footer */}
      <div className="absolute bottom-0 left-0 right-0 bg-white/90 backdrop-blur-md border-t border-slate-200 p-4 pb-safe safe-bottom shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-50">
        <div className="max-w-md mx-auto">
          <button onClick={handleSubmit} className="w-full bg-emerald-600 text-white py-3.5 rounded-xl font-bold text-lg hover:bg-emerald-700 active:scale-[0.98] transition-all flex justify-center items-center gap-2 shadow-lg shadow-emerald-200">
            <Check size={24} strokeWidth={3} /> 保存する
          </button>
        </div>
      </div>

      {/* Modals */}
      {isTimePickerOpen && <TimePickerModal initialValue={notificationTime} onConfirm={(val) => { setNotificationTime(val); setIsTimePickerOpen(false); }} onCancel={() => setIsTimePickerOpen(false)} />}

      {isCustomTimingOpen && (
        <CustomTimingModal 
          onConfirm={(val) => { setLabel(val); setIsCustomTimingOpen(false); }} 
          onCancel={() => setIsCustomTimingOpen(false)} 
        />
      )}

      {showDeleteModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
            <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowDeleteModal(false)}></div>
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm p-6 relative z-10 animate-in zoom-in-95 duration-200">
                <h3 className="text-lg font-bold text-slate-900 mb-2">削除の確認</h3>
                <p className="text-slate-900 mb-6 font-medium">このお薬を削除します。<br/>よろしいですか？</p>
                <div className="flex gap-3">
                    <button onClick={() => setShowDeleteModal(false)} className="flex-1 py-3 rounded-xl font-bold text-slate-900 bg-slate-100 hover:bg-slate-200 transition-colors">キャンセル</button>
                    <button onClick={confirmDelete} className="flex-1 py-3 rounded-xl font-bold text-white bg-red-500 hover:bg-red-600 shadow-lg shadow-red-200 transition-colors">削除</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, addMonths, subMonths, isToday, addWeeks, subWeeks } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { Medication, MedicationLog, ViewMode, CalendarMode, Type } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  // --- State ---
  const [view, setView] = useState<ViewMode>('home');

  // Calendar State
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('week');

  // Data State
  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  // Preferences State
  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleUnits');
      return saved ? JSON.parse(saved) : UNITS;
    } catch { return UNITS; }
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleLabels');
      return saved ? JSON.parse(saved) : LABELS;
    } catch { return LABELS; }
  });

  // UI State
  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Effects (Persistence) ---
  useEffect(() => {
    try {
      const savedMeds = localStorage.getItem('medications');
      const savedLogs = localStorage.getItem('logs');
      if (savedMeds) setMedications(JSON.parse(savedMeds));
      if (savedLogs) setLogs(JSON.parse(savedLogs));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('medications', JSON.stringify(medications));
  }, [medications]);

  useEffect(() => {
    localStorage.setItem('logs', JSON.stringify(logs));
  }, [logs]);

  useEffect(() => {
    localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits));
  }, [visibleUnits]);

  useEffect(() => {
    localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels));
  }, [visibleLabels]);

  // --- Logic Helpers ---
  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      // Check if duplicate name exists
      const duplicate = medications.find(m => m.title === med.title);
      if (duplicate) {
        if (window.confirm(`「${med.title}」は既に登録されています。在庫を更新しますか？`)) {
          const updatedHistory = [
            ...(duplicate.history || []),
            { id: crypto.randomUUID(), timestamp: Date.now(), type: 'update', message: `OCR/登録により在庫を ${med.stock} 追加しました` }
          ];
          setMedications(prev => prev.map(m => m.id === duplicate.id ? { 
            ...m, 
            stock: m.stock + med.stock, 
            history: updatedHistory,
            lastUpdated: Date.now()
          } : m));
        }
      } else {
        setMedications(prev => [...prev, med]);
      }
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const handleDeleteMed = (id: string) => {
    setMedications(prev => prev.filter(m => m.id !== id));
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      const newLog: MedicationLog = {
        id: crypto.randomUUID(),
        medicationId: medId,
        timestamp: new Date().getTime(),
        dateStr
      };
      setLogs(prev => [...prev, newLog]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    if (calendarMode === 'day') {
      const newDate = direction === 'next' ? addDays(selectedDate, 1) : addDays(selectedDate, -1);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(prev => direction === 'next' ? addWeeks(prev, 1) : subWeeks(prev, 1));
    } else {
      setDisplayDate(prev => direction === 'next' ? addMonths(prev, 1) : subMonths(prev, 1));
    }
  };

  // --- OCR Scanning Logic ---
  const handleScanClick = () => {
    setShowAddMenu(false);
    fileInputRef.current?.click();
  };

  const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];
        await performOCR(base64Data);
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error(err);
      alert('読み取りに失敗しました。');
      setIsScanning(false);
    }
  };

  const performOCR = async (base64Image: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        このお薬手帳の画像から、お薬の情報を抽出してください。
        以下のJSON形式で返してください。
        {
          "title": "お薬の名前",
          "dosage": 1回あたりの量(数値),
          "unit": "単位(錠, カプセル, 包, 個, 漢方, mg, ml, 吸入, 注射, 塗り薬, 貼り薬, スプレー, 点眼薬から選択)",
          "label": "服薬タイミング(朝食後, 夕食前など)",
          "stock": 全体の数量(数値、不明なら0),
          "memo": "備考や注意事項"
        }
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json"
        }
      });

      const extracted = JSON.parse(response.text || '{}');

      // Ensure it matches our Medication type
      const scannedMed: Medication = {
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || 'お薬手帳から読み取り',
        color: 'emerald',
        history: [{ id: crypto.randomUUID(), timestamp: Date.now(), type: 'scan', message: 'お薬手帳から読み取りました' }]
      };

      setEditingMed(scannedMed);
      setIsFormOpen(true);
    } catch (err) {
      console.error(err);
      alert('解析中にエラーが発生しました。');
    } finally {
      setIsScanning(false);
    }
  };

  // --- Calendar Generators ---
  const generateCalendarDays = () => {
    if (calendarMode === 'day') return [selectedDate];
    if (calendarMode === 'week') {
      const start = startOfWeek(displayDate, { weekStartsOn: 0 });
      return Array.from({ length: 7 }).map((_, i) => addDays(start, i));
    }
    const start = startOfWeek(startOfMonth(displayDate), { weekStartsOn: 0 });
    const end = endOfWeek(endOfMonth(displayDate), { weekStartsOn: 0 });
    return eachDayOfInterval({ start, end });
  };

  const calendarDays = generateCalendarDays();

  // --- Components ---

  const ActionMenu = () => (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowAddMenu(false)}></div>
      <div className="relative bg-white rounded-t-[32px] p-6 pb-12 animate-in slide-in-from-bottom duration-300">
        <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto mb-6"></div>
        <h3 className="text-xl font-extrabold text-slate-800 mb-6 text-center">追加方法を選択</h3>
        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => {
              setShowAddMenu(false);
              setEditingMed(null);
              setIsFormOpen(true);
            }}
            className="flex flex-col items-center gap-3 p-6 rounded-3xl bg-emerald-50 text-emerald-600 hover:bg-emerald-100 transition-colors"
          >
            <div className="w-14 h-14 rounded-2xl bg-emerald-500 text-white flex items-center justify-center shadow-lg shadow-emerald-200">
              <FileText size={28} />
            </div>
            <span className="font-bold">手動で入力</span>
          </button>
          <button 
            onClick={handleScanClick}
            className="flex flex-col items-center gap-3 p-6 rounded-3xl bg-blue-50 text-blue-600 hover:bg-blue-100 transition-colors"
          >
            <div className="w-14 h-14 rounded-2xl bg-blue-500 text-white flex items-center justify-center shadow-lg shadow-blue-200">
              <Camera size={28} />
            </div>
            <span className="font-bold">手帳をスキャン</span>
          </button>
        </div>
        <button 
          onClick={() => setShowAddMenu(false)}
          className="w-full mt-6 py-4 rounded-2xl font-bold text-slate-400 hover:bg-slate-50 transition-colors"
        >
          キャンセル
        </button>
      </div>
    </div>
  );

  const CustomizeModal = () => {
    const [activeTab, setActiveTab] = useState<'timing' | 'unit'>('timing');

    const toggleUnit = (u: string) => {
      setVisibleUnits(prev => prev.includes(u) ? prev.filter(x => x !== u) : [...prev, u]);
    };

    const toggleLabel = (l: string) => {
      setVisibleLabels(prev => prev.includes(l) ? prev.filter(x => x !== l) : [...prev, l]);
    };

    return (
      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowCustomizeModal(false)}></div>
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm flex flex-col max-h-[80vh] relative z-10 animate-in zoom-in-95 duration-200">
          <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl">
            <h3 className="font-bold text-slate-800">表示のカスタマイズ</h3>
            <button onClick={() => setShowCustomizeModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
          </div>
          <div className="flex p-2 gap-2 bg-slate-50 border-b border-slate-100">
            <button onClick={() => setActiveTab('timing')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'timing' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>服薬タイミング</button>
            <button onClick={() => setActiveTab('unit')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'unit' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>単位</button>
          </div>
          <div className="flex-1 overflow-y-auto p-2">
            {(activeTab === 'timing' ? LABELS : UNITS).map(item => (
              <label key={item} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 cursor-pointer">
                <span className="font-bold text-slate-700">{item}</span>
                <div className="relative inline-flex items-center">
                  <input type="checkbox" checked={(activeTab === 'timing' ? visibleLabels : visibleUnits).includes(item)} onChange={() => activeTab === 'timing' ? toggleLabel(item) : toggleUnit(item)} className="sr-only peer" />
                  <div className="w-11 h-6 bg-slate-200 rounded-full peer peer-checked:bg-emerald-500 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                </div>
              </label>
            ))}
          </div>
          <div className="p-4 border-t border-slate-100 bg-slate-50 rounded-b-2xl">
             <button onClick={() => setShowCustomizeModal(false)} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-emerald-200">完了</button>
          </div>
        </div>
      </div>
    );
  };

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">ホーム</h1>
      </div>

      <div className="bg-white shadow-sm z-10 sticky top-0 rounded-b-3xl border-b border-slate-100">
        <div className="px-5 pt-4 pb-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
              <CalendarIcon className="text-emerald-600" size={24} />
              {calendarMode === 'day' 
                ? format(selectedDate, 'M月d日', { locale: ja }) 
                : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
               {['month', 'week', 'day'].map((m: any) => (
                 <button key={m} onClick={() => { setCalendarMode(m); if(m!=='month') setDisplayDate(selectedDate); }} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                   {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                 </button>
               ))}
            </div>
          </div>
          <div className="flex justify-between items-center mb-2">
             <button onClick={() => handleCalendarNavigate('prev')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronLeft size={20}/></button>
             <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full hover:bg-emerald-100 transition-colors">今日に戻る</button>
             <button onClick={() => handleCalendarNavigate('next')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronRight size={20}/></button>
          </div>
          <div className={`grid ${calendarMode === 'month' ? 'grid-cols-7 gap-y-1' : calendarMode === 'week' ? 'grid-cols-7' : 'grid-cols-1'} text-center pb-4`}>
            {calendarMode !== 'day' && WEEK_DAYS.map((day, i) => (
              <div key={day} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{day}</div>
            ))}
            {calendarDays.map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = calendarMode !== 'month' || format(day, 'M') === format(displayDate, 'M');
              const dayStr = format(day, 'yyyy-MM-dd');
              const medsForDay = medications.length;
              const completedCount = logs.filter(l => l.dateStr === dayStr && medications.some(m => m.id === l.medicationId)).length;
              const allDone = medsForDay > 0 && medsForDay === completedCount;
              const someDone = completedCount > 0;
              if (calendarMode === 'day') return <div key={idx} className="py-6 text-3xl font-extrabold text-slate-800 tracking-tight animate-in fade-in zoom-in duration-300">{format(day, 'M月d日', { locale: ja })}</div>;
              return (
                <div key={idx} className="flex flex-col items-center">
                  <button onClick={() => setSelectedDate(day)} className={`w-10 h-10 flex flex-col items-center justify-center rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md shadow-emerald-200 scale-105 z-10' : 'text-slate-700 hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-30' : ''}`}>
                    <span className={`text-sm font-bold ${isSelected ? 'text-white' : isTodayDate ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                    {medsForDay > 0 && <div className={`w-1.5 h-1.5 rounded-full mt-0.5 ${isSelected ? 'bg-white/80' : allDone ? 'bg-emerald-400' : someDone ? 'bg-orange-300' : 'bg-slate-200'}`}></div>}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-6 space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M月d日 (EE)', { locale: ja })}<span className="text-slate-400 text-sm font-normal ml-2">のタスク</span></h3>
          <button 
            onClick={() => setShowAddMenu(true)} 
            className="flex items-center gap-1 bg-emerald-600 text-white px-3 py-1.5 rounded-full font-bold text-sm shadow-lg shadow-emerald-100 active:scale-95 transition-all ring-4 ring-emerald-50"
          >
            <Plus size={16} strokeWidth={3} /> 追加
          </button>
        </div>
        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl shadow-sm border border-slate-100 mx-2">
             <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><Pill className="text-slate-300" size={32} /></div>
             <p className="text-slate-500 font-medium mb-3">お薬が登録されていません</p>
          </div>
        ) : (
          medications.map(med => {
            const completed = isCompleted(med.id, selectedDate);
            const expanded = showDetailId === med.id;
            return (
              <div key={med.id} className={`relative overflow-hidden rounded-2xl shadow-sm border transition-all duration-300 ${completed ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100 hover:border-emerald-200 hover:shadow-md'}`}>
                <div className="p-4 flex items-center gap-4">
                  <button onClick={() => toggleComplete(med.id, selectedDate)} className={`flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${completed ? 'bg-emerald-500 text-white shadow-sm shadow-emerald-200' : 'bg-slate-100 text-slate-300'}`}>
                    <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${completed ? 'scale-100' : 'scale-0'}`} />
                  </button>
                  <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(expanded ? null : med.id)}>
                    <div className="flex justify-between items-start mb-1">
                      <h4 className={`font-bold text-lg leading-tight transition-colors ${completed ? 'text-slate-400 line-through decoration-2 decoration-slate-300' : 'text-slate-800'}`}>{med.title}</h4>
                      <span className={`text-[10px] font-bold px-2 py-1 rounded-md border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>{med.label}</span>
                    </div>
                    <div className="flex items-center gap-3 text-xs font-medium text-slate-500">
                      <span className="flex items-center gap-1"><Pill size={12} /> {med.dosage}{med.unit}</span>
                      {med.notificationTime && <span className="flex items-center gap-1"><Bell size={12} /> {med.notificationTime}</span>}
                    </div>
                  </div>
                </div>
                <div className={`bg-slate-50 border-t border-slate-100 transition-all duration-300 ease-in-out ${expanded ? 'max-h-60 opacity-100' : 'max-h-0 opacity-0'}`}>
                   <div className="p-4 space-y-3">
                      <div className="flex justify-between items-center text-sm">
                         <span className="text-slate-500 font-medium">在庫数</span>
                         <span className={`font-bold ${med.stock <= 5 ? 'text-red-500' : 'text-slate-700'}`}>あと {med.stock} {med.unit}</span>
                      </div>
                      {med.memo && <div className="flex gap-2 text-sm text-slate-600 bg-white p-2 rounded-lg border border-slate-100"><AlertCircle size={16} className="text-orange-400 shrink-0 mt-0.5" />{med.memo}</div>}
                      <button 
                        onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }}
                        className="w-full py-2 bg-white text-emerald-600 rounded-lg text-xs font-bold border border-emerald-100 hover:bg-emerald-50"
                      >
                        詳細を編集する
                      </button>
                   </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );

  const renderMeds = () => (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top relative">
         <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
         <button onClick={() => setShowAddMenu(true)} className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-1 bg-emerald-600 text-white font-bold text-sm px-4 py-2 rounded-full shadow-lg shadow-emerald-100 ring-4 ring-emerald-50 active:scale-95 transition-all">
          <Plus size={16} strokeWidth={3} /> 追加
        </button>
      </div>
      <div className="p-4 space-y-3 overflow-y-auto pb-32">
        {medications.length === 0 ? (
           <div className="flex flex-col items-center justify-center h-[50vh] text-slate-400">
              <div className="bg-slate-100 p-6 rounded-full mb-4"><Archive size={40} className="opacity-50"/></div>
              <p className="font-medium">登録されたお薬はありません</p>
           </div>
        ) : (
          medications.map(med => (
            <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
              <div>
                <div className="flex items-center gap-2 mb-2">
                   <h3 className="font-bold text-lg text-slate-800">{med.title}</h3>
                   <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>{med.label}</span>
                </div>
                <div className="text-sm text-slate-500 font-medium flex items-center gap-3">
                  <span className={`${med.stock < 5 ? 'text-red-500 font-bold' : 'text-slate-600'}`}>残り {med.stock}{med.unit}</span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span>1回 {med.dosage}{med.unit}</span>
                </div>
              </div>
              <ChevronRight size={20} className="text-slate-300" />
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen text-slate-900 font-sans max-w-md mx-auto shadow-2xl overflow-hidden relative">
      <div className="h-full overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && renderMeds()}
        {view === 'settings' && (
           <div className="flex flex-col h-full bg-slate-50">
           <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
           <div className="bg-white px-5 py-4 shadow-sm sticky top-0 z-10 rounded-b-3xl border-b border-slate-100"><h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2"><SettingsIcon size={24} className="text-slate-400"/>設定詳細</h2></div>
           <div className="p-5 space-y-8 overflow-y-auto pb-32">
             <section className="space-y-3">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">カスタマイズ</h3>
                <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                   <button onClick={() => setShowCustomizeModal(true)} className="w-full p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                     <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-xl"><SlidersHorizontal size={20}/></div>
                        <div className="text-left"><p className="font-bold text-slate-800">表示のカスタマイズ</p><p className="text-xs text-slate-500 font-medium">単位やタイミングの選択肢を編集</p></div>
                     </div>
                     <ChevronRight size={20} className="text-slate-300" />
                   </button>
                </div>
             </section>
             <section className="space-y-3">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">データ管理</h3>
                <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden divide-y divide-slate-50">
                   <button onClick={() => { const data = JSON.stringify({ medications, logs }, null, 2); const blob = new Blob([data], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `medimate_backup_${format(new Date(), 'yyyyMMdd')}.json`; a.click(); }} className="w-full p-4 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
                      <div className="p-2.5 bg-blue-50 text-blue-500 rounded-xl"><Database size={20}/></div>
                      <div><p className="font-bold text-slate-800">バックアップを保存</p><p className="text-xs text-slate-500 font-medium">現在のデータをJSONでダウンロード</p></div>
                   </button>
                   <button onClick={() => { if(window.confirm('すべてのデータを削除して初期化しますか？')) { localStorage.clear(); setMedications([]); setLogs([]); alert('初期化しました'); } }} className="w-full p-4 flex items-center gap-3 hover:bg-red-50 transition-colors text-left">
                      <div className="p-2.5 bg-red-50 text-red-500 rounded-xl"><RotateCcw size={20}/></div>
                      <div><p className="font-bold text-red-600">データを初期化</p><p className="text-xs text-slate-500 font-medium">記録を消去する</p></div>
                   </button>
                </div>
             </section>
             <div className="text-center pt-8 pb-4"><p className="text-xs font-bold text-slate-300">MediMate v1.4.0 (OCR Support)</p></div>
           </div>
         </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {/* Hidden File Input for Scan */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={onFileChange} 
        accept="image/*" 
        capture="environment" 
        className="hidden" 
      />

      {/* Loading Overlay */}
      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
          <Loader2 size={48} className="animate-spin mb-4 text-emerald-400" />
          <p className="text-lg font-bold">手帳を解析しています...</p>
          <p className="text-sm opacity-70">しばらくお待ちください</p>
        </div>
      )}

      {showAddMenu && <ActionMenu />}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={handleDeleteMed}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}

      {showCustomizeModal && <CustomizeModal />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, addMonths, subMonths, isToday, addWeeks, subWeeks } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
// Fix: Removed 'Type' from './types' import as it is not exported there
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
// Fix: Imported 'Type' from '@google/genai' for use in responseSchema
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  // --- State ---
  const [view, setView] = useState<ViewMode>('home');

  // Calendar State
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('week');

  // Data State
  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  // Preferences State
  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleUnits');
      return saved ? JSON.parse(saved) : UNITS;
    } catch { return UNITS; }
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('visibleLabels');
      return saved ? JSON.parse(saved) : LABELS;
    } catch { return LABELS; }
  });

  // UI State
  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Effects (Persistence) ---
  useEffect(() => {
    try {
      const savedMeds = localStorage.getItem('medications');
      const savedLogs = localStorage.getItem('logs');
      if (savedMeds) setMedications(JSON.parse(savedMeds));
      if (savedLogs) setLogs(JSON.parse(savedLogs));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('medications', JSON.stringify(medications));
  }, [medications]);

  useEffect(() => {
    localStorage.setItem('logs', JSON.stringify(logs));
  }, [logs]);

  useEffect(() => {
    localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits));
  }, [visibleUnits]);

  useEffect(() => {
    localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels));
  }, [visibleLabels]);

  // --- Logic Helpers ---
  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      // Check if duplicate name exists
      const duplicate = medications.find(m => m.title === med.title);
      if (duplicate) {
        if (window.confirm(`「${med.title}」は既に登録されています。在庫を更新しますか？`)) {
          const updatedHistory = [
            ...(duplicate.history || []),
            { id: crypto.randomUUID(), timestamp: Date.now(), type: 'update', message: `OCR/登録により在庫を ${med.stock} 追加しました` }
          ];
          setMedications(prev => prev.map(m => m.id === duplicate.id ? { 
            ...m, 
            stock: m.stock + med.stock, 
            history: updatedHistory,
            lastUpdated: Date.now()
          } : m));
        }
      } else {
        setMedications(prev => [...prev, med]);
      }
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const handleDeleteMed = (id: string) => {
    setMedications(prev => prev.filter(m => m.id !== id));
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      const newLog: MedicationLog = {
        id: crypto.randomUUID(),
        medicationId: medId,
        timestamp: new Date().getTime(),
        dateStr
      };
      setLogs(prev => [...prev, newLog]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    if (calendarMode === 'day') {
      const newDate = direction === 'next' ? addDays(selectedDate, 1) : addDays(selectedDate, -1);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(prev => direction === 'next' ? addWeeks(prev, 1) : subWeeks(prev, 1));
    } else {
      setDisplayDate(prev => direction === 'next' ? addMonths(prev, 1) : subMonths(prev, 1));
    }
  };

  // --- OCR Scanning Logic ---
  const handleScanClick = () => {
    setShowAddMenu(false);
    fileInputRef.current?.click();
  };

  const onFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64Data = (reader.result as string).split(',')[1];
        await performOCR(base64Data);
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error(err);
      alert('読み取りに失敗しました。');
      setIsScanning(false);
    }
  };

  // Fix: Improved OCR functionality with structured responseSchema and correct Type usage
  const performOCR = async (base64Image: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        このお薬手帳の画像から、お薬の情報を抽出してください。
        以下のJSON形式で返してください。
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING, description: "お薬の名前" },
              dosage: { type: Type.NUMBER, description: "1回あたりの量" },
              unit: { type: Type.STRING, description: "単位 (例: 錠, 包, カプセル)" },
              label: { type: Type.STRING, description: "服薬タイミング (例: 朝食後, 寝る前)" },
              stock: { type: Type.NUMBER, description: "全体の数量 (不明なら0)" },
              memo: { type: Type.STRING, description: "備考や注意事項" }
            },
            required: ["title", "dosage", "unit", "label"]
          }
        }
      });

      const extracted = JSON.parse(response.text || '{}');

      // Ensure it matches our Medication type
      const scannedMed: Medication = {
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || 'お薬手帳から読み取り',
        color: 'emerald',
        history: [{ id: crypto.randomUUID(), timestamp: Date.now(), type: 'scan', message: 'お薬手帳から読み取りました' }]
      };

      setEditingMed(scannedMed);
      setIsFormOpen(true);
    } catch (err) {
      console.error(err);
      alert('解析中にエラーが発生しました。');
    } finally {
      setIsScanning(false);
    }
  };

  // --- Calendar Generators ---
  const generateCalendarDays = () => {
    if (calendarMode === 'day') return [selectedDate];
    if (calendarMode === 'week') {
      const start = startOfWeek(displayDate, { weekStartsOn: 0 });
      return Array.from({ length: 7 }).map((_, i) => addDays(start, i));
    }
    const start = startOfWeek(startOfMonth(displayDate), { weekStartsOn: 0 });
    const end = endOfWeek(endOfMonth(displayDate), { weekStartsOn: 0 });
    return eachDayOfInterval({ start, end });
  };

  const calendarDays = generateCalendarDays();

  // --- Components ---

  const ActionMenu = () => (
    <div className="fixed inset-0 z-[100] flex flex-col justify-end">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowAddMenu(false)}></div>
      <div className="relative bg-white rounded-t-[32px] p-6 pb-12 animate-in slide-in-from-bottom duration-300">
        <div className="w-12 h-1.5 bg-slate-200 rounded-full mx-auto mb-6"></div>
        <h3 className="text-xl font-extrabold text-slate-800 mb-6 text-center">追加方法を選択</h3>
        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => {
              setShowAddMenu(false);
              setEditingMed(null);
              setIsFormOpen(true);
            }}
            className="flex flex-col items-center gap-3 p-6 rounded-3xl bg-emerald-50 text-emerald-600 hover:bg-emerald-100 transition-colors"
          >
            <div className="w-14 h-14 rounded-2xl bg-emerald-500 text-white flex items-center justify-center shadow-lg shadow-emerald-200">
              <FileText size={28} />
            </div>
            <span className="font-bold">手動で入力</span>
          </button>
          <button 
            onClick={handleScanClick}
            className="flex flex-col items-center gap-3 p-6 rounded-3xl bg-blue-50 text-blue-600 hover:bg-blue-100 transition-colors"
          >
            <div className="w-14 h-14 rounded-2xl bg-blue-500 text-white flex items-center justify-center shadow-lg shadow-blue-200">
              <Camera size={28} />
            </div>
            <span className="font-bold">手帳をスキャン</span>
          </button>
        </div>
        <button 
          onClick={() => setShowAddMenu(false)}
          className="w-full mt-6 py-4 rounded-2xl font-bold text-slate-400 hover:bg-slate-50 transition-colors"
        >
          キャンセル
        </button>
      </div>
    </div>
  );

  const CustomizeModal = () => {
    const [activeTab, setActiveTab] = useState<'timing' | 'unit'>('timing');

    const toggleUnit = (u: string) => {
      setVisibleUnits(prev => prev.includes(u) ? prev.filter(x => x !== u) : [...prev, u]);
    };

    const toggleLabel = (l: string) => {
      setVisibleLabels(prev => prev.includes(l) ? prev.filter(x => x !== l) : [...prev, l]);
    };

    return (
      <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
        <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowCustomizeModal(false)}></div>
        <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm flex flex-col max-h-[80vh] relative z-10 animate-in zoom-in-95 duration-200">
          <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl">
            <h3 className="font-bold text-slate-800">表示のカスタマイズ</h3>
            <button onClick={() => setShowCustomizeModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
          </div>
          <div className="flex p-2 gap-2 bg-slate-50 border-b border-slate-100">
            <button onClick={() => setActiveTab('timing')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'timing' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>服薬タイミング</button>
            <button onClick={() => setActiveTab('unit')} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'unit' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>単位</button>
          </div>
          <div className="flex-1 overflow-y-auto p-2">
            {(activeTab === 'timing' ? LABELS : UNITS).map(item => (
              <label key={item} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 cursor-pointer">
                <span className="font-bold text-slate-700">{item}</span>
                <div className="relative inline-flex items-center">
                  <input type="checkbox" checked={(activeTab === 'timing' ? visibleLabels : visibleUnits).includes(item)} onChange={() => activeTab === 'timing' ? toggleLabel(item) : toggleUnit(item)} className="sr-only peer" />
                  <div className="w-11 h-6 bg-slate-200 rounded-full peer peer-checked:bg-emerald-500 after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full peer-checked:after:border-white"></div>
                </div>
              </label>
            ))}
          </div>
          <div className="p-4 border-t border-slate-100 bg-slate-50 rounded-b-2xl">
             <button onClick={() => setShowCustomizeModal(false)} className="w-full bg-emerald-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-emerald-200">完了</button>
          </div>
        </div>
      </div>
    );
  };

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top">
         <h1 className="text-center font-bold text-slate-800">ホーム</h1>
      </div>

      <div className="bg-white shadow-sm z-10 sticky top-0 rounded-b-3xl border-b border-slate-100">
        <div className="px-5 pt-4 pb-2">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
              <CalendarIcon className="text-emerald-600" size={24} />
              {calendarMode === 'day' 
                ? format(selectedDate, 'M月d日', { locale: ja }) 
                : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1">
               {['month', 'week', 'day'].map((m: any) => (
                 <button key={m} onClick={() => { setCalendarMode(m); if(m!=='month') setDisplayDate(selectedDate); }} className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                   {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                 </button>
               ))}
            </div>
          </div>
          <div className="flex justify-between items-center mb-2">
             <button onClick={() => handleCalendarNavigate('prev')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronLeft size={20}/></button>
             <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full hover:bg-emerald-100 transition-colors">今日に戻る</button>
             <button onClick={() => handleCalendarNavigate('next')} className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"><ChevronRight size={20}/></button>
          </div>
          <div className={`grid ${calendarMode === 'month' ? 'grid-cols-7 gap-y-1' : calendarMode === 'week' ? 'grid-cols-7' : 'grid-cols-1'} text-center pb-4`}>
            {calendarMode !== 'day' && WEEK_DAYS.map((day, i) => (
              <div key={day} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{day}</div>
            ))}
            {calendarDays.map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = calendarMode !== 'month' || format(day, 'M') === format(displayDate, 'M');
              const dayStr = format(day, 'yyyy-MM-dd');
              const medsForDay = medications.length;
              const completedCount = logs.filter(l => l.dateStr === dayStr && medications.some(m => m.id === l.medicationId)).length;
              const allDone = medsForDay > 0 && medsForDay === completedCount;
              const someDone = completedCount > 0;
              if (calendarMode === 'day') return <div key={idx} className="py-6 text-3xl font-extrabold text-slate-800 tracking-tight animate-in fade-in zoom-in duration-300">{format(day, 'M月d日', { locale: ja })}</div>;
              return (
                <div key={idx} className="flex flex-col items-center">
                  <button onClick={() => setSelectedDate(day)} className={`w-10 h-10 flex flex-col items-center justify-center rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md shadow-emerald-200 scale-105 z-10' : 'text-slate-700 hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-30' : ''}`}>
                    <span className={`text-sm font-bold ${isSelected ? 'text-white' : isTodayDate ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                    {medsForDay > 0 && <div className={`w-1.5 h-1.5 rounded-full mt-0.5 ${isSelected ? 'bg-white/80' : allDone ? 'bg-emerald-400' : someDone ? 'bg-orange-300' : 'bg-slate-200'}`}></div>}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-6 space-y-4">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M月d日 (EE)', { locale: ja })}<span className="text-slate-400 text-sm font-normal ml-2">のタスク</span></h3>
          <button 
            onClick={() => setShowAddMenu(true)} 
            className="flex items-center gap-1 bg-emerald-600 text-white px-3 py-1.5 rounded-full font-bold text-sm shadow-lg shadow-emerald-100 active:scale-95 transition-all ring-4 ring-emerald-50"
          >
            <Plus size={16} strokeWidth={3} /> 追加
          </button>
        </div>
        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl shadow-sm border border-slate-100 mx-2">
             <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><Pill className="text-slate-300" size={32} /></div>
             <p className="text-slate-500 font-medium mb-3">お薬が登録されていません</p>
          </div>
        ) : (
          medications.map(med => {
            const completed = isCompleted(med.id, selectedDate);
            const expanded = showDetailId === med.id;
            return (
              <div key={med.id} className={`relative overflow-hidden rounded-2xl shadow-sm border transition-all duration-300 ${completed ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100 hover:border-emerald-200 hover:shadow-md'}`}>
                <div className="p-4 flex items-center gap-4">
                  <button onClick={() => toggleComplete(med.id, selectedDate)} className={`flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center transition-all active:scale-90 ${completed ? 'bg-emerald-500 text-white shadow-sm shadow-emerald-200' : 'bg-slate-100 text-slate-300'}`}>
                    <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${completed ? 'scale-100' : 'scale-0'}`} />
                  </button>
                  <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(expanded ? null : med.id)}>
                    <div className="flex justify-between items-start mb-1">
                      <h4 className={`font-bold text-lg leading-tight transition-colors ${completed ? 'text-slate-400 line-through decoration-2 decoration-slate-300' : 'text-slate-800'}`}>{med.title}</h4>
                      <span className={`text-[10px] font-bold px-2 py-1 rounded-md border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>{med.label}</span>
                    </div>
                    <div className="flex items-center gap-3 text-xs font-medium text-slate-500">
                      <span className="flex items-center gap-1"><Pill size={12} /> {med.dosage}{med.unit}</span>
                      {med.notificationTime && <span className="flex items-center gap-1"><Bell size={12} /> {med.notificationTime}</span>}
                    </div>
                  </div>
                </div>
                <div className={`bg-slate-50 border-t border-slate-100 transition-all duration-300 ease-in-out ${expanded ? 'max-h-60 opacity-100' : 'max-h-0 opacity-0'}`}>
                   <div className="p-4 space-y-3">
                      <div className="flex justify-between items-center text-sm">
                         <span className="text-slate-500 font-medium">在庫数</span>
                         <span className={`font-bold ${med.stock <= 5 ? 'text-red-500' : 'text-slate-700'}`}>あと {med.stock} {med.unit}</span>
                      </div>
                      {med.memo && <div className="flex gap-2 text-sm text-slate-600 bg-white p-2 rounded-lg border border-slate-100"><AlertCircle size={16} className="text-orange-400 shrink-0 mt-0.5" />{med.memo}</div>}
                      <button 
                        onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }}
                        className="w-full py-2 bg-white text-emerald-600 rounded-lg text-xs font-bold border border-emerald-100 hover:bg-emerald-50"
                      >
                        詳細を編集する
                      </button>
                   </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );

  const renderMeds = () => (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top relative">
         <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
         <button onClick={() => setShowAddMenu(true)} className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-1 bg-emerald-600 text-white font-bold text-sm px-4 py-2 rounded-full shadow-lg shadow-emerald-100 ring-4 ring-emerald-50 active:scale-95 transition-all">
          <Plus size={16} strokeWidth={3} /> 追加
        </button>
      </div>
      <div className="p-4 space-y-3 overflow-y-auto pb-32">
        {medications.length === 0 ? (
           <div className="flex flex-col items-center justify-center h-[50vh] text-slate-400">
              <div className="bg-slate-100 p-6 rounded-full mb-4"><Archive size={40} className="opacity-50"/></div>
              <p className="font-medium">登録されたお薬はありません</p>
           </div>
        ) : (
          medications.map(med => (
            <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
              <div>
                <div className="flex items-center gap-2 mb-2">
                   <h3 className="font-bold text-lg text-slate-800">{med.title}</h3>
                   <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-gray-100 border-gray-200'}`}>{med.label}</span>
                </div>
                <div className="text-sm text-slate-500 font-medium flex items-center gap-3">
                  <span className={`${med.stock < 5 ? 'text-red-500 font-bold' : 'text-slate-600'}`}>残り {med.stock}{med.unit}</span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span>1回 {med.dosage}{med.unit}</span>
                </div>
              </div>
              <ChevronRight size={20} className="text-slate-300" />
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen text-slate-900 font-sans max-w-md mx-auto shadow-2xl overflow-hidden relative">
      <div className="h-full overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && renderMeds()}
        {view === 'settings' && (
           <div className="flex flex-col h-full bg-slate-50">
           <div className="bg-slate-50/80 backdrop-blur-sm border-b border-slate-200 py-3 safe-top"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
           <div className="bg-white px-5 py-4 shadow-sm sticky top-0 z-10 rounded-b-3xl border-b border-slate-100"><h2 className="text-xl font-extrabold text-slate-800 flex items-center gap-2"><SettingsIcon size={24} className="text-slate-400"/>設定詳細</h2></div>
           <div className="p-5 space-y-8 overflow-y-auto pb-32">
             <section className="space-y-3">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">カスタマイズ</h3>
                <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                   <button onClick={() => setShowCustomizeModal(true)} className="w-full p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                     <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-emerald-50 text-emerald-600 rounded-xl"><SlidersHorizontal size={20}/></div>
                        <div className="text-left"><p className="font-bold text-slate-800">表示のカスタマイズ</p><p className="text-xs text-slate-500 font-medium">単位やタイミングの選択肢を編集</p></div>
                     </div>
                     <ChevronRight size={20} className="text-slate-300" />
                   </button>
                </div>
             </section>
             <section className="space-y-3">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">データ管理</h3>
                <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden divide-y divide-slate-50">
                   <button onClick={() => { const data = JSON.stringify({ medications, logs }, null, 2); const blob = new Blob([data], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `medimate_backup_${format(new Date(), 'yyyyMMdd')}.json`; a.click(); }} className="w-full p-4 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
                      <div className="p-2.5 bg-blue-50 text-blue-500 rounded-xl"><Database size={20}/></div>
                      <div><p className="font-bold text-slate-800">バックアップを保存</p><p className="text-xs text-slate-500 font-medium">現在のデータをJSONでダウンロード</p></div>
                   </button>
                   <button onClick={() => { if(window.confirm('すべてのデータを削除して初期化しますか？')) { localStorage.clear(); setMedications([]); setLogs([]); alert('初期化しました'); } }} className="w-full p-4 flex items-center gap-3 hover:bg-red-50 transition-colors text-left">
                      <div className="p-2.5 bg-red-50 text-red-500 rounded-xl"><RotateCcw size={20}/></div>
                      <div><p className="font-bold text-red-600">データを初期化</p><p className="text-xs text-slate-500 font-medium">記録を消去する</p></div>
                   </button>
                </div>
             </section>
             <div className="text-center pt-8 pb-4"><p className="text-xs font-bold text-slate-300">MediMate v1.4.0 (OCR Support)</p></div>
           </div>
         </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {/* Hidden File Input for Scan */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={onFileChange} 
        accept="image/*" 
        capture="environment" 
        className="hidden" 
      />

      {/* Loading Overlay */}
      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
          <Loader2 size={48} className="animate-spin mb-4 text-emerald-400" />
          <p className="text-lg font-bold">手帳を解析しています...</p>
          <p className="text-sm opacity-70">しばらくお待ちください</p>
        </div>
      )}

      {showAddMenu && <ActionMenu />}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={handleDeleteMed}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}

      {showCustomizeModal && <CustomizeModal />}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('week');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    // メニュー外クリックで閉じる
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      const duplicate = medications.find(m => m.title === med.title);
      if (duplicate) {
        if (window.confirm(`「${med.title}」は既に登録されています。在庫を更新しますか？`)) {
          setMedications(prev => prev.map(m => m.id === duplicate.id ? { 
            ...m, 
            stock: m.stock + med.stock, 
            lastUpdated: Date.now()
          } : m));
        }
      } else {
        setMedications(prev => [...prev, med]);
      }
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const performOCR = async (base64Image: string) => {
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "お薬手帳の情報（名前、1回の量、単位、タイミング）を抽出してください" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              dosage: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              label: { type: Type.STRING },
              stock: { type: Type.NUMBER },
              memo: { type: Type.STRING }
            },
            required: ["title", "dosage", "unit", "label"]
          }
        }
      });
      const extracted = JSON.parse(response.text || '{}');
      setEditingMed({
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || '',
        color: 'emerald',
        history: [{ id: crypto.randomUUID(), timestamp: Date.now(), type: 'scan', message: 'スキャンから登録' }]
      });
      setIsFormOpen(true);
    } catch (err) {
      alert('読み取りに失敗しました');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const ActionDropdown = () => (
    <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[60] animate-in fade-in slide-in-from-top-2 duration-200">
      <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors">
        <FileText size={18} className="text-emerald-500" />
        <span className="text-sm font-bold text-slate-700">手動で入力</span>
      </button>
      <button onClick={() => fileInputRef.current?.click()} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors">
        <Camera size={18} className="text-blue-500" />
        <span className="text-sm font-bold text-slate-700">手帳をスキャン</span>
      </button>
    </div>
  );

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">ホーム</h1></div>

      {/* Calendar Area */}
      <div className="bg-white shadow-sm px-5 pt-4 pb-4 border-b border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-extrabold text-slate-800">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
          <div className="flex bg-slate-100 rounded-lg p-1">
            {['week', 'month'].map((m: any) => (
              <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                {m === 'week' ? '週' : '月'}
              </button>
            ))}
          </div>
        </div>
        <div className="grid grid-cols-7 text-center">
          {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
          {(calendarMode === 'week' ? Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(displayDate), i)) : eachDayOfInterval({ start: startOfWeek(startOfMonth(displayDate)), end: endOfWeek(endOfMonth(displayDate)) })).map((day, idx) => (
            <button key={idx} onClick={() => { setSelectedDate(day); setDisplayDate(day); }} className={`flex flex-col items-center py-2 rounded-xl transition-all ${isSameDay(day, selectedDate) ? 'bg-emerald-500 text-white shadow-md' : 'hover:bg-slate-50'}`}>
              <span className="text-sm font-bold">{format(day, 'd')}</span>
              {medications.length > 0 && <div className={`w-1 h-1 rounded-full mt-1 ${isSameDay(day, selectedDate) ? 'bg-white' : 'bg-slate-300'}`}></div>}
            </button>
          ))}
        </div>
      </div>

      {/* Task List Header */}
      <div className="px-4 py-6 flex items-center justify-between">
        <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の予定</h3>
        <div className="relative" ref={menuRef}>
          <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-sm shadow-lg shadow-emerald-100 flex items-center gap-1 active:scale-95 transition-all">
            <Plus size={16} strokeWidth={3} /> 追加
          </button>
          {showAddMenu && <ActionDropdown />}
        </div>
      </div>

      {/* Med List */}
      <div className="flex-1 overflow-y-auto px-4 space-y-3 pb-32">
        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl border border-slate-100 text-slate-400 font-medium">お薬を登録しましょう</div>
        ) : (
          medications.map(med => (
            <div key={med.id} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100'}`}>
              <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${isCompleted(med.id, selectedDate) ? 'scale-100' : 'scale-0'}`} />
              </button>
              <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(showDetailId === med.id ? null : med.id)}>
                <div className="flex justify-between items-start">
                  <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                </div>
                <div className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</div>
                {showDetailId === med.id && (
                  <div className="mt-3 pt-3 border-t border-slate-50 flex gap-2">
                    <button onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }} className="text-xs font-bold text-emerald-600 px-3 py-1.5 bg-emerald-50 rounded-lg">編集</button>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl overflow-hidden flex flex-col relative">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
              <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
              <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
                <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
                  <Plus size={14} /> 追加
                </button>
                {showAddMenu && <ActionDropdown />}
              </div>
            </div>
            <div className="p-4 space-y-3 overflow-y-auto pb-32">
              {medications.map(med => (
                <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="font-bold text-slate-800">{med.title}</h3>
                      <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
                    </div>
                    <div className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit} / 1回: {med.dosage}{med.unit}</div>
                  </div>
                  <ChevronRight size={18} className="text-slate-300" />
                </div>
              ))}
            </div>
          </div>
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => setShowCustomizeModal(true)} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-slate-700">
                <div className="flex items-center gap-3"><SlidersHorizontal size={20} className="text-slate-400" /> 表示設定</div>
                <ChevronRight size={18} />
              </button>
              <button onClick={() => { if(window.confirm('初期化しますか？')) { localStorage.clear(); location.reload(); } }} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-red-500">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      <input type="file" ref={fileInputRef} onChange={(e) => { const file = e.target.files?.[0]; if(file) { const reader = new FileReader(); reader.onloadend = () => performOCR(reader.result?.toString().split(',')[1] || ''); reader.readAsDataURL(file); } }} accept="image/*" capture="environment" className="hidden" />

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">お薬手帳を解析中...</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  // デフォルトを 'month' に変更
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      const duplicate = medications.find(m => m.title === med.title);
      if (duplicate) {
        if (window.confirm(`「${med.title}」は既に登録されています。在庫を更新しますか？`)) {
          setMedications(prev => prev.map(m => m.id === duplicate.id ? { 
            ...m, 
            stock: m.stock + med.stock, 
            lastUpdated: Date.now()
          } : m));
        }
      } else {
        setMedications(prev => [...prev, med]);
      }
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    const offset = direction === 'next' ? 1 : -1;
    if (calendarMode === 'day') {
      const newDate = addDays(selectedDate, offset);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(addWeeks(displayDate, offset));
    } else {
      setDisplayDate(addMonths(displayDate, offset));
    }
  };

  const performOCR = async (base64Image: string) => {
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "抽出: 名前, 量(数値), 単位, タイミング" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              dosage: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              label: { type: Type.STRING },
              stock: { type: Type.NUMBER },
              memo: { type: Type.STRING }
            },
            required: ["title", "dosage", "unit", "label"]
          }
        }
      });
      const extracted = JSON.parse(response.text || '{}');
      setEditingMed({
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || '',
        color: 'emerald',
        history: [{ id: crypto.randomUUID(), timestamp: Date.now(), type: 'scan', message: 'スキャンから登録' }]
      });
      setIsFormOpen(true);
    } catch (err) {
      alert('読み取りに失敗しました');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const ActionDropdown = () => (
    <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2 duration-200">
      <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors">
        <FileText size={18} className="text-emerald-500" />
        <span className="text-sm font-bold text-slate-700">手動で入力</span>
      </button>
      <button onClick={() => fileInputRef.current?.click()} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors">
        <Camera size={18} className="text-blue-500" />
        <span className="text-sm font-bold text-slate-700">手帳をスキャン</span>
      </button>
    </div>
  );

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      {/* Home Header with Add Button */}
      <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
        <h1 className="text-center font-bold text-slate-800">ホーム</h1>
        <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
          <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
            <Plus size={14} strokeWidth={3} /> 追加
          </button>
          {showAddMenu && <ActionDropdown />}
        </div>
      </div>

      {/* Calendar Area */}
      <div className="bg-white shadow-sm px-5 pt-4 pb-4 border-b border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-extrabold text-slate-800">
            {calendarMode === 'day' ? format(selectedDate, 'M月 d日 (EE)', { locale: ja }) : format(displayDate, 'yyyy年 M月', { locale: ja })}
          </h2>
          <div className="flex bg-slate-100 rounded-lg p-1">
            {['month', 'week', 'day'].map((m: any) => (
              <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
              </button>
            ))}
          </div>
        </div>

        <div className="flex justify-between items-center mb-2">
          <button onClick={() => handleCalendarNavigate('prev')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronLeft size={20}/></button>
          {calendarMode !== 'month' && <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">今日</button>}
          <button onClick={() => handleCalendarNavigate('next')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronRight size={20}/></button>
        </div>

        {calendarMode === 'day' ? (
          <div className="flex justify-center py-4">
            <div className="text-center animate-in zoom-in-95 duration-200">
              <div className="text-4xl font-black text-slate-800 tracking-tighter">{format(selectedDate, 'd')}</div>
              <div className="text-sm font-bold text-slate-400">{format(selectedDate, 'EEEE', { locale: ja })}</div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {(calendarMode === 'week' 
              ? Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(displayDate), i)) 
              : eachDayOfInterval({ start: startOfWeek(startOfMonth(displayDate)), end: endOfWeek(endOfMonth(displayDate)) })
            ).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = format(day, 'M') === format(displayDate, 'M') || calendarMode === 'week';

              return (
                <button 
                  key={idx} 
                  onClick={() => { setSelectedDate(day); if (calendarMode === 'month') setDisplayDate(day); }} 
                  className={`flex flex-col items-center py-2 rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md z-10' : 'hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-20' : ''}`}
                >
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  {medications.length > 0 && isCurrentMonth && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                </button>
              );
            })}
          </div>
        )}
      </div>

      {/* Task List Header */}
      <div className="px-4 py-6">
        <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の予定</h3>
      </div>

      {/* Med List */}
      <div className="flex-1 overflow-y-auto px-4 space-y-3 pb-32">
        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl border border-slate-100 text-slate-400 font-medium">
            <div className="bg-slate-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-3"><Pill className="text-slate-200" size={24}/></div>
            お薬を登録しましょう
          </div>
        ) : (
          medications.map(med => (
            <div key={med.id} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100'}`}>
              <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${isCompleted(med.id, selectedDate) ? 'scale-100' : 'scale-0'}`} />
              </button>
              <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(showDetailId === med.id ? null : med.id)}>
                <div className="flex justify-between items-start">
                  <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                </div>
                <div className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</div>
                {showDetailId === med.id && (
                  <div className="mt-3 pt-3 border-t border-slate-50 flex gap-2 animate-in fade-in slide-in-from-top-1">
                    <button onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }} className="text-xs font-bold text-emerald-600 px-3 py-1.5 bg-emerald-50 rounded-lg">編集</button>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl overflow-hidden flex flex-col relative">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
              <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
              <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
                <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
                  <Plus size={14} /> 追加
                </button>
                {showAddMenu && <ActionDropdown />}
              </div>
            </div>
            <div className="p-4 space-y-3 overflow-y-auto pb-32">
              {medications.length === 0 ? (
                 <div className="text-center py-20 text-slate-400 font-medium">登録されたお薬はありません</div>
              ) : (
                medications.map(med => (
                  <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-bold text-slate-800">{med.title}</h3>
                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
                      </div>
                      <div className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit} / 1回: {med.dosage}{med.unit}</div>
                    </div>
                    <ChevronRight size={18} className="text-slate-300" />
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => setShowCustomizeModal(true)} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-slate-700 active:bg-slate-50 transition-colors">
                <div className="flex items-center gap-3"><SlidersHorizontal size={20} className="text-slate-400" /> 表示設定</div>
                <ChevronRight size={18} />
              </button>
              <button onClick={() => { if(window.confirm('すべてのデータをリセットしますか？')) { localStorage.clear(); location.reload(); } }} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-red-500 active:bg-red-50 transition-colors">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={(e) => { 
          const file = e.target.files?.[0]; 
          if(file) { 
            const reader = new FileReader(); 
            reader.onloadend = () => performOCR(reader.result?.toString().split(',')[1] || ''); 
            reader.readAsDataURL(file); 
          } 
        }} 
        accept="image/*" 
        capture="environment" 
        className="hidden" 
      />

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">お薬手帳を解析中...</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { X, Camera, RefreshCw, AlertCircle } from 'lucide-react';

interface CameraModalProps {
  onCapture: (base64: string) => void;
  onCancel: () => void;
}

export const CameraModal: React.FC<CameraModalProps> = ({ onCapture, onCancel }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setIsReady(true);
        }
      } catch (err) {
        console.error("Camera access error:", err);
        setError("カメラにアクセスできませんでした。権限を許可してください。");
      }
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const takePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (context) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      context.drawImage(video, 0, 0, canvas.width, canvas.height);
      const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
      onCapture(base64);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-black flex flex-col items-center justify-center animate-in fade-in duration-200">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-center z-10 safe-top">
        <button onClick={onCancel} className="p-2 bg-black/50 text-white rounded-full backdrop-blur-md">
          <X size={24} />
        </button>
        <div className="bg-black/50 text-white px-3 py-1 rounded-full text-xs font-bold backdrop-blur-md">
          手帳を枠内に合わせてください
        </div>
        <div className="w-10"></div>
      </div>

      {/* Video Preview */}
      <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
        {error ? (
          <div className="p-8 text-center text-white">
            <AlertCircle size={48} className="mx-auto mb-4 text-red-500" />
            <p className="font-bold mb-4">{error}</p>
            <button onClick={onCancel} className="px-6 py-2 bg-white text-black rounded-full font-bold">戻る</button>
          </div>
        ) : (
          <>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              className="w-full h-full object-cover"
            />
            {/* Guide Frame */}
            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-[85%] aspect-[3/4] border-2 border-white/50 rounded-2xl shadow-[0_0_0_1000px_rgba(0,0,0,0.5)]"></div>
            </div>
          </>
        )}
      </div>

      {/* Shutter Button Container */}
      {isReady && !error && (
        <div className="absolute bottom-0 left-0 right-0 p-8 flex justify-center items-center safe-bottom">
          <button
            onClick={takePhoto}
            className="w-20 h-20 bg-white rounded-full flex items-center justify-center shadow-2xl active:scale-90 transition-transform"
          >
            <div className="w-16 h-16 border-4 border-slate-900 rounded-full flex items-center justify-center">
              <div className="w-12 h-12 bg-slate-900 rounded-full"></div>
            </div>
          </button>
        </div>
      )}

      {/* Hidden Canvas for capture */}
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      const duplicate = medications.find(m => m.title === med.title);
      if (duplicate) {
        if (window.confirm(`「${med.title}」は既に登録されています。在庫を更新しますか？`)) {
          setMedications(prev => prev.map(m => m.id === duplicate.id ? { 
            ...m, 
            stock: m.stock + med.stock, 
            lastUpdated: Date.now()
          } : m));
        }
      } else {
        setMedications(prev => [...prev, med]);
      }
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    const offset = direction === 'next' ? 1 : -1;
    if (calendarMode === 'day') {
      const newDate = addDays(selectedDate, offset);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(addWeeks(displayDate, offset));
    } else {
      setDisplayDate(addMonths(displayDate, offset));
    }
  };

  const performOCR = async (base64Image: string) => {
    setIsCameraOpen(false);
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "抽出: 名前, 量(数値), 単位, タイミング" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              dosage: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              label: { type: Type.STRING },
              stock: { type: Type.NUMBER },
              memo: { type: Type.STRING }
            },
            required: ["title", "dosage", "unit", "label"]
          }
        }
      });
      const extracted = JSON.parse(response.text || '{}');
      setEditingMed({
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || '',
        color: 'emerald',
        history: [{ id: crypto.randomUUID(), timestamp: Date.now(), type: 'scan', message: 'スキャンから登録' }]
      });
      setIsFormOpen(true);
    } catch (err) {
      alert('解析に失敗しました。もう一度お試しください。');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const ActionDropdown = () => (
    <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2 duration-200">
      <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <FileText size={18} className="text-emerald-500" />
        <span className="text-sm font-bold text-slate-700">手動で入力</span>
      </button>
      <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <Camera size={18} className="text-blue-500" />
        <span className="text-sm font-bold text-slate-700">手帳をスキャン</span>
      </button>
    </div>
  );

  const renderHome = () => (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
        <h1 className="text-center font-bold text-slate-800">ホーム</h1>
        <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
          <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
            <Plus size={14} strokeWidth={3} /> 追加
          </button>
          {showAddMenu && <ActionDropdown />}
        </div>
      </div>

      <div className="bg-white shadow-sm px-5 pt-4 pb-4 border-b border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-extrabold text-slate-800">
            {calendarMode === 'day' ? format(selectedDate, 'M月 d日 (EE)', { locale: ja }) : format(displayDate, 'yyyy年 M月', { locale: ja })}
          </h2>
          <div className="flex bg-slate-100 rounded-lg p-1">
            {['month', 'week', 'day'].map((m: any) => (
              <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
              </button>
            ))}
          </div>
        </div>

        <div className="flex justify-between items-center mb-2">
          <button onClick={() => handleCalendarNavigate('prev')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronLeft size={20}/></button>
          {calendarMode !== 'month' && <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">今日</button>}
          <button onClick={() => handleCalendarNavigate('next')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronRight size={20}/></button>
        </div>

        {calendarMode === 'day' ? (
          <div className="flex justify-center py-4">
            <div className="text-center animate-in zoom-in-95 duration-200">
              <div className="text-4xl font-black text-slate-800 tracking-tighter">{format(selectedDate, 'd')}</div>
              <div className="text-sm font-bold text-slate-400">{format(selectedDate, 'EEEE', { locale: ja })}</div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {(calendarMode === 'week' 
              ? Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(displayDate), i)) 
              : eachDayOfInterval({ start: startOfWeek(startOfMonth(displayDate)), end: endOfWeek(endOfMonth(displayDate)) })
            ).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = format(day, 'M') === format(displayDate, 'M') || calendarMode === 'week';

              return (
                <button 
                  key={idx} 
                  onClick={() => { setSelectedDate(day); if (calendarMode === 'month') setDisplayDate(day); }} 
                  className={`flex flex-col items-center py-2 rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md z-10' : 'hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-20' : ''}`}
                >
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  {medications.length > 0 && isCurrentMonth && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                </button>
              );
            })}
          </div>
        )}
      </div>

      <div className="px-4 py-6">
        <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の予定</h3>
      </div>

      <div className="flex-1 overflow-y-auto px-4 space-y-3 pb-32">
        {medications.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-3xl border border-slate-100 text-slate-400 font-medium">
            <div className="bg-slate-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-3"><Pill className="text-slate-200" size={24}/></div>
            お薬を登録しましょう
          </div>
        ) : (
          medications.map(med => (
            <div key={med.id} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100'}`}>
              <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${isCompleted(med.id, selectedDate) ? 'scale-100' : 'scale-0'}`} />
              </button>
              <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(showDetailId === med.id ? null : med.id)}>
                <div className="flex justify-between items-start">
                  <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                </div>
                <div className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</div>
                {showDetailId === med.id && (
                  <div className="mt-3 pt-3 border-t border-slate-50 flex gap-2 animate-in fade-in slide-in-from-top-1">
                    <button onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }} className="text-xs font-bold text-emerald-600 px-3 py-1.5 bg-emerald-50 rounded-lg">編集</button>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl overflow-hidden flex flex-col relative">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
              <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
              <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
                <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
                  <Plus size={14} /> 追加
                </button>
                {showAddMenu && <ActionDropdown />}
              </div>
            </div>
            <div className="p-4 space-y-3 overflow-y-auto pb-32">
              {medications.length === 0 ? (
                 <div className="text-center py-20 text-slate-400 font-medium">登録されたお薬はありません</div>
              ) : (
                medications.map(med => (
                  <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-bold text-slate-800">{med.title}</h3>
                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
                      </div>
                      <div className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit} / 1回: {med.dosage}{med.unit}</div>
                    </div>
                    <ChevronRight size={18} className="text-slate-300" />
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => setShowCustomizeModal(true)} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-slate-700 active:bg-slate-50 transition-colors text-left">
                <div className="flex items-center gap-3"><SlidersHorizontal size={20} className="text-slate-400" /> 表示設定</div>
                <ChevronRight size={18} />
              </button>
              <button onClick={() => { if(window.confirm('すべてのデータをリセットしますか？')) { localStorage.clear(); location.reload(); } }} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-red-500 active:bg-red-50 transition-colors text-left">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && (
        <CameraModal
          onCapture={performOCR}
          onCancel={() => setIsCameraOpen(false)}
        />
      )}

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">お薬手帳を解析中...</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

