import React, { useRef, useEffect, useState } from 'react';
import { X, AlertCircle, RefreshCw } from 'lucide-react';

interface CameraModalProps {
  onCapture: (base64: string) => void;
  onCancel: () => void;
}

export const CameraModal: React.FC<CameraModalProps> = ({ onCapture, onCancel }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [retryCount, setRetryCount] = useState(0);

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      setError(null);
      setIsReady(false);

      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        setError("このブラウザまたは環境ではカメラを使用できません（HTTPS環境であることを確認してください）。");
        return;
      }

      try {
        // 1. まずは背面カメラを理想的な解像度で試行
        const constraints = {
          video: { 
            facingMode: { ideal: 'environment' },
            width: { ideal: 1920 },
            height: { ideal: 1080 }
          },
          audio: false
        };

        try {
          stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (e) {
          // 2. 失敗した場合は解像度指定を外して背面カメラのみで試行
          console.log("Retrying with simple facingMode...");
          stream = await navigator.mediaDevices.getUserMedia({ 
            video: { facingMode: 'environment' }, 
            audio: false 
          });
        }

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // メタデータが読み込まれるのを待ってから再生
          videoRef.current.onloadedmetadata = async () => {
            try {
              if (videoRef.current) {
                await videoRef.current.play();
                setIsReady(true);
              }
            } catch (playErr) {
              console.error("Video play error:", playErr);
              // 自動再生がブロックされた場合はユーザーの操作を待つ（またはここでReadyにする）
              setIsReady(true);
            }
          };
        }
      } catch (err: any) {
        console.error("Camera access error:", err);

        // 3. 最終的なフォールバック: カメラデバイスがあれば何でも開く
        try {
          console.log("Ultimate fallback...");
          stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
          if (videoRef.current) {
            videoRef.current.srcObject = stream;
            videoRef.current.onloadedmetadata = () => {
              videoRef.current?.play().then(() => setIsReady(true)).catch(() => setIsReady(true));
            };
          }
        } catch (retryErr: any) {
          if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
            setError("カメラの利用が許可されていません。ブラウザの設定でカメラを許可してください。");
          } else if (err.name === 'NotFoundError') {
            setError("カメラが見つかりませんでした。デバイスにカメラが接続されているか確認してください。");
          } else {
            setError(`カメラの起動に失敗しました (${err.name}): ${err.message || '不明なエラー'}`);
          }
        }
      }
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [retryCount]);

  const takePhoto = () => {
    if (!videoRef.current || !canvasRef.current || !isReady) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (context) {
      // プレビューの実際のアスペクト比に合わせてキャンバスサイズを設定
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      context.drawImage(video, 0, 0, canvas.width, canvas.height);
      const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
      onCapture(base64);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-black flex flex-col items-center justify-center animate-in fade-in duration-200">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-center z-20 safe-top">
        <button onClick={onCancel} className="p-2 bg-black/50 text-white rounded-full backdrop-blur-md">
          <X size={24} />
        </button>
        <div className="bg-black/50 text-white px-4 py-1.5 rounded-full text-xs font-bold backdrop-blur-md">
          {error ? 'エラー' : '手帳をスキャン'}
        </div>
        <div className="w-10"></div>
      </div>

      {/* Video Preview */}
      <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
        {error ? (
          <div className="p-8 text-center text-white z-30 max-w-sm w-full">
            <div className="bg-slate-900/80 p-8 rounded-3xl backdrop-blur-lg border border-white/10 shadow-2xl">
              <div className="bg-red-500/20 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertCircle size={32} className="text-red-400" />
              </div>
              <p className="font-bold mb-8 text-sm leading-relaxed">{error}</p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={() => setRetryCount(prev => prev + 1)} 
                  className="w-full py-3.5 bg-white text-black rounded-xl font-bold flex items-center justify-center gap-2 active:scale-95 transition-transform"
                >
                  <RefreshCw size={18} /> 再試行する
                </button>
                <button 
                  onClick={onCancel} 
                  className="w-full py-3.5 bg-white/10 text-white rounded-xl font-bold active:scale-95 transition-transform"
                >
                  キャンセル
                </button>
              </div>
            </div>
          </div>
        ) : (
          <>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              className={`w-full h-full object-cover transition-opacity duration-700 ${isReady ? 'opacity-100' : 'opacity-0'}`}
            />
            {/* Guide Frame */}
            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-[85%] aspect-[3/4] border-2 border-white/50 rounded-2xl shadow-[0_0_0_2000px_rgba(0,0,0,0.6)]">
                {/* Scanner animation effect */}
                <div className={`absolute top-0 left-0 right-0 h-0.5 bg-emerald-400 shadow-[0_0_15px_rgba(52,211,153,0.8)] ${isReady ? 'animate-[scan_3s_ease-in-out_infinite]' : 'hidden'}`}></div>
              </div>
            </div>

            {!isReady && !error && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white/50 gap-4">
                <RefreshCw size={40} className="animate-spin text-emerald-400" />
                <p className="text-xs font-bold tracking-widest uppercase">Initializing Camera...</p>
              </div>
            )}
          </>
        )}
      </div>

      {/* Shutter Button Container */}
      {isReady && !error && (
        <div className="absolute bottom-0 left-0 right-0 p-12 flex flex-col items-center gap-6 z-20 safe-bottom">
          <p className="text-white/80 text-[10px] font-black tracking-[0.2em] uppercase bg-black/30 px-4 py-1.5 rounded-full backdrop-blur-sm">
            Align text inside frame
          </p>
          <button
            onClick={takePhoto}
            className="w-20 h-20 bg-white rounded-full flex items-center justify-center shadow-[0_0_30px_rgba(255,255,255,0.3)] active:scale-90 transition-transform p-1.5"
          >
            <div className="w-full h-full border-4 border-slate-900 rounded-full flex items-center justify-center">
              <div className="w-12 h-12 bg-slate-900 rounded-full"></div>
            </div>
          </button>
        </div>
      )}

      {/* Hidden Canvas for capture */}
      <canvas ref={canvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { X, AlertCircle, RefreshCw, Camera } from 'lucide-react';

interface CameraModalProps {
  onCapture: (base64: string) => void;
  onCancel: () => void;
}

export const CameraModal: React.FC<CameraModalProps> = ({ onCapture, onCancel }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isInitializing, setIsInitializing] = useState(false);

  const startCamera = useCallback(async () => {
    setError(null);
    setIsInitializing(true);
    setIsReady(false);

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("このブラウザではカメラを使用できません。Safari、Chrome等の最新版を使用し、HTTPS環境であることを確認してください。");
      setIsInitializing(false);
      return;
    }

    try {
      // 背面カメラを優先的にリクエスト
      const constraints = {
        video: { 
          facingMode: { ideal: 'environment' },
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        },
        audio: false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = async () => {
          try {
            if (videoRef.current) {
              await videoRef.current.play();
              setIsReady(true);
              setIsInitializing(false);
            }
          } catch (playErr) {
            console.error("Video play error:", playErr);
            setIsReady(true);
            setIsInitializing(false);
          }
        };
      }
    } catch (err: any) {
      console.error("Camera access error:", err);
      setIsInitializing(false);

      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError' || err.name === 'NotReadableError') {
        setError("カメラの使用が拒否されました。ブラウザのアドレスバーにある『Aa』や『鍵マーク』をタップして、カメラのアクセスを『許可』に設定してから再読み込みしてください。");
      } else if (err.name === 'NotFoundError') {
        setError("カメラが見つかりませんでした。");
      } else {
        setError(`カメラを起動できませんでした (${err.name})。設定を確認してください。`);
      }
    }
  }, []);

  // 初回表示時に一度試みるが、モバイルではユーザーアクションが必要な場合が多い
  useEffect(() => {
    startCamera();
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [startCamera]);

  const takePhoto = () => {
    if (!videoRef.current || !canvasRef.current || !isReady) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (context) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      context.drawImage(video, 0, 0, canvas.width, canvas.height);
      const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
      onCapture(base64);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-black flex flex-col items-center justify-center animate-in fade-in duration-200">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-center z-20 safe-top">
        <button onClick={onCancel} className="p-2 bg-black/50 text-white rounded-full backdrop-blur-md">
          <X size={24} />
        </button>
        <div className="bg-black/50 text-white px-4 py-1.5 rounded-full text-xs font-bold backdrop-blur-md">
          {error ? '権限エラー' : '手帳スキャン'}
        </div>
        <div className="w-10"></div>
      </div>

      {/* Video Preview */}
      <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
        {error ? (
          <div className="p-6 text-center text-white z-30 max-w-sm w-full">
            <div className="bg-slate-900/90 p-8 rounded-[32px] backdrop-blur-xl border border-white/10 shadow-2xl">
              <div className="bg-amber-500/20 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle size={32} className="text-amber-400" />
              </div>
              <h3 className="text-lg font-bold mb-3">カメラが使えません</h3>
              <p className="text-sm text-slate-300 mb-8 leading-relaxed">
                {error}
                <br/><br/>
                <span className="text-xs text-slate-400">※iPadの場合: 設定 > Safari > カメラ > 「許可」になっているか確認してください。</span>
              </p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={startCamera} 
                  className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold flex items-center justify-center gap-2 active:scale-95 transition-all shadow-lg shadow-emerald-900/20"
                >
                  {isInitializing ? <RefreshCw size={20} className="animate-spin" /> : <Camera size={20} />}
                  カメラを起動する
                </button>
                <button 
                  onClick={onCancel} 
                  className="w-full py-4 bg-white/10 text-white rounded-2xl font-bold active:scale-95 transition-all"
                >
                  キャンセル
                </button>
              </div>
            </div>
          </div>
        ) : (
          <>
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              className={`w-full h-full object-cover transition-opacity duration-700 ${isReady ? 'opacity-100' : 'opacity-0'}`}
            />
            {/* Guide Frame */}
            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-[85%] aspect-[3/4] border-2 border-white/40 rounded-3xl shadow-[0_0_0_2000px_rgba(0,0,0,0.6)]">
                {/* Scanner animation effect */}
                <div className={`absolute top-0 left-0 right-0 h-1 bg-emerald-400 shadow-[0_0_20px_rgba(52,211,153,1)] ${isReady ? 'animate-[scan_3s_ease-in-out_infinite]' : 'hidden'}`}></div>
              </div>
            </div>

            {!isReady && !error && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white/50 gap-6">
                <div className="relative">
                  <RefreshCw size={48} className="animate-spin text-emerald-500" />
                  <div className="absolute inset-0 bg-emerald-500 blur-2xl opacity-20 animate-pulse"></div>
                </div>
                <p className="text-[10px] font-black tracking-[0.3em] uppercase opacity-60">Connecting to Camera...</p>
              </div>
            )}
          </>
        )}
      </div>

      {/* Shutter Button Container */}
      {isReady && !error && (
        <div className="absolute bottom-0 left-0 right-0 p-12 flex flex-col items-center gap-6 z-20 safe-bottom">
          <div className="px-5 py-2 bg-black/40 rounded-full backdrop-blur-md border border-white/10">
            <p className="text-white text-[10px] font-bold tracking-widest uppercase">
              枠内にお薬手帳を合わせてください
            </p>
          </div>
          <button
            onClick={takePhoto}
            className="group relative w-20 h-20 active:scale-90 transition-all"
          >
            <div className="absolute inset-0 bg-white rounded-full blur-md opacity-20 group-active:opacity-40 transition-opacity"></div>
            <div className="relative w-full h-full bg-white rounded-full flex items-center justify-center p-1.5 shadow-2xl">
              <div className="w-full h-full border-[3px] border-slate-900 rounded-full flex items-center justify-center">
                <div className="w-12 h-12 bg-slate-900 rounded-full"></div>
              </div>
            </div>
          </button>
        </div>
      )}

      {/* Hidden Canvas for capture */}
      <canvas ref={canvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { X, AlertCircle, RefreshCw, Camera, Upload } from 'lucide-react';

interface CameraModalProps {
  onCapture: (base64: string) => void;
  onCancel: () => void;
}

export const CameraModal: React.FC<CameraModalProps> = ({ onCapture, onCancel }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isInitializing, setIsInitializing] = useState(false);

  const startCamera = useCallback(async () => {
    setError(null);
    setIsInitializing(true);
    setIsReady(false);

    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setError("この環境ではブラウザの直接カメラ操作が制限されています。「標準カメラで撮影」をお試しください。");
      setIsInitializing(false);
      return;
    }

    try {
      const constraints = {
        video: { 
          facingMode: { ideal: 'environment' },
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = async () => {
          try {
            if (videoRef.current) {
              await videoRef.current.play();
              setIsReady(true);
              setIsInitializing(false);
            }
          } catch (playErr) {
            console.error("Video play error:", playErr);
            setIsReady(true);
            setIsInitializing(false);
          }
        };
      }
    } catch (err: any) {
      console.error("Camera access error:", err);
      setIsInitializing(false);

      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError' || err.name === 'SecurityError') {
        setError("カメラのアクセスがブロックされています。プレビュー環境の制約、または端末の設定が原因です。下の「標準カメラで撮影」ボタンをお試しください。");
      } else {
        setError(`カメラを起動できませんでした (${err.name})。`);
      }
    }
  }, []);

  useEffect(() => {
    // 初回は自動試行（許可されている場合のみ成功）
    startCamera();
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        const stream = videoRef.current.srcObject as MediaStream;
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [startCamera]);

  const handleNativeCamera = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result?.toString().split(',')[1];
        if (base64) onCapture(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const takePhoto = () => {
    if (!videoRef.current || !canvasRef.current || !isReady) return;
    const context = canvasRef.current.getContext('2d');
    if (context && videoRef.current) {
      canvasRef.current.width = videoRef.current.videoWidth;
      canvasRef.current.height = videoRef.current.videoHeight;
      context.drawImage(videoRef.current, 0, 0);
      const base64 = canvasRef.current.toDataURL('image/jpeg', 0.8).split(',')[1];
      onCapture(base64);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-black flex flex-col items-center justify-center animate-in fade-in duration-200">
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-center z-20 safe-top">
        <button onClick={onCancel} className="p-2 bg-black/50 text-white rounded-full backdrop-blur-md"><X size={24} /></button>
        <div className="bg-black/50 text-white px-4 py-1.5 rounded-full text-xs font-bold backdrop-blur-md">
          {error ? '撮影オプション' : '手帳スキャン'}
        </div>
        <div className="w-10"></div>
      </div>

      <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
        {error ? (
          <div className="p-6 text-center text-white z-30 max-w-sm w-full">
            <div className="bg-slate-900/95 p-8 rounded-[32px] backdrop-blur-xl border border-white/10 shadow-2xl">
              <div className="bg-amber-500/20 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle size={32} className="text-amber-400" />
              </div>
              <h3 className="text-lg font-bold mb-3">カメラの制限</h3>
              <p className="text-sm text-slate-300 mb-8 leading-relaxed">
                ブラウザによる直接のカメラ制御ができません。OS標準のカメラ機能（ファイル選択）を使用してください。
              </p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-bold flex items-center justify-center gap-2 active:scale-95 transition-all shadow-lg"
                >
                  <Camera size={20} />
                  標準カメラで撮影する
                </button>
                <button 
                  onClick={startCamera} 
                  className="w-full py-3 text-slate-400 text-xs font-bold hover:text-white transition-colors"
                >
                  ブラウザカメラを再試行
                </button>
                <button 
                  onClick={onCancel} 
                  className="w-full py-4 bg-white/5 text-white rounded-2xl font-bold active:scale-95 transition-all mt-2"
                >
                  キャンセル
                </button>
              </div>
            </div>
          </div>
        ) : (
          <>
            <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover transition-opacity duration-700 ${isReady ? 'opacity-100' : 'opacity-0'}`} />
            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-[85%] aspect-[3/4] border-2 border-white/40 rounded-3xl shadow-[0_0_0_2000px_rgba(0,0,0,0.6)]">
                <div className={`absolute top-0 left-0 right-0 h-1 bg-emerald-400 shadow-[0_0_20px_rgba(52,211,153,1)] ${isReady ? 'animate-[scan_3s_ease-in-out_infinite]' : 'hidden'}`}></div>
              </div>
            </div>
            {!isReady && !error && (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-white/50 gap-6">
                <RefreshCw size={48} className="animate-spin text-emerald-500" />
                <p className="text-[10px] font-black tracking-[0.3em] uppercase opacity-60">Initializing Camera...</p>
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className="mt-8 px-6 py-3 bg-white/10 rounded-full text-xs font-bold text-white backdrop-blur-md"
                >
                  起動しない場合はこちら（標準カメラ）
                </button>
              </div>
            )}
          </>
        )}
      </div>

      <input type="file" ref={fileInputRef} onChange={handleNativeCamera} accept="image/*" capture="environment" className="hidden" />

      {isReady && !error && (
        <div className="absolute bottom-0 left-0 right-0 p-12 flex flex-col items-center gap-6 z-20 safe-bottom">
          <button onClick={takePhoto} className="group relative w-20 h-20 active:scale-90 transition-all">
            <div className="absolute inset-0 bg-white rounded-full blur-md opacity-20"></div>
            <div className="relative w-full h-full bg-white rounded-full flex items-center justify-center p-1.5 shadow-2xl">
              <div className="w-full h-full border-[3px] border-slate-900 rounded-full flex items-center justify-center">
                <div className="w-12 h-12 bg-slate-900 rounded-full"></div>
              </div>
            </div>
          </button>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          15% { opacity: 1; }
          85% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

import React, { useRef, useState } from 'react';
import { X, Camera, Image as ImageIcon, AlertCircle, Loader2 } from 'lucide-react';

interface CameraModalProps {
  onCapture: (base64: string) => void;
  onCancel: () => void;
}

export const CameraModal: React.FC<CameraModalProps> = ({ onCapture, onCancel }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsProcessing(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result?.toString().split(',')[1];
        if (base64) {
          onCapture(base64);
        } else {
          setIsProcessing(false);
          alert("画像の読み込みに失敗しました。");
        }
      };
      reader.onerror = () => {
        setIsProcessing(false);
        alert("エラーが発生しました。");
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-slate-900 flex flex-col items-center justify-center p-6 animate-in fade-in duration-200">
      {/* Background Decor */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-[10%] -left-[10%] w-[50%] h-[50%] bg-emerald-500/10 blur-[120px] rounded-full"></div>
        <div className="absolute -bottom-[10%] -right-[10%] w-[50%] h-[50%] bg-blue-500/10 blur-[120px] rounded-full"></div>
      </div>

      {/* Close Button */}
      <div className="absolute top-0 right-0 p-4 z-20 safe-top">
        <button onClick={onCancel} className="p-3 bg-white/10 text-white rounded-full backdrop-blur-md active:scale-90 transition-transform">
          <X size={24} />
        </button>
      </div>

      <div className="w-full max-w-sm bg-white/5 backdrop-blur-2xl rounded-[48px] border border-white/10 p-10 shadow-2xl relative z-10 flex flex-col items-center text-center">
        {isProcessing ? (
          <div className="py-12 flex flex-col items-center">
            <Loader2 size={56} className="animate-spin text-emerald-400 mb-6" />
            <h3 className="text-xl font-bold text-white mb-2">読み込み中...</h3>
            <p className="text-slate-400 text-sm">画像を解析する準備をしています</p>
          </div>
        ) : (
          <>
            <div className="bg-gradient-to-br from-emerald-400 to-teal-600 w-20 h-20 rounded-3xl flex items-center justify-center mb-8 shadow-lg shadow-emerald-500/20">
              <Camera size={40} className="text-white" />
            </div>

            <h3 className="text-2xl font-black text-white mb-3 tracking-tight">お薬手帳のスキャン</h3>
            <p className="text-slate-400 text-sm mb-10 leading-relaxed">
              ブラウザの制約を回避するため、端末の標準機能を使用して撮影または選択してください。
            </p>

            <div className="w-full space-y-4">
              {/* Camera Button */}
              <button 
                onClick={() => fileInputRef.current?.click()} 
                className="w-full py-5 bg-white text-slate-900 rounded-[24px] font-bold flex items-center justify-center gap-3 active:scale-[0.97] transition-all shadow-xl"
              >
                <Camera size={24} />
                <span>今すぐ写真を撮る</span>
              </button>

              {/* Gallery Button */}
              <button 
                onClick={() => galleryInputRef.current?.click()} 
                className="w-full py-5 bg-white/10 text-white rounded-[24px] font-bold flex items-center justify-center gap-3 active:scale-[0.97] transition-all border border-white/10"
              >
                <ImageIcon size={22} className="text-emerald-400" />
                <span>ライブラリから選択</span>
              </button>
            </div>

            <div className="mt-12 flex items-start gap-3 p-4 bg-emerald-500/5 rounded-2xl border border-emerald-500/10 text-left">
              <AlertCircle size={16} className="text-emerald-400 shrink-0 mt-0.5" />
              <p className="text-[11px] leading-relaxed text-slate-400">
                <span className="text-emerald-400 font-bold">ヒント:</span> 名前や用量がはっきり写るように撮影してください。影が入らないように明るい場所がおすすめです。
              </p>
            </div>
          </>
        )}
      </div>

      {/* Native Capture Input (Forces Camera) */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*" 
        capture="environment" 
        className="hidden" 
      />

      {/* Native File Input (Picker) */}
      <input 
        type="file" 
        ref={galleryInputRef} 
        onChange={handleFileChange} 
        accept="image/*" 
        className="hidden" 
      />
    </div>
  );
};

