// Scrollable Wheel Component
const ScrollWheel: React.FC<{ 
  items: number[]; 
  value: number; 
  onChange: (val: number) => void;
  format?: (val: number) => string;
}> = ({ items, value, onChange, format }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const highlightListRef = useRef<HTMLDivElement>(null);

  const ITEM_HEIGHT = 40;
  const CONTAINER_HEIGHT = 160;
  const PADDING = (CONTAINER_HEIGHT - ITEM_HEIGHT) / 2;

  useEffect(() => {
    if (containerRef.current) {
      const index = items.indexOf(value);
      if (index !== -1) {
        containerRef.current.scrollTop = index * ITEM_HEIGHT;
        if (highlightListRef.current) {
          highlightListRef.current.style.transform = `translateY(-${index * ITEM_HEIGHT}px)`;
        }
      }
    }
  }, []);

  const handleScroll = () => {
    if (containerRef.current && highlightListRef.current) {
      const scrollTop = containerRef.current.scrollTop;
      highlightListRef.current.style.transform = `translateY(-${scrollTop}px)`;
      const index = Math.round(scrollTop / ITEM_HEIGHT);
      if (items[index] !== undefined && items[index] !== value) {
        onChange(items[index]);
      }
    }
  };

  return (
    <div className="relative h-[160px] w-20 overflow-hidden select-none">
      <div 
        ref={containerRef}
        onScroll={handleScroll}
        className="h-full overflow-y-auto no-scrollbar snap-y snap-mandatory"
        style={{ paddingTop: PADDING, paddingBottom: PADDING }}
      >
        {items.map((item) => (
          <div 
            key={item} 
            className="h-[40px] flex items-center justify-center snap-center text-xl font-medium text-slate-300"
          >
            {format ? format(item) : item}
          </div>
        ))}
      </div>
      <div 
        className="absolute left-0 right-0 pointer-events-none overflow-hidden"
        style={{ top: PADDING, height: ITEM_HEIGHT }}
      >
        <div ref={highlightListRef} className="w-full">
           {items.map((item) => (
            <div 
              key={item} 
              className="h-[40px] flex items-center justify-center text-xl font-bold text-slate-900"
            >
              {format ? format(item) : item}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

