import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths, differenceInCalendarDays, startOfDay } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showCustomizeModal, setShowCustomizeModal] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  // 特定の日にお薬を表示すべきかどうかを判定
  const shouldShowMedicationOnDate = (med: Medication, targetDate: Date) => {
    const label = med.label;
    // 「N日にM回」というパターンを抽出
    const customMatch = label.match(/(\d+)日に(\d+)回/);

    if (customMatch) {
      const intervalDays = parseInt(customMatch[1]);
      const startDate = startOfDay(new Date(med.startDate));
      const target = startOfDay(targetDate);

      // 開始日より前の日付には表示しない
      if (target < startDate) return false;

      const diffDays = differenceInCalendarDays(target, startDate);
      // 周期の倍数日かどうかをチェック
      return diffDays % intervalDays === 0;
    }

    // 通常のラベルは毎日表示
    return true;
  };

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      const duplicate = medications.find(m => m.title === med.title);
      if (duplicate) {
        if (window.confirm(`「${med.title}」は既に登録されています。在庫を更新しますか？`)) {
          setMedications(prev => prev.map(m => m.id === duplicate.id ? { 
            ...m, 
            stock: m.stock + med.stock, 
            lastUpdated: Date.now()
          } : m));
        }
      } else {
        setMedications(prev => [...prev, med]);
      }
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    const offset = direction === 'next' ? 1 : -1;
    if (calendarMode === 'day') {
      const newDate = addDays(selectedDate, offset);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(addWeeks(displayDate, offset));
    } else {
      setDisplayDate(addMonths(displayDate, offset));
    }
  };

  const performOCR = async (base64Image: string) => {
    setIsCameraOpen(false);
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "抽出: 名前, 量(数値), 単位, タイミング" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              dosage: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              label: { type: Type.STRING },
              stock: { type: Type.NUMBER },
              memo: { type: Type.STRING }
            },
            required: ["title", "dosage", "unit", "label"]
          }
        }
      });
      const extracted = JSON.parse(response.text || '{}');
      const now = Date.now();
      setEditingMed({
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || '',
        color: 'emerald',
        startDate: now,
        history: [{ id: crypto.randomUUID(), timestamp: now, type: 'scan', message: 'スキャンから登録' }]
      });
      setIsFormOpen(true);
    } catch (err) {
      alert('解析に失敗しました。もう一度お試しください。');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const ActionDropdown = () => (
    <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2 duration-200">
      <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <FileText size={18} className="text-emerald-500" />
        <span className="text-sm font-bold text-slate-700">手動で入力</span>
      </button>
      <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <Camera size={18} className="text-blue-500" />
        <span className="text-sm font-bold text-slate-700">手帳をスキャン</span>
      </button>
    </div>
  );

  const renderHome = () => {
    const scheduledMeds = medications.filter(m => shouldShowMedicationOnDate(m, selectedDate));

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
          <h1 className="text-center font-bold text-slate-800">ホーム</h1>
          <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
            <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
              <Plus size={14} strokeWidth={3} /> 追加
            </button>
            {showAddMenu && <ActionDropdown />}
          </div>
        </div>

        <div className="bg-white shadow-sm px-5 pt-4 pb-4 border-b border-slate-100">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800">
              {calendarMode === 'day' ? format(selectedDate, 'M月 d日 (EE)', { locale: ja }) : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex bg-slate-100 rounded-lg p-1">
              {['month', 'week', 'day'].map((m: any) => (
                <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                  {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                </button>
              ))}
            </div>
          </div>

          <div className="flex justify-between items-center mb-2">
            <button onClick={() => handleCalendarNavigate('prev')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronLeft size={20}/></button>
            {calendarMode !== 'month' && <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">今日</button>}
            <button onClick={() => handleCalendarNavigate('next')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronRight size={20}/></button>
          </div>

          {calendarMode === 'day' ? (
            <div className="flex justify-center py-4">
              <div className="text-center animate-in zoom-in-95 duration-200">
                <div className="text-4xl font-black text-slate-800 tracking-tighter">{format(selectedDate, 'd')}</div>
                <div className="text-sm font-bold text-slate-400">{format(selectedDate, 'EEEE', { locale: ja })}</div>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-7 text-center">
              {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
              {(calendarMode === 'week' 
                ? Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(displayDate), i)) 
                : eachDayOfInterval({ start: startOfWeek(startOfMonth(displayDate)), end: endOfWeek(endOfMonth(displayDate)) })
              ).map((day, idx) => {
                const isSelected = isSameDay(day, selectedDate);
                const isTodayDate = isToday(day);
                const isCurrentMonth = format(day, 'M') === format(displayDate, 'M') || calendarMode === 'week';

                // その日に飲むべきお薬があるか
                const hasMedicationsOnDay = medications.some(m => shouldShowMedicationOnDate(m, day));

                return (
                  <button 
                    key={idx} 
                    onClick={() => { setSelectedDate(day); if (calendarMode === 'month') setDisplayDate(day); }} 
                    className={`flex flex-col items-center py-2 rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md z-10' : 'hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-20' : ''}`}
                  >
                    <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                    {hasMedicationsOnDay && isCurrentMonth && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                  </button>
                );
              })}
            </div>
          )}
        </div>

        <div className="px-4 py-6">
          <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の予定</h3>
        </div>

        <div className="flex-1 overflow-y-auto px-4 space-y-3 pb-32">
          {scheduledMeds.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-3xl border border-slate-100 text-slate-400 font-medium">
              <div className="bg-slate-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-3"><Pill className="text-slate-200" size={24}/></div>
              {medications.length === 0 ? 'お薬を登録しましょう' : 'この日の服薬予定はありません'}
            </div>
          ) : (
            scheduledMeds.map(med => (
              <div key={med.id} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100'}`}>
                <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                  <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${isCompleted(med.id, selectedDate) ? 'scale-100' : 'scale-0'}`} />
                </button>
                <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(showDetailId === med.id ? null : med.id)}>
                  <div className="flex justify-between items-start">
                    <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                  </div>
                  <div className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</div>
                  {showDetailId === med.id && (
                    <div className="mt-3 pt-3 border-t border-slate-50 flex gap-2 animate-in fade-in slide-in-from-top-1">
                      <button onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }} className="text-xs font-bold text-emerald-600 px-3 py-1.5 bg-emerald-50 rounded-lg">編集</button>
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl overflow-hidden flex flex-col relative">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
              <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
              <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
                <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
                  <Plus size={14} /> 追加
                </button>
                {showAddMenu && <ActionDropdown />}
              </div>
            </div>
            <div className="p-4 space-y-3 overflow-y-auto pb-32">
              {medications.length === 0 ? (
                 <div className="text-center py-20 text-slate-400 font-medium">登録されたお薬はありません</div>
              ) : (
                medications.map(med => (
                  <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-bold text-slate-800">{med.title}</h3>
                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
                      </div>
                      <div className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit} / 1回: {med.dosage}{med.unit}</div>
                    </div>
                    <ChevronRight size={18} className="text-slate-300" />
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => setShowCustomizeModal(true)} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-slate-700 active:bg-slate-50 transition-colors text-left">
                <div className="flex items-center gap-3"><SlidersHorizontal size={20} className="text-slate-400" /> 表示設定</div>
                <ChevronRight size={18} />
              </button>
              <button onClick={() => { if(window.confirm('すべてのデータをリセットしますか？')) { localStorage.clear(); location.reload(); } }} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-red-500 active:bg-red-50 transition-colors text-left">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && (
        <CameraModal
          onCapture={performOCR}
          onCancel={() => setIsCameraOpen(false)}
        />
      )}

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">お薬手帳を解析中...</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths, differenceInCalendarDays, startOfDay, parse } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const shouldShowMedicationOnDate = (med: Medication, targetDate: Date) => {
    const label = med.label;
    const customMatch = label.match(/(\d+)日に(\d+)回/);

    if (customMatch) {
      const intervalDays = parseInt(customMatch[1]);
      const startDate = startOfDay(new Date(med.startDate));
      const target = startOfDay(targetDate);

      if (target < startDate) return false;
      const diffDays = differenceInCalendarDays(target, startDate);
      return diffDays % intervalDays === 0;
    }
    return true;
  };

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    const sameNameMed = medications.find(m => m.title === med.title && m.id !== med.id);

    if (existingIndex !== -1) {
      // 既存データの直接編集
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else if (sameNameMed) {
      // 同じ名前の別登録（スキャン等）の場合、既存データを優先して在庫のみ更新
      const updatedMed = {
        ...sameNameMed,
        stock: sameNameMed.stock + med.stock,
        lastUpdated: Date.now(),
        history: [
          ...(sameNameMed.history || []),
          { 
            id: crypto.randomUUID(), 
            timestamp: Date.now(), 
            type: 'update' as const, 
            message: `重複検知：在庫を${med.stock}${med.unit}追加しました。` 
          }
        ]
      };
      setMedications(prev => prev.map(m => m.id === sameNameMed.id ? updatedMed : m));
      alert(`「${med.title}」は既に登録されていたため、在庫を合算しました。`);
    } else {
      // 新規登録
      setMedications(prev => [...prev, med]);
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    const offset = direction === 'next' ? 1 : -1;
    if (calendarMode === 'day') {
      const newDate = addDays(selectedDate, offset);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(addWeeks(displayDate, offset));
    } else {
      setDisplayDate(addMonths(displayDate, offset));
    }
  };

  const performOCR = async (base64Image: string) => {
    setIsCameraOpen(false);
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "処方箋またはお薬手帳から抽出: 名前, 量(数値), 単位, タイミング, 在庫(全量), 処方日(YYYY-MM-DD)" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              dosage: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              label: { type: Type.STRING },
              stock: { type: Type.NUMBER },
              prescribedDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
              memo: { type: Type.STRING }
            },
            required: ["title", "dosage", "unit", "label"]
          }
        }
      });
      const extracted = JSON.parse(response.text || '{}');
      const now = Date.now();

      // 処方日の解析（なければ今日）
      let startDate = now;
      if (extracted.prescribedDate) {
        try {
          startDate = parse(extracted.prescribedDate, 'yyyy-MM-dd', new Date()).getTime();
        } catch (e) {
          startDate = now;
        }
      }

      setEditingMed({
        id: crypto.randomUUID(),
        title: extracted.title || '不明なお薬',
        dosage: Number(extracted.dosage) || 1,
        unit: (UNITS.includes(extracted.unit) ? extracted.unit : '錠') as any,
        label: extracted.label || '朝食後',
        stock: Number(extracted.stock) || 0,
        memo: extracted.memo || '',
        color: 'emerald',
        startDate: startDate,
        history: [{ id: crypto.randomUUID(), timestamp: now, type: 'scan', message: 'スキャンから登録' }]
      });
      setIsFormOpen(true);
    } catch (err) {
      alert('解析に失敗しました。もう一度お試しください。');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const ActionDropdown = () => (
    <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2 duration-200">
      <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <FileText size={18} className="text-emerald-500" />
        <span className="text-sm font-bold text-slate-700">手動で入力</span>
      </button>
      <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <Camera size={18} className="text-blue-500" />
        <span className="text-sm font-bold text-slate-700">手帳をスキャン</span>
      </button>
    </div>
  );

  const renderHome = () => {
    const scheduledMeds = medications.filter(m => shouldShowMedicationOnDate(m, selectedDate));

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
          <h1 className="text-center font-bold text-slate-800">ホーム</h1>
          <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
            <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
              <Plus size={14} strokeWidth={3} /> 追加
            </button>
            {showAddMenu && <ActionDropdown />}
          </div>
        </div>

        <div className="bg-white shadow-sm px-5 pt-4 pb-4 border-b border-slate-100">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800">
              {calendarMode === 'day' ? format(selectedDate, 'M月 d日 (EE)', { locale: ja }) : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex bg-slate-100 rounded-lg p-1">
              {['month', 'week', 'day'].map((m: any) => (
                <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                  {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                </button>
              ))}
            </div>
          </div>

          <div className="flex justify-between items-center mb-2">
            <button onClick={() => handleCalendarNavigate('prev')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronLeft size={20}/></button>
            {calendarMode !== 'month' && <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">今日</button>}
            <button onClick={() => handleCalendarNavigate('next')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronRight size={20}/></button>
          </div>

          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {(calendarMode === 'week' 
              ? Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(displayDate), i)) 
              : eachDayOfInterval({ start: startOfWeek(startOfMonth(displayDate)), end: endOfWeek(endOfMonth(displayDate)) })
            ).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = format(day, 'M') === format(displayDate, 'M') || calendarMode === 'week';
              const hasMedicationsOnDay = medications.some(m => shouldShowMedicationOnDate(m, day));

              return (
                <button 
                  key={idx} 
                  onClick={() => { setSelectedDate(day); if (calendarMode === 'month') setDisplayDate(day); }} 
                  className={`flex flex-col items-center py-2 rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md z-10' : 'hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-20' : ''}`}
                >
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  {hasMedicationsOnDay && isCurrentMonth && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                </button>
              );
            })}
          </div>
        </div>

        <div className="px-4 py-6">
          <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の予定</h3>
        </div>

        <div className="flex-1 overflow-y-auto px-4 space-y-3 pb-32">
          {scheduledMeds.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-3xl border border-slate-100 text-slate-400 font-medium">
              <div className="bg-slate-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-3"><Pill className="text-slate-200" size={24}/></div>
              {medications.length === 0 ? 'お薬を登録しましょう' : 'この日の服薬予定はありません'}
            </div>
          ) : (
            scheduledMeds.map(med => (
              <div key={med.id} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100'}`}>
                <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                  <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${isCompleted(med.id, selectedDate) ? 'scale-100' : 'scale-0'}`} />
                </button>
                <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(showDetailId === med.id ? null : med.id)}>
                  <div className="flex justify-between items-start">
                    <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                  </div>
                  <div className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</div>
                  {showDetailId === med.id && (
                    <div className="mt-3 pt-3 border-t border-slate-50 flex gap-2 animate-in fade-in slide-in-from-top-1">
                      <button onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }} className="text-xs font-bold text-emerald-600 px-3 py-1.5 bg-emerald-50 rounded-lg">編集</button>
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl overflow-hidden flex flex-col relative">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
              <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
              <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
                <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
                  <Plus size={14} /> 追加
                </button>
                {showAddMenu && <ActionDropdown />}
              </div>
            </div>
            <div className="p-4 space-y-3 overflow-y-auto pb-32">
              {medications.length === 0 ? (
                 <div className="text-center py-20 text-slate-400 font-medium">登録されたお薬はありません</div>
              ) : (
                medications.map(med => (
                  <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-bold text-slate-800">{med.title}</h3>
                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
                      </div>
                      <div className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit} / 1回: {med.dosage}{med.unit}</div>
                    </div>
                    <ChevronRight size={18} className="text-slate-300" />
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => { if(window.confirm('すべてのデータをリセットしますか？')) { localStorage.clear(); location.reload(); } }} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-red-500 active:bg-red-50 transition-colors text-left">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && (
        <CameraModal
          onCapture={performOCR}
          onCancel={() => setIsCameraOpen(false)}
        />
      )}

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">お薬手帳を解析中...</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

