          </div>

          {initialData?.history && initialData.history.length > 0 && (
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200">
              <div className="flex items-center gap-2 mb-3 text-slate-400">
                <History size={16} />
                <span className="text-xs font-bold uppercase tracking-wider">更新履歴</span>
              </div>
              <div className="space-y-3">
                {[...initialData.history].reverse().slice(0, 5).map(entry => (
                  <div key={entry.id} className="text-xs border-l-2 border-slate-100 pl-3 py-1">
                    <div className="text-slate-400 font-medium mb-0.5">{format(entry.timestamp, 'yyyy/MM/dd HH:mm', { locale: ja })}</div>
                    <div className="text-slate-700 font-bold">{entry.message}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {initialData && onDelete && (
            <button type="button" onClick={() => setShowDeleteModal(true)} className="w-full py-3.5 bg-red-50 text-red-600 rounded-xl font-bold text-lg hover:bg-red-100 active:scale-[0.98] transition-all flex justify-center items-center gap-2 shadow-sm border border-red-100 mt-8">
              <Trash2 size={24} strokeWidth={2.5} /> このお薬を削除
            </button>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/90 backdrop-blur-md border-t border-slate-200 p-4 pb-safe safe-bottom shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-50">
        <div className="max-w-md mx-auto">
          <button onClick={handleSubmit} className="w-full bg-emerald-600 text-white py-3.5 rounded-xl font-bold text-lg hover:bg-emerald-700 active:scale-[0.98] transition-all flex justify-center items-center gap-2 shadow-lg shadow-emerald-200">
            <Check size={24} strokeWidth={3} /> 保存する
          </button>
        </div>
      </div>

      {isTimePickerOpen && <TimePickerModal initialValue={notificationTime} onConfirm={(val) => { setNotificationTime(val); setIsTimePickerOpen(false); }} onCancel={() => setIsTimePickerOpen(false)} />}
      {isCustomTimingOpen && <CustomTimingModal onConfirm={(val) => { setLabel(val); setIsCustomTimingOpen(false); }} onCancel={() => setIsCustomTimingOpen(false)} />}
      {showDeleteModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-in fade-in duration-200">
            <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setShowDeleteModal(false)}></div>
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm p-6 relative z-10 animate-in zoom-in-95 duration-200">
                <h3 className="text-lg font-bold text-slate-900 mb-2">削除の確認</h3>
                <p className="text-slate-900 mb-6 font-medium">このお薬を削除します。<br/>よろしいですか？</p>
                <div className="flex gap-3">
                    <button onClick={() => setShowDeleteModal(false)} className="flex-1 py-3 rounded-xl font-bold text-slate-900 bg-slate-100 hover:bg-slate-200 transition-colors">キャンセル</button>
                    <button onClick={confirmDelete} className="flex-1 py-3 rounded-xl font-bold text-white bg-red-500 hover:bg-red-600 shadow-lg shadow-red-200 transition-colors">削除</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths, differenceInCalendarDays, startOfDay, parse } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showDetailId, setShowDetailId] = useState<string | null>(null);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const shouldShowMedicationOnDate = (med: Medication, targetDate: Date) => {
    const label = med.label;
    const customMatch = label.match(/(\d+)日に(\d+)回/);

    if (customMatch) {
      const intervalDays = parseInt(customMatch[1]);
      const startDate = startOfDay(new Date(med.startDate));
      const target = startOfDay(targetDate);

      if (target < startDate) return false;
      const diffDays = differenceInCalendarDays(target, startDate);
      return diffDays % intervalDays === 0;
    }
    return true;
  };

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    const sameNameMed = medications.find(m => m.title === med.title && m.id !== med.id);

    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else if (sameNameMed) {
      const updatedMed = {
        ...sameNameMed,
        stock: sameNameMed.stock + med.stock,
        lastUpdated: Date.now(),
        history: [
          ...(sameNameMed.history || []),
          { 
            id: crypto.randomUUID(), 
            timestamp: Date.now(), 
            type: 'update' as const, 
            message: `在庫更新：処方により${med.stock}${med.unit}追加しました。` 
          }
        ]
      };
      setMedications(prev => prev.map(m => m.id === sameNameMed.id ? updatedMed : m));
      alert(`「${med.title}」の在庫を更新しました。`);
    } else {
      setMedications(prev => [...prev, med]);
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    const offset = direction === 'next' ? 1 : -1;
    if (calendarMode === 'day') {
      const newDate = addDays(selectedDate, offset);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(addWeeks(displayDate, offset));
    } else {
      setDisplayDate(addMonths(displayDate, offset));
    }
  };

  const performOCR = async (base64Image: string) => {
    setIsCameraOpen(false);
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "処方箋またはお薬手帳の画像から、記載されているすべてのお薬を抽出してください。複数のお薬がある場合はその項目ごとに情報をまとめてください。抽出項目: 名前, 量(数値), 単位, タイミング, 在庫(処方された全量), 処方日(YYYY-MM-DD)" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                dosage: { type: Type.NUMBER },
                unit: { type: Type.STRING },
                label: { type: Type.STRING },
                stock: { type: Type.NUMBER },
                prescribedDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
                memo: { type: Type.STRING }
              },
              required: ["title", "dosage", "unit", "label"]
            }
          }
        }
      });

      const extractedItems = JSON.parse(response.text || '[]');
      if (!Array.isArray(extractedItems) || extractedItems.length === 0) {
        throw new Error('お薬が検出されませんでした。');
      }

      const now = Date.now();
      let updatedMeds = [...medications];
      let summary = { new: 0, updated: 0 };

      extractedItems.forEach((item: any) => {
        // 処方日の解析
        let startDate = now;
        if (item.prescribedDate) {
          try {
            startDate = parse(item.prescribedDate, 'yyyy-MM-dd', new Date()).getTime();
          } catch (e) {
            startDate = now;
          }
        }

        const sameNameIndex = updatedMeds.findIndex(m => m.title === item.title);

        if (sameNameIndex !== -1) {
          // 在庫の合算と履歴の追加
          const existing = updatedMeds[sameNameIndex];
          updatedMeds[sameNameIndex] = {
            ...existing,
            stock: existing.stock + (Number(item.stock) || 0),
            lastUpdated: now,
            history: [
              ...(existing.history || []),
              { 
                id: crypto.randomUUID(), 
                timestamp: now, 
                type: 'update', 
                message: `スキャン一括更新：在庫を${item.stock}${existing.unit}追加しました。` 
              }
            ]
          };
          summary.updated++;
        } else {
          // 新規登録
          const newMed: Medication = {
            id: crypto.randomUUID(),
            title: item.title || '不明なお薬',
            dosage: Number(item.dosage) || 1,
            unit: (UNITS.includes(item.unit) ? item.unit : '錠') as any,
            label: item.label || '朝食後',
            stock: Number(item.stock) || 0,
            memo: item.memo || '',
            color: 'emerald',
            startDate: startDate,
            history: [{ id: crypto.randomUUID(), timestamp: now, type: 'scan', message: 'スキャンから一括登録' }]
          };
          updatedMeds.push(newMed);
          summary.new++;
        }
      });

      setMedications(updatedMeds);
      alert(`${summary.new + summary.updated}件のお薬を処理しました。\n(新規登録: ${summary.new}件 / 在庫更新: ${summary.updated}件)`);

      // ホームまたは一覧へ
      if (view === 'home') setView('home'); 
      else setView('meds');

    } catch (err: any) {
      alert(err.message || '解析に失敗しました。もう一度お試しください。');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const ActionDropdown = () => (
    <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2 duration-200">
      <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <FileText size={18} className="text-emerald-500" />
        <span className="text-sm font-bold text-slate-700">手動で入力</span>
      </button>
      <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 transition-colors text-left">
        <Camera size={18} className="text-blue-500" />
        <span className="text-sm font-bold text-slate-700">手帳をスキャン</span>
      </button>
    </div>
  );

  const renderHome = () => {
    const scheduledMeds = medications.filter(m => shouldShowMedicationOnDate(m, selectedDate));

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
          <h1 className="text-center font-bold text-slate-800">ホーム</h1>
          <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
            <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
              <Plus size={14} strokeWidth={3} /> 追加
            </button>
            {showAddMenu && <ActionDropdown />}
          </div>
        </div>

        <div className="bg-white shadow-sm px-5 pt-4 pb-4 border-b border-slate-100">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-extrabold text-slate-800">
              {calendarMode === 'day' ? format(selectedDate, 'M月 d日 (EE)', { locale: ja }) : format(displayDate, 'yyyy年 M月', { locale: ja })}
            </h2>
            <div className="flex bg-slate-100 rounded-lg p-1">
              {['month', 'week', 'day'].map((m: any) => (
                <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                  {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                </button>
              ))}
            </div>
          </div>

          <div className="flex justify-between items-center mb-2">
            <button onClick={() => handleCalendarNavigate('prev')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronLeft size={20}/></button>
            {calendarMode !== 'month' && <button onClick={() => { const now = new Date(); setSelectedDate(now); setDisplayDate(now); }} className="text-[10px] font-bold text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">今日</button>}
            <button onClick={() => handleCalendarNavigate('next')} className="p-1 hover:bg-slate-50 rounded-full text-slate-400"><ChevronRight size={20}/></button>
          </div>

          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {(calendarMode === 'week' 
              ? Array.from({ length: 7 }).map((_, i) => addDays(startOfWeek(displayDate), i)) 
              : eachDayOfInterval({ start: startOfWeek(startOfMonth(displayDate)), end: endOfWeek(endOfMonth(displayDate)) })
            ).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const isCurrentMonth = format(day, 'M') === format(displayDate, 'M') || calendarMode === 'week';
              const hasMedicationsOnDay = medications.some(m => shouldShowMedicationOnDate(m, day));

              return (
                <button 
                  key={idx} 
                  onClick={() => { setSelectedDate(day); if (calendarMode === 'month') setDisplayDate(day); }} 
                  className={`flex flex-col items-center py-2 rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md z-10' : 'hover:bg-slate-50'} ${!isCurrentMonth ? 'opacity-20' : ''}`}
                >
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  {hasMedicationsOnDay && isCurrentMonth && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                </button>
              );
            })}
          </div>
        </div>

        <div className="px-4 py-6">
          <h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の予定</h3>
        </div>

        <div className="flex-1 overflow-y-auto px-4 space-y-3 pb-32">
          {scheduledMeds.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-3xl border border-slate-100 text-slate-400 font-medium">
              <div className="bg-slate-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-3"><Pill className="text-slate-200" size={24}/></div>
              {medications.length === 0 ? 'お薬を登録しましょう' : 'この日の服薬予定はありません'}
            </div>
          ) : (
            scheduledMeds.map(med => (
              <div key={med.id} className={`p-4 rounded-2xl border flex items-center gap-4 transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100'}`}>
                <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-300'}`}>
                  <Check size={28} strokeWidth={3} className={`transition-transform duration-300 ${isCompleted(med.id, selectedDate) ? 'scale-100' : 'scale-0'}`} />
                </button>
                <div className="flex-1 cursor-pointer" onClick={() => setShowDetailId(showDetailId === med.id ? null : med.id)}>
                  <div className="flex justify-between items-start">
                    <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                  </div>
                  <div className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</div>
                  {showDetailId === med.id && (
                    <div className="mt-3 pt-3 border-t border-slate-50 flex gap-2 animate-in fade-in slide-in-from-top-1">
                      <button onClick={(e) => { e.stopPropagation(); setEditingMed(med); setIsFormOpen(true); }} className="text-xs font-bold text-emerald-600 px-3 py-1.5 bg-emerald-50 rounded-lg">編集</button>
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl overflow-hidden flex flex-col relative">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
              <h1 className="text-center font-bold text-slate-800">お薬一覧</h1>
              <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
                <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
                  <Plus size={14} /> 追加
                </button>
                {showAddMenu && <ActionDropdown />}
              </div>
            </div>
            <div className="p-4 space-y-3 overflow-y-auto pb-32">
              {medications.length === 0 ? (
                 <div className="text-center py-20 text-slate-400 font-medium">登録されたお薬はありません</div>
              ) : (
                medications.map(med => (
                  <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 transition-colors cursor-pointer">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-bold text-slate-800">{med.title}</h3>
                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
                      </div>
                      <div className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit} / 1回: {med.dosage}{med.unit}</div>
                    </div>
                    <ChevronRight size={18} className="text-slate-300" />
                  </div>
                ))
              )}
            </div>
          </div>
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => { if(window.confirm('すべてのデータをリセットしますか？')) { localStorage.clear(); location.reload(); } }} className="w-full p-4 bg-white rounded-2xl border border-slate-100 flex items-center justify-between font-bold text-red-500 active:bg-red-50 transition-colors text-left">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && (
        <CameraModal
          onCapture={performOCR}
          onCancel={() => setIsCameraOpen(false)}
        />
      )}

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">お薬を解析・登録中...</p>
          <p className="text-xs text-white/60 mt-2">複数の項目を抽出しています</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

export default App;

export type ViewMode = 'home' | 'meds' | 'settings';
export type CalendarMode = 'month' | 'week' | 'day';

export type UnitType = 
  | '包' 
  | '個' 
  | '錠' 
  | 'カプセル' 
  | '漢方' 
  | '吸入' 
  | '注射' 
  | '塗り薬' 
  | '貼り薬' 
  | 'スプレー' 
  | 'mg' 
  | 'ml' 
  | '点眼薬';

export type LabelType = string;

export interface HistoryEntry {
  id: string;
  timestamp: number;
  type: 'manual' | 'scan' | 'update';
  message: string;
}

export interface Medication {
  id: string;
  title: string;
  unit: UnitType;
  dosage: number;
  label: LabelType;
  stock: number;
  memo: string;
  notificationTime?: string; // HH:mm
  color: string;
  history?: HistoryEntry[];
  lastUpdated?: number;
  startDate: number;

  // フォルダ機能用の追加フィールド
  isFolder: boolean;
  parentId?: string; // 親フォルダのID
  folderType?: 'multi-dose' | 'one-pack'; // 1日複数回用フォルダか、一包化用フォルダか
}

export interface MedicationLog {
  id: string;
  medicationId: string;
  timestamp: number; 
  dateStr: string; 
}

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths, differenceInCalendarDays, startOfDay, parse } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2, ChevronDown, FolderOpen, Package } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set());

  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const shouldShowMedicationOnDate = (med: Medication, targetDate: Date) => {
    // フォルダそのものは直接のタスクにはならない（子要素がある場合）
    if (med.isFolder) return false;

    const label = med.label;
    const customMatch = label.match(/(\d+)日に(\d+)回/);

    if (customMatch) {
      const intervalDays = parseInt(customMatch[1]);
      const startDate = startOfDay(new Date(med.startDate));
      const target = startOfDay(targetDate);

      if (target < startDate) return false;
      const diffDays = differenceInCalendarDays(target, startDate);
      return diffDays % intervalDays === 0;
    }
    return true;
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  // フォルダ内の全てのタスクが完了しているか
  const isFolderCompleted = (folderId: string, date: Date, scheduledMeds: Medication[]) => {
    const children = scheduledMeds.filter(m => m.parentId === folderId);
    if (children.length === 0) return false;
    return children.every(c => isCompleted(c.id, date));
  };

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      setMedications(prev => [...prev, med]);
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const performOCR = async (base64Image: string) => {
    setIsCameraOpen(false);
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "処方箋またはお薬手帳からすべてのお薬を抽出してください。複数回服用や一包化を考慮して構造化してください。同じ薬でタイミングが複数ある場合は同一グループとして扱い、一包化（1つの袋に複数種類）されている場合はその袋（一包化）をグループとして扱ってください。抽出: 名前, 量, 単位, タイミング, 在庫(全量), 処方日, 一包化フラグ(boolean), グループ名" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                dosage: { type: Type.NUMBER },
                unit: { type: Type.STRING },
                label: { type: Type.STRING },
                stock: { type: Type.NUMBER },
                prescribedDate: { type: Type.STRING },
                isOnePack: { type: Type.BOOLEAN },
                groupName: { type: Type.STRING, description: "同じ薬や一包化をまとめる名前（例：カロナール、朝の一包化など）" }
              },
              required: ["title", "dosage", "unit", "label", "groupName"]
            }
          }
        }
      });

      const extractedItems = JSON.parse(response.text || '[]');
      const now = Date.now();
      let newMeds = [...medications];

      // グループ名で分類
      const groups: Record<string, any[]> = {};
      extractedItems.forEach((item: any) => {
        const key = item.groupName;
        if (!groups[key]) groups[key] = [];
        groups[key].push(item);
      });

      Object.entries(groups).forEach(([groupName, items]) => {
        const isOnePack = items.some(i => i.isOnePack);
        const folderType = isOnePack ? 'one-pack' : 'multi-dose';

        // フォルダ作成
        const folderId = crypto.randomUUID();
        const folder: Medication = {
          id: folderId,
          title: groupName,
          unit: '錠', 
          dosage: 0,
          label: isOnePack ? items[0].label : '複数回',
          stock: 0,
          memo: isOnePack ? '一包化' : '1日複数回',
          color: 'emerald',
          startDate: now,
          isFolder: true,
          folderType
        };
        newMeds.push(folder);

        // 子アイテム作成
        items.forEach(item => {
          const startDate = item.prescribedDate ? parse(item.prescribedDate, 'yyyy-MM-dd', new Date()).getTime() : now;
          newMeds.push({
            id: crypto.randomUUID(),
            title: item.title,
            dosage: item.dosage,
            unit: item.unit as any,
            label: item.label,
            stock: item.stock,
            memo: '',
            color: 'emerald',
            startDate: startDate,
            isFolder: false,
            parentId: folderId
          });
        });
      });

      setMedications(newMeds);
      alert(`${extractedItems.length}件のお薬を解析・グループ化して登録しました。`);
    } catch (err) {
      alert('解析に失敗しました。');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const handleCalendarNavigate = (direction: 'prev' | 'next') => {
    const offset = direction === 'next' ? 1 : -1;
    if (calendarMode === 'day') {
      const newDate = addDays(selectedDate, offset);
      setSelectedDate(newDate);
      setDisplayDate(newDate);
    } else if (calendarMode === 'week') {
      setDisplayDate(addWeeks(displayDate, offset));
    } else {
      setDisplayDate(addMonths(displayDate, offset));
    }
  };

  const renderHome = () => {
    // 本日予定されている全「タスク用（isFolder=false）」お薬
    const scheduledMeds = medications.filter(m => shouldShowMedicationOnDate(m, selectedDate));

    // フォルダIDをキーとしたグループ化
    const folderGroups: Record<string, Medication[]> = {};
    const standaloneMeds: Medication[] = [];

    scheduledMeds.forEach(m => {
      if (m.parentId) {
        if (!folderGroups[m.parentId]) folderGroups[m.parentId] = [];
        folderGroups[m.parentId].push(m);
      } else {
        standaloneMeds.push(m);
      }
    });

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
          <h1 className="text-center font-bold text-slate-800">ホーム</h1>
          <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
            <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-all">
              <Plus size={14} /> 追加
            </button>
            {showAddMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2">
                <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                  <FileText size={18} className="text-emerald-500" /> 手動入力
                </button>
                <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                  <Camera size={18} className="text-blue-500" /> 手帳スキャン
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Calendar UI */}
        <div className="bg-white px-5 py-4 border-b border-slate-100">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-black text-slate-800">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
            <div className="flex bg-slate-100 rounded-lg p-1">
              {['month', 'week', 'day'].map((m: any) => (
                <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                  {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                </button>
              ))}
            </div>
          </div>
          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {eachDayOfInterval({ 
              start: calendarMode === 'week' ? startOfWeek(displayDate) : startOfWeek(startOfMonth(displayDate)), 
              end: calendarMode === 'week' ? addDays(startOfWeek(displayDate), 6) : endOfWeek(endOfMonth(displayDate)) 
            }).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const hasMed = medications.some(m => shouldShowMedicationOnDate(m, day));
              return (
                <button key={idx} onClick={() => setSelectedDate(day)} className={`flex flex-col items-center py-2 rounded-xl transition-all ${isSelected ? 'bg-emerald-500 text-white shadow-md' : 'hover:bg-slate-50'}`}>
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  {hasMed && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                </button>
              );
            })}
          </div>
        </div>

        <div className="px-4 py-4"><h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} のタスク</h3></div>

        <div className="flex-1 overflow-y-auto px-4 space-y-4 pb-32">
          {standaloneMeds.length === 0 && Object.keys(folderGroups).length === 0 ? (
            <div className="text-center py-12 text-slate-400 font-medium">予定はありません</div>
          ) : (
            <>
              {/* フォルダごとの表示 */}
              {Object.entries(folderGroups).map(([folderId, children]) => {
                const folder = medications.find(m => m.id === folderId);
                if (!folder) return null;
                const isOnePack = folder.folderType === 'one-pack';
                const isAllDone = isFolderCompleted(folderId, selectedDate, scheduledMeds);
                const isExpanded = expandedFolders.has(folderId);

                return (
                  <div key={folderId} className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                    {/* Folder Header */}
                    <div className={`p-4 flex items-center gap-4 transition-colors ${isAllDone ? 'bg-emerald-50/50' : 'bg-white'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isAllDone ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                        {isOnePack ? <Package size={24} /> : <FolderOpen size={24} />}
                      </div>
                      <div className="flex-1">
                        <h4 className={`font-bold text-lg ${isAllDone ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{folder.title}</h4>
                        <p className="text-xs text-slate-500 font-medium">
                          {isOnePack ? '一包化パッケージ' : `${children.length}つの服用タイミング`}
                        </p>
                      </div>
                      {!isOnePack && (
                        <button onClick={() => {
                          const newSet = new Set(expandedFolders);
                          if (isExpanded) newSet.delete(folderId);
                          else newSet.add(folderId);
                          setExpandedFolders(newSet);
                        }} className={`p-2 text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>
                          <ChevronDown size={20} />
                        </button>
                      )}
                      {isOnePack && (
                        <button 
                          onClick={() => children.forEach(c => toggleComplete(c.id, selectedDate))}
                          className={`w-10 h-10 rounded-xl flex items-center justify-center ${isAllDone ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300'}`}
                        >
                          <Check size={24} strokeWidth={3} />
                        </button>
                      )}
                    </div>

                    {/* Children for multi-dose (always shown if expanded) */}
                    {!isOnePack && isExpanded && (
                      <div className="bg-slate-50/50 border-t border-slate-50 px-4 py-2 space-y-2">
                        {children.map(child => (
                          <div key={child.id} className="flex items-center gap-3 py-2 border-b border-slate-100 last:border-0">
                            <button 
                              onClick={() => toggleComplete(child.id, selectedDate)}
                              className={`w-8 h-8 rounded-lg flex items-center justify-center ${isCompleted(child.id, selectedDate) ? 'bg-emerald-500 text-white' : 'bg-white border border-slate-200 text-slate-200'}`}
                            >
                              <Check size={18} strokeWidth={3} />
                            </button>
                            <div className="flex-1">
                              <span className={`text-sm font-bold ${isCompleted(child.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-700'}`}>
                                {child.label}
                              </span>
                            </div>
                            <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded border">{child.dosage}{child.unit}</span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}

              {/* スタンドアロンのお薬 */}
              {standaloneMeds.map(med => (
                <div key={med.id} className={`p-4 rounded-3xl border flex items-center gap-4 ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100 shadow-sm'}`}>
                  <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300'}`}>
                    <Check size={28} strokeWidth={3} />
                  </button>
                  <div className="flex-1" onClick={() => { setEditingMed(med); setIsFormOpen(true); }}>
                    <div className="flex justify-between items-start">
                      <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                    </div>
                    <p className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</p>
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      </div>
    );
  };

  const renderMeds = () => {
    // フォルダとお薬の分類
    const folders = medications.filter(m => m.isFolder);
    const orphanMeds = medications.filter(m => !m.isFolder && !m.parentId);

    const renderMedItem = (med: Medication) => (
      <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 cursor-pointer">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <h3 className="font-bold text-slate-800">{med.title}</h3>
            <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded border">{med.label}</span>
          </div>
          <p className="text-xs text-slate-500 font-medium">在庫: {med.stock}{med.unit}</p>
        </div>
        <ChevronRight size={18} className="text-slate-300" />
      </div>
    );

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative"><h1 className="text-center font-bold text-slate-800">お薬一覧</h1></div>
        <div className="p-4 space-y-4 overflow-y-auto pb-32">
          {/* Folders */}
          {folders.map(folder => (
            <div key={folder.id} className="space-y-2">
              <div className="flex items-center gap-2 px-1">
                {folder.folderType === 'one-pack' ? <Package size={16} className="text-emerald-500" /> : <FolderOpen size={16} className="text-emerald-500" />}
                <h2 className="text-sm font-black text-slate-400 uppercase tracking-widest">{folder.title}</h2>
              </div>
              <div className="space-y-2 pl-2 border-l-2 border-slate-200">
                {medications.filter(m => m.parentId === folder.id).map(renderMedItem)}
              </div>
            </div>
          ))}

          {/* Orpahns */}
          {orphanMeds.length > 0 && (
            <div className="space-y-2">
              <h2 className="text-sm font-black text-slate-400 uppercase tracking-widest px-1">その他</h2>
              {orphanMeds.map(renderMedItem)}
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl flex flex-col relative overflow-hidden">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && renderMeds()}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5"><button onClick={() => { if(window.confirm('全リセットしますか？')) { localStorage.clear(); location.reload(); }}} className="w-full p-4 bg-white rounded-2xl border border-red-100 flex items-center justify-between font-bold text-red-500 shadow-sm"><div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div></button></div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && <CameraModal onCapture={performOCR} onCancel={() => setIsCameraOpen(false)} />}
      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <Loader2 size={40} className="animate-spin mb-3 text-emerald-400" />
          <p className="font-bold">処方箋を解析中...</p>
        </div>
      )}
      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { setMedications(medications.filter(m => m.id !== id)); setIsFormOpen(false); }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { format, startOfWeek, addDays, isSameDay, startOfMonth, endOfMonth, endOfWeek, eachDayOfInterval, isToday, addWeeks, subWeeks, addMonths, subMonths, differenceInCalendarDays, startOfDay, parse } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight, Plus, Check, Pill, Archive, Bell, AlertCircle, Settings as SettingsIcon, Database, RotateCcw, SlidersHorizontal, X, Camera, FileText, Loader2, ChevronDown, FolderOpen, Package, MoreVertical, Edit2 } from 'lucide-react';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, CalendarMode } from './types';
import { LABEL_COLORS, WEEK_DAYS, UNITS, LABELS } from './constants';
import { GoogleGenAI, Type } from "@google/genai";

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [selectedDate, setSelectedDate] = useState(new Date()); 
  const [displayDate, setDisplayDate] = useState(new Date());   
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');

  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);

  const [visibleUnits, setVisibleUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleUnits');
    return saved ? JSON.parse(saved) : UNITS;
  });
  const [visibleLabels, setVisibleLabels] = useState<string[]>(() => {
    const saved = localStorage.getItem('visibleLabels');
    return saved ? JSON.parse(saved) : LABELS;
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);

  const [expandedFolders, setExpandedFolders] = useState<Set<string>>(new Set());

  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedMeds = localStorage.getItem('medications');
    const savedLogs = localStorage.getItem('logs');
    if (savedMeds) setMedications(JSON.parse(savedMeds));
    if (savedLogs) setLogs(JSON.parse(savedLogs));

    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowAddMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => { localStorage.setItem('medications', JSON.stringify(medications)); }, [medications]);
  useEffect(() => { localStorage.setItem('logs', JSON.stringify(logs)); }, [logs]);
  useEffect(() => { localStorage.setItem('visibleUnits', JSON.stringify(visibleUnits)); }, [visibleUnits]);
  useEffect(() => { localStorage.setItem('visibleLabels', JSON.stringify(visibleLabels)); }, [visibleLabels]);

  const shouldShowMedicationOnDate = (med: Medication, targetDate: Date) => {
    // フォルダそのものは、ホームのタスク判定には含めるが、表示ロジックは子要素を参照する
    const label = med.label;
    const customMatch = label.match(/(\d+)日に(\d+)回/);

    if (customMatch) {
      const intervalDays = parseInt(customMatch[1]);
      const startDate = startOfDay(new Date(med.startDate));
      const target = startOfDay(targetDate);

      if (target < startDate) return false;
      const diffDays = differenceInCalendarDays(target, startDate);
      return diffDays % intervalDays === 0;
    }
    return true;
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const toggleComplete = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    const existingLog = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existingLog) {
      setLogs(prev => prev.filter(l => l.id !== existingLog.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const isFolderAllDone = (folderId: string, date: Date, children: Medication[]) => {
    if (children.length === 0) return false;
    return children.every(c => isCompleted(c.id, date));
  };

  const handleSaveMed = (med: Medication) => {
    const existingIndex = medications.findIndex(m => m.id === med.id);
    if (existingIndex !== -1) {
      setMedications(prev => prev.map(m => m.id === med.id ? med : m));
    } else {
      setMedications(prev => [...prev, med]);
    }
    setIsFormOpen(false);
    setEditingMed(null);
  };

  const performOCR = async (base64Image: string) => {
    setIsCameraOpen(false);
    setIsScanning(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: "処方箋またはお薬手帳からすべてのお薬を抽出してください。複数回服用や一包化を考慮して構造化してください。同じ薬でタイミングが複数ある場合は同一グループとして扱い、一包化（1つの袋に複数種類）されている場合はその袋（一包化）をグループとして扱ってください。抽出: 名前, 量, 単位, タイミング, 在庫(全量), 処方日, 一包化フラグ(boolean), グループ名" }]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                dosage: { type: Type.NUMBER },
                unit: { type: Type.STRING },
                label: { type: Type.STRING },
                stock: { type: Type.NUMBER },
                prescribedDate: { type: Type.STRING },
                isOnePack: { type: Type.BOOLEAN },
                groupName: { type: Type.STRING }
              },
              required: ["title", "dosage", "unit", "label", "groupName"]
            }
          }
        }
      });

      const extractedItems = JSON.parse(response.text || '[]');
      const now = Date.now();
      let newMeds = [...medications];

      const groups: Record<string, any[]> = {};
      extractedItems.forEach((item: any) => {
        const key = item.groupName;
        if (!groups[key]) groups[key] = [];
        groups[key].push(item);
      });

      Object.entries(groups).forEach(([groupName, items]) => {
        const isOnePack = items.some(i => i.isOnePack);
        const folderType = isOnePack ? 'one-pack' : 'multi-dose';

        const folderId = crypto.randomUUID();
        const folder: Medication = {
          id: folderId,
          title: groupName,
          unit: '包', 
          dosage: items[0].dosage,
          label: items[0].label,
          stock: items[0].stock,
          memo: isOnePack ? '一包化パッケージ' : '服用グループ',
          color: 'emerald',
          startDate: now,
          isFolder: true,
          folderType
        };
        newMeds.push(folder);

        items.forEach(item => {
          const startDate = item.prescribedDate ? parse(item.prescribedDate, 'yyyy-MM-dd', new Date()).getTime() : now;
          newMeds.push({
            id: crypto.randomUUID(),
            title: item.title,
            dosage: item.dosage,
            unit: item.unit as any,
            label: item.label,
            stock: item.stock,
            memo: '',
            color: 'emerald',
            startDate: startDate,
            isFolder: false,
            parentId: folderId
          });
        });
      });

      setMedications(newMeds);
    } catch (err) {
      alert('解析に失敗しました。');
    } finally {
      setIsScanning(false);
      setShowAddMenu(false);
    }
  };

  const renderHome = () => {
    // 表示すべき全アイテム（フォルダ自体はタスク判定しない、その子またはスタンドアロンのみ）
    const scheduledMeds = medications.filter(m => !m.isFolder && shouldShowMedicationOnDate(m, selectedDate));

    // フォルダごとにグルーピング
    const folderGroups: Record<string, Medication[]> = {};
    const standaloneMeds: Medication[] = [];

    scheduledMeds.forEach(m => {
      if (m.parentId) {
        if (!folderGroups[m.parentId]) folderGroups[m.parentId] = [];
        folderGroups[m.parentId].push(m);
      } else {
        standaloneMeds.push(m);
      }
    });

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
          <h1 className="text-center font-bold text-slate-800">ホーム</h1>
          <div className="absolute right-4 top-1/2 -translate-y-1/2" ref={menuRef}>
            <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1">
              <Plus size={14} /> 追加
            </button>
            {showAddMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2">
                <button onClick={() => { setEditingMed(null); setIsFormOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                  <FileText size={18} className="text-emerald-500" /> 手動入力
                </button>
                <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                  <Camera size={18} className="text-blue-500" /> 手帳スキャン
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Calendar (省略なしで再実装) */}
        <div className="bg-white px-5 py-4 border-b border-slate-100">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-black text-slate-800">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
            <div className="flex bg-slate-100 rounded-lg p-1">
              {['month', 'week', 'day'].map((m: any) => (
                <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                  {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
                </button>
              ))}
            </div>
          </div>
          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {eachDayOfInterval({ 
              start: calendarMode === 'week' ? startOfWeek(displayDate) : startOfWeek(startOfMonth(displayDate)), 
              end: calendarMode === 'week' ? addDays(startOfWeek(displayDate), 6) : endOfWeek(endOfMonth(displayDate)) 
            }).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const hasMed = medications.some(m => !m.isFolder && shouldShowMedicationOnDate(m, day));
              return (
                <button key={idx} onClick={() => setSelectedDate(day)} className={`flex flex-col items-center py-2 rounded-xl transition-all ${isSelected ? 'bg-emerald-500 text-white shadow-md' : 'hover:bg-slate-50'}`}>
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  {hasMed && <div className={`w-1 h-1 rounded-full mt-1 ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                </button>
              );
            })}
          </div>
        </div>

        <div className="px-4 py-4"><h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} のタスク</h3></div>

        <div className="flex-1 overflow-y-auto px-4 space-y-4 pb-32">
          {Object.entries(folderGroups).map(([folderId, children]) => {
            const folder = medications.find(m => m.id === folderId);
            if (!folder) return null;
            const isOnePack = folder.folderType === 'one-pack';
            const isAllDone = isFolderAllDone(folderId, selectedDate, children);
            const isExpanded = expandedFolders.has(folderId);

            return (
              <div key={folderId} className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                <div className={`p-4 flex items-center gap-4 transition-colors ${isAllDone ? 'bg-emerald-50/50' : 'bg-white'}`}>
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isAllDone ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                    {isOnePack ? <Package size={24} /> : <FolderOpen size={24} />}
                  </div>
                  <div className="flex-1 cursor-pointer" onClick={() => {
                    const newSet = new Set(expandedFolders);
                    if (isExpanded) newSet.delete(folderId); else newSet.add(folderId);
                    setExpandedFolders(newSet);
                  }}>
                    <h4 className={`font-bold text-lg ${isAllDone ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{folder.title}</h4>
                    <p className="text-xs text-slate-500 font-medium">
                      {isOnePack ? '一包化タスク' : `${children.length}つの服用タイミング`}
                    </p>
                  </div>

                  {isOnePack ? (
                    // 一包化はタイトルのみ表示し、1つのチェックで全部終わる
                    <button 
                      onClick={() => children.forEach(c => { if(isCompleted(c.id, selectedDate) === isAllDone) toggleComplete(c.id, selectedDate) })}
                      className={`w-10 h-10 rounded-xl flex items-center justify-center ${isAllDone ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300'}`}
                    >
                      <Check size={24} strokeWidth={3} />
                    </button>
                  ) : (
                    // 複数回は展開矢印
                    <button onClick={() => {
                      const newSet = new Set(expandedFolders);
                      if (isExpanded) newSet.delete(folderId); else newSet.add(folderId);
                      setExpandedFolders(newSet);
                    }} className={`p-2 text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>
                      <ChevronDown size={20} />
                    </button>
                  )}
                </div>

                {/* 複数回服用の場合の子要素（展開時のみ） */}
                {!isOnePack && isExpanded && (
                  <div className="bg-slate-50/50 px-4 py-2 space-y-2 border-t border-slate-50">
                    {children.map(child => (
                      <div key={child.id} className="flex items-center gap-3 py-3 border-b border-slate-100 last:border-0">
                        <button 
                          onClick={() => toggleComplete(child.id, selectedDate)}
                          className={`w-8 h-8 rounded-lg flex items-center justify-center ${isCompleted(child.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-white border border-slate-200 text-slate-200'}`}
                        >
                          <Check size={18} strokeWidth={3} />
                        </button>
                        <div className="flex-1">
                          <p className={`text-sm font-bold ${isCompleted(child.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-700'}`}>
                            {child.label}
                          </p>
                          {child.notificationTime && <span className="text-[10px] text-slate-400 flex items-center gap-1"><Bell size={10}/> {child.notificationTime}</span>}
                        </div>
                        <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded border">{child.dosage}{child.unit}</span>
                      </div>
                    ))}
                  </div>
                )}
                {/* 一包化展開時（中身の確認のみ） */}
                {isOnePack && isExpanded && (
                  <div className="bg-slate-50/50 px-4 py-2 space-y-1 border-t border-slate-50">
                    <p className="text-[10px] font-bold text-slate-400 mb-2">含まれるお薬:</p>
                    {children.map(child => (
                      <div key={child.id} className="flex justify-between items-center py-1">
                        <span className="text-xs font-bold text-slate-600">{child.title}</span>
                        <span className="text-[10px] text-slate-400">{child.dosage}{child.unit}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}

          {standaloneMeds.map(med => (
            <div key={med.id} className={`p-4 rounded-3xl border flex items-center gap-4 ${isCompleted(med.id, selectedDate) ? 'bg-emerald-50/50 border-emerald-100' : 'bg-white border-slate-100 shadow-sm'}`}>
              <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300'}`}>
                <Check size={28} strokeWidth={3} />
              </button>
              <div className="flex-1" onClick={() => { setEditingMed(med); setIsFormOpen(true); }}>
                <div className="flex justify-between items-start">
                  <h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-400 line-through' : 'text-slate-800'}`}>{med.title}</h4>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span>
                </div>
                <p className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const renderMeds = () => {
    const folders = medications.filter(m => m.isFolder);
    const orphanMeds = medications.filter(m => !m.isFolder && !m.parentId);

    const renderMedItem = (med: Medication) => (
      <div key={med.id} onClick={() => { setEditingMed(med); setIsFormOpen(true); }} className="bg-white p-4 rounded-2xl border border-slate-100 flex justify-between items-center active:bg-slate-50 mb-2 last:mb-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center"><Pill size={16} className="text-slate-400" /></div>
          <div>
            <div className="flex items-center gap-2 mb-0.5">
              <h3 className="font-bold text-slate-800 text-sm">{med.title}</h3>
              <span className="text-[9px] bg-slate-50 px-1.5 py-0.5 rounded border text-slate-400">{med.label}</span>
            </div>
            <p className="text-[10px] text-slate-400">1回: {med.dosage}{med.unit} / 在庫: {med.stock}</p>
          </div>
        </div>
        <Edit2 size={14} className="text-slate-300" />
      </div>
    );

    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">お薬一覧</h1></div>
        <div className="p-4 space-y-6 overflow-y-auto pb-32">
          {folders.map(folder => (
            <div key={folder.id} className="bg-white/40 rounded-3xl p-4 border border-slate-200/50">
              <div className="flex items-center justify-between mb-3 px-1">
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600">
                    {folder.folderType === 'one-pack' ? <Package size={16} /> : <FolderOpen size={16} />}
                  </div>
                  <h2 className="font-black text-slate-800 tracking-tight">{folder.title}</h2>
                </div>
                <button onClick={() => { setEditingMed(folder); setIsFormOpen(true); }} className="p-1.5 hover:bg-slate-100 rounded-full text-slate-400 transition-colors"><Edit2 size={14}/></button>
              </div>
              <div className="space-y-1">
                {medications.filter(m => m.parentId === folder.id).map(renderMedItem)}
              </div>
            </div>
          ))}

          {orphanMeds.length > 0 && (
            <div className="px-1">
              <h2 className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] mb-3 ml-1">その他のお薬</h2>
              {orphanMeds.map(renderMedItem)}
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl flex flex-col relative overflow-hidden">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && renderHome()}
        {view === 'meds' && renderMeds()}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5">
              <button onClick={() => { if(window.confirm('全データを削除しますか？')) { localStorage.clear(); location.reload(); }}} className="w-full p-4 bg-white rounded-3xl border border-red-100 flex items-center justify-between font-bold text-red-500 shadow-sm active:scale-95 transition-transform">
                <div className="flex items-center gap-3"><RotateCcw size={20} /> データリセット</div>
                <ChevronRight size={18} />
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && <CameraModal onCapture={performOCR} onCancel={() => setIsCameraOpen(false)} />}
      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
          <div className="bg-white/10 p-10 rounded-[48px] border border-white/20 flex flex-col items-center">
            <Loader2 size={48} className="animate-spin mb-6 text-emerald-400" />
            <p className="font-black text-xl mb-1 tracking-tight">AI解析中...</p>
            <p className="text-xs text-white/50">項目を抽出して自動で整理しています</p>
          </div>
        </div>
      )}
      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => { 
            // フォルダを消すときは子も消す
            const toDelete = medications.filter(m => m.id === id || m.parentId === id);
            const idsToDelete = toDelete.map(m => m.id);
            setMedications(medications.filter(m => !idsToDelete.includes(m.id)));
            setIsFormOpen(false); 
          }}
          visibleUnits={visibleUnits}
          visibleLabels={visibleLabels}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Check, ChevronLeft, Trash2, Pill, Clock, X, ChevronDown, History, Calendar as CalendarIcon, Package, FolderOpen } from 'lucide-react';
import { Medication, UnitType, LabelType } from '../types';
import { UNITS, LABELS } from '../constants';
import { format } from 'date-fns';
import { ja } from 'date-fns/locale';

interface MedicationFormProps {
  initialData?: Medication;
  onSave: (med: Medication) => void;
  onCancel: () => void;
  onDelete?: (id: string) => void;
  visibleUnits: string[];
  visibleLabels: string[];
}

// Options
const HOURS = Array.from({ length: 24 }, (_, i) => i);
const MINUTES = Array.from({ length: 60 }, (_, i) => i);
const DOSAGE_OPTIONS = [0.1, 0.5, 1, 1.5, 2, 2.5, 3, 4, 5, 10];
const STOCK_OPTIONS = [0, 5, 7, 10, 14, 21, 28, 30, 60, 90, 100];

const ScrollWheel: React.FC<{ 
  items: number[]; 
  value: number; 
  onChange: (val: number) => void;
  format?: (val: number) => string;
}> = ({ items, value, onChange, format }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const highlightListRef = useRef<HTMLDivElement>(null);
  const ITEM_HEIGHT = 40;
  const CONTAINER_HEIGHT = 160;
  const PADDING = (CONTAINER_HEIGHT - ITEM_HEIGHT) / 2;

  useEffect(() => {
    if (containerRef.current) {
      const index = items.indexOf(value);
      if (index !== -1) containerRef.current.scrollTop = index * ITEM_HEIGHT;
    }
  }, []);

  const handleScroll = () => {
    if (containerRef.current) {
      const scrollTop = containerRef.current.scrollTop;
      if (highlightListRef.current) highlightListRef.current.style.transform = `translateY(-${scrollTop}px)`;
      const index = Math.round(scrollTop / ITEM_HEIGHT);
      if (items[index] !== undefined && items[index] !== value) onChange(items[index]);
    }
  };

  return (
    <div className="relative h-[160px] w-20 overflow-hidden select-none">
      <div ref={containerRef} onScroll={handleScroll} className="h-full overflow-y-auto no-scrollbar snap-y snap-mandatory" style={{ paddingTop: PADDING, paddingBottom: PADDING }}>
        {items.map((item) => <div key={item} className="h-[40px] flex items-center justify-center snap-center text-xl font-medium text-slate-300">{format ? format(item) : item}</div>)}
      </div>
      <div className="absolute left-0 right-0 pointer-events-none overflow-hidden" style={{ top: PADDING, height: ITEM_HEIGHT }}>
        <div ref={highlightListRef} className="w-full">
           {items.map((item) => <div key={item} className="h-[40px] flex items-center justify-center text-xl font-bold text-slate-900">{format ? format(item) : item}</div>)}
        </div>
      </div>
    </div>
  );
};

export const MedicationForm: React.FC<MedicationFormProps> = ({ initialData, onSave, onCancel, onDelete, visibleUnits, visibleLabels }) => {
  const isFolder = initialData?.isFolder;
  const [title, setTitle] = useState(initialData?.title || '');
  const [dosage, setDosage] = useState(initialData?.dosage?.toString() || '1');
  const [unit, setUnit] = useState<UnitType>(initialData?.unit || '錠');
  const [label, setLabel] = useState<LabelType>(initialData?.label || '朝食後');
  const [stock, setStock] = useState(initialData?.stock?.toString() || '0');
  const [memo, setMemo] = useState(initialData?.memo || '');
  const [notificationTime, setNotificationTime] = useState(initialData?.notificationTime || '');
  const [startDateStr, setStartDateStr] = useState(format(initialData?.startDate || Date.now(), 'yyyy-MM-dd'));

  const [isTimePickerOpen, setIsTimePickerOpen] = useState(false);
  const [hour, setHour] = useState(notificationTime ? parseInt(notificationTime.split(':')[0]) : 8);
  const [minute, setMinute] = useState(notificationTime ? parseInt(notificationTime.split(':')[1]) : 0);
  const [showDeleteModal, setShowDeleteModal] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return;
    const now = Date.now();
    onSave({
      ...initialData,
      id: initialData?.id || crypto.randomUUID(),
      title,
      dosage: parseFloat(dosage) || 0,
      unit,
      label,
      stock: parseInt(stock) || 0,
      memo,
      notificationTime: notificationTime || undefined,
      color: 'emerald',
      startDate: new Date(startDateStr).getTime(),
      isFolder: !!isFolder,
      folderType: initialData?.folderType,
      parentId: initialData?.parentId,
      history: [...(initialData?.history || []), { id: crypto.randomUUID(), timestamp: now, type: 'update', message: '情報を更新しました' }]
