  return (
    <div className="fixed inset-0 z-50 bg-slate-50 flex flex-col animate-in slide-in-from-bottom duration-300">
      <div className="bg-white px-4 py-3 flex items-center justify-between shadow-sm border-b border-slate-200 safe-top">
        <button onClick={onCancel} className="p-2 -ml-2 text-slate-900 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft size={24} /></button>
        <div className="flex flex-col items-center">
          <h2 className="text-sm font-black text-slate-800 tracking-tight">{isFolder ? 'グループの編集' : 'お薬の編集'}</h2>
          {isFolder && <span className="text-[10px] text-slate-400 font-bold uppercase">{initialData?.folderType === 'one-pack' ? '一包化' : '服用グループ'}</span>}
        </div>
        <div className="w-10"></div> 
      </div>

      <div className="flex-1 overflow-y-auto p-4 pb-48 safe-bottom">
        <div className="max-w-md mx-auto space-y-4">

          <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">名前</label>
            <div className="flex items-center gap-3">
              {isFolder ? (
                initialData?.folderType === 'one-pack' ? <Package className="text-emerald-500" size={24}/> : <FolderOpen className="text-emerald-500" size={24}/>
              ) : <Pill className="text-emerald-500" size={24}/>}
              <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="名称を入力..." className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none" />
            </div>
          </div>

          {!isFolder && (
            <>
              <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200 relative">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">開始日（処方日）</label>
                <div className="flex items-center gap-3">
                  <CalendarIcon size={18} className="text-slate-400" />
                  <input type="date" value={startDateStr} onChange={(e) => setStartDateStr(e.target.value)} className="bg-transparent text-lg font-bold text-slate-800 outline-none flex-1" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200 relative">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">1回の量</label>
                  <select value={dosage} onChange={(e) => setDosage(e.target.value)} className="w-full bg-transparent text-lg font-bold text-slate-800 outline-none appearance-none">
                    {DOSAGE_OPTIONS.map(d => <option key={d} value={d}>{d}</option>)}
