                  <ChevronDown size={14} className="absolute right-4 bottom-6 text-slate-400" />
                </div>
              </div>

              <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200 relative">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">タイミング</label>
                <select value={label} onChange={(e) => setLabel(e.target.value)} className="w-full bg-transparent text-lg font-bold text-slate-800 outline-none appearance-none">
                  {LABELS.map(l => <option key={l} value={l}>{l}</option>)}
