                  <select value={stock} onChange={(e) => setStock(e.target.value)} className="w-full bg-transparent text-lg font-bold text-slate-800 outline-none appearance-none">
                    {STOCK_OPTIONS.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <ChevronDown size={14} className="absolute right-4 bottom-6 text-slate-400" />
                </div>
                <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200 relative">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">通知</label>
                  <button onClick={() => setIsTimePickerOpen(true)} className="w-full text-left text-lg font-bold text-slate-800">{notificationTime || '--:--'}</button>
                  <Clock size={14} className="absolute right-4 bottom-6 text-slate-400" />
                </div>
              </div>
            </>
          )}

          <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">メモ</label>
            <textarea rows={3} value={memo} onChange={(e) => setMemo(e.target.value)} placeholder="特記事項があれば..." className="w-full bg-transparent text-sm font-medium text-slate-600 outline-none resize-none" />
          </div>

          {onDelete && (
            <button type="button" onClick={() => setShowDeleteModal(true)} className="w-full py-5 bg-red-50 text-red-500 rounded-3xl font-black text-sm uppercase tracking-widest flex justify-center items-center gap-2">
              <Trash2 size={20} /> この情報を削除
            </button>
          )}
        </div>
      </div>

      <div className="absolute bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t border-slate-200 p-6 pb-safe safe-bottom z-50">
        <button onClick={handleSubmit} className="w-full bg-slate-900 text-white py-5 rounded-[24px] font-black text-lg shadow-xl active:scale-95 transition-transform flex items-center justify-center gap-2">
          <Check size={24} strokeWidth={3} /> 変更を保存
        </button>
      </div>

      {isTimePickerOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsTimePickerOpen(false)}></div>
          <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-[320px] relative z-10 animate-in zoom-in-95 overflow-hidden">
            <div className="p-8 flex justify-center items-center gap-4 relative">
              <div className="absolute top-1/2 left-4 right-4 -translate-y-1/2 h-10 bg-slate-100 rounded-2xl -z-10"></div>
              <ScrollWheel items={HOURS} value={hour} onChange={setHour} format={(val) => val.toString().padStart(2, '0')} />
              <span className="text-2xl font-black text-slate-300 pb-1">:</span>
              <ScrollWheel items={MINUTES} value={minute} onChange={setMinute} format={(val) => val.toString().padStart(2, '0')} />
            </div>
            <div className="p-4 bg-slate-50 border-t border-slate-100 flex gap-3">
              <button onClick={() => { setNotificationTime(''); setIsTimePickerOpen(false); }} className="flex-1 py-4 text-red-500 font-bold text-sm">解除</button>
