      {showDeleteModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowDeleteModal(false)}></div>
          <div className="bg-white rounded-[40px] p-8 w-full max-w-sm relative z-10 text-center">
            <div className="w-20 h-20 bg-red-100 text-red-500 rounded-3xl flex items-center justify-center mx-auto mb-6"><Trash2 size={40}/></div>
            <h3 className="text-xl font-black text-slate-800 mb-2">削除しますか？</h3>
            <p className="text-sm text-slate-400 font-medium mb-8 leading-relaxed">この操作は取り消せません。{isFolder && "グループ内のお薬もすべて削除されます。"}</p>
