                <button onClick={() => { setIsCameraOpen(true); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700"><Camera size={18} className="text-blue-500" /> 手帳スキャン</button>
              </div>
            )}
          </div>
        </div>

        <div className="bg-white px-5 py-4 border-b border-slate-100">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-black text-slate-800">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
            <div className="flex bg-slate-100 rounded-lg p-1">
              {['month', 'week', 'day'].map((m: any) => (
                <button key={m} onClick={() => setCalendarMode(m)} className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>{m === 'month' ? '月' : m === 'week' ? '週' : '日'}</button>
              ))}
            </div>
          </div>
          <div className="grid grid-cols-7 text-center">
            {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
            {eachDayOfInterval({ 
              start: calendarMode === 'week' ? startOfWeek(displayDate) : startOfWeek(startOfMonth(displayDate)), 
              end: calendarMode === 'week' ? addDays(startOfWeek(displayDate), 6) : endOfWeek(endOfMonth(displayDate)) 
            }).map((day, idx) => {
              const isSelected = isSameDay(day, selectedDate);
              const isTodayDate = isToday(day);
              const hasMed = medications.some(m => shouldShowMedicationOnDate(m, day));
              const cond = conditions.find(c => c.dateStr === format(day, 'yyyy-MM-dd'));
              return (
                <button key={idx} onClick={() => setSelectedDate(day)} className={`flex flex-col items-center py-2 rounded-xl transition-all ${isSelected ? 'bg-emerald-500 text-white shadow-md' : 'hover:bg-slate-50'}`}>
                  <span className={`text-sm font-bold ${isTodayDate && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                  <div className="flex gap-0.5 mt-1">
                    {hasMed && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-slate-300'}`}></div>}
                    {cond && cond.score > 0 && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-blue-400'}`}></div>}
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 pb-32 pt-4">
          <div className="bg-white rounded-[32px] p-5 border border-slate-100 shadow-sm mb-6">
            <div className="flex items-center gap-2 mb-4">
              <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-500 flex items-center justify-center"><Smile size={18}/></div>
              <h3 className="font-bold text-slate-800">今日の体調</h3>
            </div>
