                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${item.bg} ${item.color}`}><item.icon size={28} /></div>
                  <span className={`text-[10px] font-bold ${currentCondition.score === item.score ? 'text-slate-800' : 'text-slate-400'}`}>{item.label}</span>
                </button>
              ))}
            </div>
            <div className="relative">
              <MessageSquare size={14} className="absolute left-3 top-3.5 text-slate-300" />
              <textarea value={currentCondition.memo} onChange={(e) => updateCondition(currentCondition.dateStr, { memo: e.target.value })} placeholder="症状や気付いたことをメモ..." className="w-full bg-slate-50 rounded-2xl p-3 pl-10 text-sm font-medium text-slate-700 outline-none resize-none min-h-[80px]" />
            </div>
          </div>
          <div className="mb-4 flex items-center justify-between"><h3 className="text-lg font-bold text-slate-800">{format(selectedDate, 'M/d (EE)', { locale: ja })} の服薬</h3></div>
          <div className="space-y-4">
            {Object.entries(folderGroups).map(([folderId, children]) => {
              const folder = medications.find(m => m.id === folderId);
              if (!folder) return null;
              const isOnePack = folder.folderType === 'one-pack';
              const isAllDone = isFolderAllDone(folderId, selectedDate, children);
              const isExpanded = expandedFolders.has(folderId);
              return (
                <div key={folderId} className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                  <div className="p-4 flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isAllDone ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400'}`}>{isOnePack ? <Package size={24} /> : <FolderOpen size={24} />}</div>
                    <div className="flex-1 cursor-pointer" onClick={() => { const newSet = new Set(expandedFolders); if (isExpanded) newSet.delete(folderId); else newSet.add(folderId); setExpandedFolders(newSet); }}>
                      <h4 className={`font-bold text-lg ${isAllDone ? 'text-slate-300 line-through' : 'text-slate-800'}`}>{folder.title}</h4>
                      <p className="text-xs text-slate-500 font-medium">{isOnePack ? '一包化タスク' : `${children.length}つの服用タイミング`}</p>
                    </div>
                    {isOnePack ? (
                      <button onClick={() => children.forEach(c => { if(isCompleted(c.id, selectedDate) === isAllDone) toggleComplete(c.id, selectedDate) })} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAllDone ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300'}`}><Check size={24} strokeWidth={3} /></button>
                    ) : (
                      <button onClick={() => { const newSet = new Set(expandedFolders); if (isExpanded) newSet.delete(folderId); else newSet.add(folderId); setExpandedFolders(newSet); }} className={`p-2 text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}><ChevronDown size={20} /></button>
                    )}
                  </div>
                  {isExpanded && (
                    <div className="bg-slate-50/50 px-4 py-2 space-y-2 border-t border-slate-50">
                      {children.map(child => (
                        <div key={child.id} className="flex items-center gap-3 py-3 border-b border-slate-100 last:border-0">
