                            <button onClick={() => toggleComplete(child.id, selectedDate)} className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${isCompleted(child.id, selectedDate) ? 'bg-emerald-500 text-white shadow-sm' : 'bg-white border border-slate-200 text-slate-200'}`}><Check size={18} strokeWidth={3} /></button>
                          )}
                          <div className="flex-1">
                            <p className={`text-sm font-bold ${isCompleted(child.id, selectedDate) ? 'text-slate-300 line-through' : 'text-slate-700'}`}>{isOnePack ? child.title : child.label}</p>
                            {child.notificationTime && <span className="text-[10px] text-slate-400 flex items-center gap-1"><Bell size={10}/> {child.notificationTime}</span>}
                          </div>
                          <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded border">{child.dosage}{child.unit}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
            {standaloneMeds.map(med => (
              <div key={med.id} className="p-4 rounded-3xl border flex items-center gap-4 bg-white border-slate-100 shadow-sm">
                <button onClick={() => toggleComplete(med.id, selectedDate)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-300'}`}><Check size={28} strokeWidth={3} /></button>
                <div className="flex-1" onClick={() => { setEditingMed(med); setIsFormOpen(true); }}>
                  <div className="flex justify-between items-start"><h4 className={`font-bold text-lg ${isCompleted(med.id, selectedDate) ? 'text-slate-300 line-through' : 'text-slate-800'}`}>{med.title}</h4><span className={`text-[10px] font-bold px-2 py-0.5 rounded border ${LABEL_COLORS[med.label] || 'bg-slate-100'}`}>{med.label}</span></div>
                  <p className="text-xs font-medium text-slate-500 mt-1">{med.dosage}{med.unit} ・ 残り{med.stock}{med.unit}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  };

  const renderReportSetup = () => {
    return (
      <div className="flex flex-col h-full bg-slate-50">
        <div className="bg-white py-4 safe-top border-b flex items-center px-4">
          <button onClick={() => setView('settings')} className="p-2 text-slate-600"><ChevronLeft size={24}/></button>
          <h1 className="flex-1 text-center font-black text-slate-800">レポート作成設定</h1>
          <div className="w-10"></div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          <section className="space-y-3">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">出力期間</h3>
            <div className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm space-y-4">
              <div className="flex flex-col gap-1">
                <label className="text-[10px] font-bold text-slate-400 px-1">開始日</label>
                <input type="date" value={reportRange.start} onChange={(e) => setReportRange({...reportRange, start: e.target.value})} className="bg-slate-50 p-3 rounded-xl font-bold text-slate-800 outline-none" />
              </div>
              <div className="flex flex-col gap-1">
                <label className="text-[10px] font-bold text-slate-400 px-1">終了日</label>
                <input type="date" value={reportRange.end} onChange={(e) => setReportRange({...reportRange, end: e.target.value})} className="bg-slate-50 p-3 rounded-xl font-bold text-slate-800 outline-none" />
              </div>
            </div>
          </section>

          <section className="space-y-3">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">出力内容</h3>
            <div className="bg-white rounded-3xl border border-slate-100 shadow-sm divide-y divide-slate-50 overflow-hidden">
              <button onClick={() => setReportOptions({...reportOptions, includeMeds: !reportOptions.includeMeds})} className="w-full p-5 flex items-center justify-between hover:bg-slate-50 transition-colors">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center"><Pill size={20}/></div>
                  <span className="font-bold text-slate-700">服薬達成記録</span>
