          <button onClick={() => setView('report')} className="w-full bg-slate-900 text-white py-5 rounded-[24px] font-black text-lg shadow-xl active:scale-95 transition-transform flex items-center justify-center gap-2">
            <FileDown size={24} strokeWidth={3} /> レポート作成
          </button>
        </div>
