  const renderReport = () => {
    const startDate = parse(reportRange.start, 'yyyy-MM-dd', new Date());
    const endDate = parse(reportRange.end, 'yyyy-MM-dd', new Date());
    const dateRange = eachDayOfInterval({ start: startDate, end: endDate });

    // 統計
    const totalScheduled = medications.filter(m => !m.isFolder).length * dateRange.length;
    const totalTaken = logs.filter(l => isWithinInterval(parse(l.dateStr, 'yyyy-MM-dd', new Date()), { start: startDate, end: endDate })).length;
    const rate = totalScheduled > 0 ? Math.round((totalTaken / totalScheduled) * 100) : 0;

    const handleShare = async () => {
      try {
        if (navigator.share) {
          await navigator.share({
            title: '服薬・体調レポート',
            text: `${reportRange.start}〜${reportRange.end}の記録です。`,
            url: window.location.href
          });
        } else {
          alert('お使いの環境では直接の共有に対応していません。PDF出力から保存してください。');
        }
      } catch (e) { console.error(e); }
