          <button onClick={() => setView('report-setup')} className="p-2 text-slate-600"><ChevronLeft size={24}/></button>
          <div className="flex gap-2">
            <button onClick={handleShare} className="p-3 bg-slate-100 text-slate-600 rounded-full active:scale-90 transition-transform"><Share size={20}/></button>
            <button onClick={() => window.print()} className="bg-emerald-600 text-white px-5 py-2 rounded-full font-bold text-sm flex items-center gap-2 shadow-lg shadow-emerald-100"><Printer size={16}/> PDF出力 / 印刷</button>
