        <div className="p-8 space-y-10 max-w-2xl mx-auto w-full print:p-4 print:max-w-none">
          <div className="text-center space-y-2 border-b-4 border-slate-900 pb-8">
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter">服薬管理レポート</h2>
            <p className="text-sm font-black text-slate-400 uppercase tracking-widest">{format(startDate, 'yyyy/MM/dd')} — {format(endDate, 'yyyy/MM/dd')}</p>
