                  const dateStr = format(date, 'yyyy-MM-dd');
                  const cond = conditions.find(c => c.dateStr === dateStr);
                  const dailyLogs = logs.filter(l => l.dateStr === dateStr);
                  if (!cond && dailyLogs.length === 0) return null;
                  const icon = CONDITION_ICONS.find(i => i.score === cond?.score);
                  return (
                    <div key={dateStr} className="flex gap-4 p-5 bg-slate-50 rounded-3xl border border-slate-200">
                      <div className="w-16 shrink-0 text-center">
                        <p className="text-sm font-black text-slate-900">{format(date, 'MM/dd')}</p>
                        <p className="text-[10px] font-bold text-slate-400">{format(date, '(EE)', { locale: ja })}</p>
                      </div>
                      <div className="flex-1 space-y-2">
                        <div className="flex items-center gap-2">
                          {icon && <icon.icon size={20} className="text-slate-900" />}
                          <span className="text-sm font-black text-slate-800">{icon?.label || '--'}</span>
