import React, { useState, useEffect } from 'react';
import { format, subDays } from 'date-fns';
import { BottomNav } from './components/BottomNav';
import { MedicationForm } from './components/MedicationForm';
import { CameraModal } from './components/CameraModal';
import { Medication, MedicationLog, ViewMode, DailyCondition, GlobalActionLog, ReportConfig } from './types';
import { UNITS, LABELS } from './constants';
import { HomeView } from './features/home/HomeView';
import { MedicationListView } from './features/meds/MedicationListView';
import { ReportSetupView } from './features/report/ReportSetupView';
import { ReportPreviewView } from './features/report/ReportPreviewView';
import { Loader2, RotateCcw, ChevronRight, FileDown } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<ViewMode>('home');
  const [medications, setMedications] = useState<Medication[]>([]);
  const [logs, setLogs] = useState<MedicationLog[]>([]);
  const [globalLogs, setGlobalLogs] = useState<GlobalActionLog[]>([]);
  const [conditions, setConditions] = useState<DailyCondition[]>([]);

  const [reportConfig, setReportConfig] = useState<ReportConfig>({
    start: format(subDays(new Date(), 30), 'yyyy-MM-dd'),
    end: format(new Date(), 'yyyy-MM-dd'),
    includeMeds: true,
    includeCondition: true,
    includeHistory: true
  });

  const [editingMed, setEditingMed] = useState<Medication | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [isScanning, setIsScanning] = useState(false);

  useEffect(() => {
    const load = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
    setMedications(load('medications'));
    setLogs(load('logs'));
    setGlobalLogs(load('globalLogs'));
    setConditions(load('conditions'));
  }, []);

  useEffect(() => {
    localStorage.setItem('medications', JSON.stringify(medications));
    localStorage.setItem('logs', JSON.stringify(logs));
    localStorage.setItem('globalLogs', JSON.stringify(globalLogs));
    localStorage.setItem('conditions', JSON.stringify(conditions));
  }, [medications, logs, globalLogs, conditions]);

  const addGlobalLog = (type: GlobalActionLog['type'], title: string, details?: string) => {
    const newLog: GlobalActionLog = { id: crypto.randomUUID(), timestamp: Date.now(), type, title, details };
    setGlobalLogs(prev => [newLog, ...prev].slice(0, 100));
  };

  const handleSaveMed = (med: Medication) => {
    const isEdit = medications.some(m => m.id === med.id);
    setMedications(prev => isEdit ? prev.map(m => m.id === med.id ? med : m) : [...prev, med]);
    addGlobalLog(isEdit ? 'update' : 'add', med.title, isEdit ? '更新しました' : '新規登録しました');
    setIsFormOpen(false);
    setEditingMed(null);
  };

  return (
    <div className="bg-slate-100 min-h-screen max-w-md mx-auto shadow-2xl flex flex-col relative overflow-hidden">
      <div className="flex-1 overflow-hidden">
        {view === 'home' && (
          <HomeView 
            medications={medications} 
            logs={logs} 
            setLogs={setLogs} 
            setMedications={setMedications}
            conditions={conditions}
            setConditions={setConditions}
            onEditMed={(med) => { setEditingMed(med); setIsFormOpen(true); }}
            onOpenForm={() => { setEditingMed(null); setIsFormOpen(true); }}
            onOpenScan={() => setIsCameraOpen(true)}
          />
        )}
        {view === 'meds' && (
          <MedicationListView 
            medications={medications} 
            globalLogs={globalLogs}
            onEditMed={(med) => { setEditingMed(med); setIsFormOpen(true); }}
            onOpenForm={() => { setEditingMed(null); setIsFormOpen(true); }}
            onOpenScan={() => setIsCameraOpen(true)}
          />
        )}
        {view === 'report-setup' && (
          <ReportSetupView 
            config={reportConfig} 
            setConfig={setReportConfig} 
            onBack={() => setView('settings')}
            onGenerate={() => setView('report')}
          />
        )}
        {view === 'report' && (
          <ReportPreviewView 
            config={reportConfig} 
            medications={medications} 
            logs={logs} 
            conditions={conditions}
            globalLogs={globalLogs}
            onBack={() => setView('report-setup')}
          />
        )}
        {view === 'settings' && (
          <div className="flex flex-col h-full bg-slate-50">
            <div className="bg-slate-50 py-3 safe-top border-b border-slate-200"><h1 className="text-center font-bold text-slate-800">設定</h1></div>
            <div className="p-5 space-y-4">
              <button onClick={() => setView('report-setup')} className="w-full p-6 bg-white rounded-[32px] border border-slate-100 flex items-center justify-between font-black text-slate-800 shadow-sm active:scale-95 transition-all">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center"><FileDown size={24}/></div>
                  <div className="text-left"><p className="text-lg">レポート作成</p><p className="text-xs text-slate-400 font-bold">PDF出力・印刷・共有</p></div>
                </div>
                <ChevronRight size={20} className="text-slate-300" />
              </button>
              <button onClick={() => { if(window.confirm('全データを削除しますか？')) { localStorage.clear(); location.reload(); }}} className="w-full p-4 bg-white rounded-3xl border border-red-50 text-red-500 font-bold flex items-center gap-3 active:scale-95 transition-transform">
                <RotateCcw size={20} /> データリセット
              </button>
            </div>
          </div>
        )}
      </div>

      <BottomNav currentView={view} onChange={setView} />

      {isCameraOpen && <CameraModal onCapture={() => {}} onCancel={() => setIsCameraOpen(false)} />}

      {isScanning && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex flex-col items-center justify-center text-white">
          <Loader2 size={48} className="animate-spin mb-4 text-emerald-400" />
          <p className="font-bold">AI解析中...</p>
        </div>
      )}

      {isFormOpen && (
        <MedicationForm 
          initialData={editingMed || undefined}
          onSave={handleSaveMed}
          onCancel={() => { setIsFormOpen(false); setEditingMed(null); }}
          onDelete={(id) => {
            setMedications(medications.filter(m => m.id !== id && m.parentId !== id));
            addGlobalLog('delete', editingMed?.title || '不明', '削除しました');
            setIsFormOpen(false);
          }}
          visibleUnits={UNITS}
          visibleLabels={LABELS}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { format, eachDayOfInterval, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameDay, isToday, addDays } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Plus, Camera, FileText, Bell, Check, Package, FolderOpen, ChevronDown } from 'lucide-react';
import { HealthCard } from '../../components/HealthCard';
import { Medication, MedicationLog, DailyCondition, CalendarMode } from '../../types';
import { WEEK_DAYS } from '../../constants';

interface HomeViewProps {
  medications: Medication[];
  logs: MedicationLog[];
  setLogs: React.Dispatch<React.SetStateAction<MedicationLog[]>>;
  setMedications: React.Dispatch<React.SetStateAction<Medication[]>>;
  conditions: DailyCondition[];
  setConditions: React.Dispatch<React.SetStateAction<DailyCondition[]>>;
  onEditMed: (med: Medication) => void;
  onOpenForm: () => void;
  onOpenScan: () => void;
}

export const HomeView: React.FC<HomeViewProps> = ({ medications, logs, setLogs, setMedications, conditions, setConditions, onEditMed, onOpenForm, onOpenScan }) => {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [displayDate, setDisplayDate] = useState(new Date());
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');
  const [showAddMenu, setShowAddMenu] = useState(false);

  const currentCondition = conditions.find(c => c.dateStr === format(selectedDate, 'yyyy-MM-dd')) || { dateStr: format(selectedDate, 'yyyy-MM-dd'), score: 0, memo: '' };

  const updateCondition = (updates: Partial<DailyCondition>) => {
    setConditions(prev => {
      const dateStr = format(selectedDate, 'yyyy-MM-dd');
      const existing = prev.find(c => c.dateStr === dateStr);
      if (existing) return prev.map(c => c.dateStr === dateStr ? { ...c, ...updates } : c);
      return [...prev, { dateStr, score: 0, memo: '', ...updates }];
    });
  };

  const isCompleted = (medId: string, date: Date) => {
    const dateStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dateStr);
  };

  const toggleComplete = (medId: string) => {
    const dateStr = format(selectedDate, 'yyyy-MM-dd');
    const existing = logs.find(l => l.medicationId === medId && l.dateStr === dateStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existing) {
      setLogs(prev => prev.filter(l => l.id !== existing.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
        <h1 className="text-center font-bold text-slate-800">ホーム</h1>
        <div className="absolute right-4 top-1/2 -translate-y-1/2">
          <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1">
