      <div className="bg-white px-5 py-4 border-b border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-black text-slate-800">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
          <div className="flex bg-slate-100 rounded-lg p-1">
            {['month', 'week'].map((m: any) => (
              <button key={m} onClick={() => setCalendarMode(m)} className={`px-4 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                {m === 'month' ? '月' : '週'}
              </button>
            ))}
          </div>
        </div>
        <div className="grid grid-cols-7 text-center">
          {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
          {eachDayOfInterval({ 
            start: calendarMode === 'week' ? startOfWeek(displayDate) : startOfWeek(startOfMonth(displayDate)), 
            end: calendarMode === 'week' ? endOfWeek(displayDate) : endOfWeek(endOfMonth(displayDate)) 
          }).map((day, idx) => {
            const isSelected = isSameDay(day, selectedDate);
            const hasMed = medications.some(m => !m.isFolder);
            return (
              <button key={idx} onClick={() => setSelectedDate(day)} className={`flex flex-col items-center py-2 rounded-xl transition-all ${isSelected ? 'bg-emerald-500 text-white shadow-md' : 'hover:bg-slate-50'}`}>
