        </div>

        <div className="space-y-4">
          {medications.filter(m => !m.isFolder).map(med => (
            <div key={med.id} className="p-4 rounded-3xl border flex items-center gap-4 bg-white border-slate-100 shadow-sm active:scale-98 transition-transform">
              <button onClick={() => toggleComplete(med.id)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isCompleted(med.id, selectedDate) ? 'bg-emerald-500 text-white' : 'bg-slate-50 text-slate-200 border border-slate-100'}`}>
