            {globalLogs.length === 0 ? (
              <div className="py-20 text-center space-y-2">
                <History size={40} className="mx-auto text-slate-200" />
                <p className="text-slate-400 font-bold text-sm">履歴はありません</p>
              </div>
            ) : (
              globalLogs.map(log => (
                <div key={log.id} className="bg-white p-4 rounded-[24px] border border-slate-100 shadow-sm flex gap-4 items-start">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                    log.type === 'add' ? 'bg-emerald-50 text-emerald-500' : 
                    log.type === 'update' ? 'bg-blue-50 text-blue-500' : 
                    'bg-red-50 text-red-500'
                  }`}>
                    {log.type === 'add' ? <Plus size={20}/> : <Edit2 size={18}/>}
