                  {dailyLogs.length > 0 && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-emerald-400'}`}></div>}
                  {hasCondition && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-blue-400'}`}></div>}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-32 pt-6">
        <div className="flex items-center justify-between mb-3 px-1">
          <div className="flex flex-col">
