              {format(selectedDate, 'M月 d日 (EE)', { locale: ja })}
            </h3>
          </div>
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-2xl font-black text-xs transition-all active:scale-95 shadow-sm ${
              isEditMode 
                ? 'bg-slate-900 text-white shadow-slate-200' 
                : 'bg-white text-emerald-600 border border-emerald-100'
            }`}
          >
            {isEditMode ? (
              <><Save size={14} strokeWidth={3} /> 保存して終了</>
            ) : (
              <><Edit3 size={14} strokeWidth={3} /> この日を編集</>
            )}
          </button>
        </div>

        <HealthCard 
          condition={currentCondition} 
          onUpdate={updateCondition} 
          selectedDate={selectedDate} 
          isEditMode={isEditMode}
        />

        <div className="mb-4 px-2">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Medication Tasks</h3>
        </div>

        <div className="space-y-3">
          {medications.filter(m => !m.isFolder).length === 0 ? (
            <div className="py-10 text-center bg-white rounded-[32px] border border-dashed border-slate-200">
              <Pill className="mx-auto text-slate-200 mb-2" size={32} />
