            </div>
          ) : (
            medications.filter(m => !m.isFolder).map(med => (
              <div 
                key={med.id} 
                className={`p-4 rounded-[28px] border flex items-center gap-4 transition-all duration-300 ${
                  isEditMode ? 'bg-white border-emerald-100 shadow-md ring-2 ring-emerald-50' : 'bg-white border-slate-100 shadow-sm opacity-90'
                }`}
              >
                <button 
                  onClick={() => toggleComplete(med.id)} 
                  disabled={!isEditMode}
                  className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${
                    isCompleted(med.id, selectedDate) 
                      ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-100' 
                      : isEditMode 
                        ? 'bg-slate-50 text-slate-200 border-2 border-slate-100' 
                        : 'bg-slate-50 text-slate-100 border border-slate-50'
