import React, { useState } from 'react';
import { format, eachDayOfInterval, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameDay, isToday, addDays } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Plus, Camera, FileText, Bell, Check, Package, FolderOpen, ChevronDown, Edit3, Save, Pill, Activity } from 'lucide-react';
import { HealthCard } from '../../components/HealthCard';
import { Medication, MedicationLog, DailyCondition, CalendarMode } from '../../types';
import { WEEK_DAYS } from '../../constants';

interface HomeViewProps {
  medications: Medication[];
  logs: MedicationLog[];
  setLogs: React.Dispatch<React.SetStateAction<MedicationLog[]>>;
  setMedications: React.Dispatch<React.SetStateAction<Medication[]>>;
  conditions: DailyCondition[];
  setConditions: React.Dispatch<React.SetStateAction<DailyCondition[]>>;
  onEditMed: (med: Medication) => void;
  onOpenForm: () => void;
  onOpenScan: () => void;
}

export const HomeView: React.FC<HomeViewProps> = ({ medications, logs, setLogs, setMedications, conditions, setConditions, onEditMed, onOpenForm, onOpenScan }) => {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [displayDate, setDisplayDate] = useState(new Date());
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('month');
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);

  const dateStr = format(selectedDate, 'yyyy-MM-dd');
  const currentCondition = conditions.find(c => c.dateStr === dateStr) || { dateStr, score: 0, memo: '' };

  const updateCondition = (updates: Partial<DailyCondition>) => {
    if (!isEditMode) return;
    setConditions(prev => {
      const existing = prev.find(c => c.dateStr === dateStr);
      if (existing) return prev.map(c => c.dateStr === dateStr ? { ...c, ...updates } : c);
      return [...prev, { dateStr, score: 0, memo: '', ...updates }];
    });
  };

  const isCompleted = (medId: string, date: Date) => {
    const dStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dStr);
  };

  const toggleComplete = (medId: string) => {
    if (!isEditMode) return; 

    const dStr = format(selectedDate, 'yyyy-MM-dd');
    const existing = logs.find(l => l.medicationId === medId && l.dateStr === dStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existing) {
      setLogs(prev => prev.filter(l => l.id !== existing.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr: dStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const handleDateSelect = (day: Date) => {
    setSelectedDate(day);
    setIsEditMode(false);
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50 py-3 safe-top border-b border-slate-200 relative">
        <h1 className="text-center font-bold text-slate-800 text-lg">ホーム</h1>
        <div className="absolute right-4 top-1/2 -translate-y-1/2">
          <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-4 py-2 rounded-full font-bold text-xs shadow-lg flex items-center gap-1 active:scale-95 transition-transform">
            <Plus size={14} /> 追加
          </button>
          {showAddMenu && (
            <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2">
              <button onClick={() => { onOpenForm(); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                <FileText size={18} className="text-emerald-500" /> 手動入力
              </button>
              <button onClick={() => { onOpenScan(); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                <Camera size={18} className="text-blue-500" /> 手帳スキャン
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white px-5 py-4 border-b border-slate-100">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-black text-slate-800">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
          <div className="flex bg-slate-100 rounded-lg p-1">
            {['month', 'week'].map((m: any) => (
              <button key={m} onClick={() => setCalendarMode(m)} className={`px-4 py-1 text-xs font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}>
                {m === 'month' ? '月' : '週'}
              </button>
            ))}
          </div>
        </div>
        <div className="grid grid-cols-7 text-center">
          {WEEK_DAYS.map((d, i) => <div key={d} className={`text-[10px] font-bold pb-2 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>{d}</div>)}
          {eachDayOfInterval({ 
            start: calendarMode === 'week' ? startOfWeek(displayDate) : startOfWeek(startOfMonth(displayDate)), 
            end: calendarMode === 'week' ? endOfWeek(displayDate) : endOfWeek(endOfMonth(displayDate)) 
          }).map((day, idx) => {
            const isSelected = isSameDay(day, selectedDate);
            const dailyLogs = logs.filter(l => l.dateStr === format(day, 'yyyy-MM-dd'));
            const hasCondition = conditions.some(c => c.dateStr === format(day, 'yyyy-MM-dd') && c.score > 0);

            return (
              <button key={idx} onClick={() => handleDateSelect(day)} className={`flex flex-col items-center py-2 rounded-xl transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-md' : 'hover:bg-slate-50'}`}>
                <span className={`text-sm font-bold ${isToday(day) && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
                <div className="flex gap-0.5 mt-1">
                  {dailyLogs.length > 0 && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-emerald-400'}`}></div>}
                  {hasCondition && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-blue-400'}`}></div>}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-32 pt-6">
        <div className="flex items-center justify-between mb-4 px-1">
          <div className="flex flex-col">
            <h3 className="text-2xl font-black text-slate-800 tracking-tighter">
              {format(selectedDate, 'M月 d日 (EE)', { locale: ja })}
            </h3>
          </div>
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-2xl font-black text-xs transition-all active:scale-95 shadow-sm ${
              isEditMode 
                ? 'bg-slate-900 text-white shadow-slate-200' 
                : 'bg-white text-emerald-600 border border-emerald-100'
            }`}
          >
            {isEditMode ? (
              <><Save size={14} strokeWidth={3} /> 保存して終了</>
            ) : (
              <><Edit3 size={14} strokeWidth={3} /> この日を編集</>
            )}
          </button>
        </div>

        <HealthCard 
          condition={currentCondition} 
          onUpdate={updateCondition} 
          selectedDate={selectedDate} 
          isEditMode={isEditMode}
        />

        <div className="mb-4 px-1 border-l-4 border-emerald-500 pl-3">
          <h3 className="text-sm font-black text-slate-800">今日の服薬</h3>
        </div>

        <div className="space-y-3">
          {medications.filter(m => !m.isFolder).length === 0 ? (
            <div className="py-10 text-center bg-white rounded-[32px] border border-dashed border-slate-200">
              <Pill className="mx-auto text-slate-200 mb-2" size={32} />
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">お薬が登録されていません</p>
            </div>
          ) : (
            medications.filter(m => !m.isFolder).map(med => (
              <div 
                key={med.id} 
                className={`p-4 rounded-[28px] border flex items-center gap-4 transition-all duration-300 ${
