              >
                <button 
                  onClick={() => toggleComplete(med.id)} 
                  disabled={!isEditMode}
                  className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${
                    isCompleted(med.id, selectedDate) 
                      ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-100' 
