            />
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {condition.score === 0 && !condition.memo ? (
            <p className="text-sm font-medium text-slate-300 text-center py-4 border border-dashed border-slate-100 rounded-2xl uppercase tracking-widest text-[10px]">
