import React, { useState } from 'react';
import { format, eachDayOfInterval, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameDay, isToday, addMonths, addWeeks, addDays, subMonths, subWeeks, subDays } from 'date-fns';
import { ja } from 'date-fns/locale';
import { Plus, Camera, FileText, Check, Edit3, Save, Pill, ChevronLeft, ChevronRight } from 'lucide-react';
import { HealthCard } from '../../components/HealthCard';
import { Medication, MedicationLog, DailyCondition, CalendarMode } from '../../types';
import { WEEK_DAYS } from '../../constants';

interface HomeViewProps {
  medications: Medication[];
  logs: MedicationLog[];
  setLogs: React.Dispatch<React.SetStateAction<MedicationLog[]>>;
  setMedications: React.Dispatch<React.SetStateAction<Medication[]>>;
  conditions: DailyCondition[];
  setConditions: React.Dispatch<React.SetStateAction<DailyCondition[]>>;
  onEditMed: (med: Medication) => void;
  onOpenForm: () => void;
  onOpenScan: () => void;
}

export const HomeView: React.FC<HomeViewProps> = ({ medications, logs, setLogs, setMedications, conditions, setConditions, onEditMed, onOpenForm, onOpenScan }) => {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [displayDate, setDisplayDate] = useState(new Date());
  const [calendarMode, setCalendarMode] = useState<CalendarMode>('week');
  const [showAddMenu, setShowAddMenu] = useState(false);
  const [isEditMode, setIsEditMode] = useState(false);

  const dateStr = format(selectedDate, 'yyyy-MM-dd');
  const currentCondition = conditions.find(c => c.dateStr === dateStr) || { dateStr, score: 0, memo: '' };

  const updateCondition = (updates: Partial<DailyCondition>) => {
    if (!isEditMode) return;
    setConditions(prev => {
      const existing = prev.find(c => c.dateStr === dateStr);
      if (existing) return prev.map(c => c.dateStr === dateStr ? { ...c, ...updates } : c);
      return [...prev, { dateStr, score: 0, memo: '', ...updates }];
    });
  };

  const isCompleted = (medId: string, date: Date) => {
    const dStr = format(date, 'yyyy-MM-dd');
    return logs.some(l => l.medicationId === medId && l.dateStr === dStr);
  };

  const toggleComplete = (medId: string) => {
    if (!isEditMode) return; 

    const dStr = format(selectedDate, 'yyyy-MM-dd');
    const existing = logs.find(l => l.medicationId === medId && l.dateStr === dStr);
    const med = medications.find(m => m.id === medId);
    if (!med) return;

    if (existing) {
      setLogs(prev => prev.filter(l => l.id !== existing.id));
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: m.stock + m.dosage } : m));
    } else {
      setLogs(prev => [...prev, { id: crypto.randomUUID(), medicationId: medId, timestamp: Date.now(), dateStr: dStr }]);
      setMedications(prev => prev.map(m => m.id === medId ? { ...m, stock: Math.max(0, m.stock - m.dosage) } : m));
    }
  };

  const handleDateSelect = (day: Date) => {
    setSelectedDate(day);
    setDisplayDate(day);
    setIsEditMode(false);
  };

  const navigateCalendar = (direction: 'next' | 'prev') => {
    if (calendarMode === 'month') {
      setDisplayDate(direction === 'next' ? addMonths(displayDate, 1) : subMonths(displayDate, 1));
    } else if (calendarMode === 'week') {
      setDisplayDate(direction === 'next' ? addWeeks(displayDate, 1) : subWeeks(displayDate, 1));
    } else {
      const nextDate = direction === 'next' ? addDays(selectedDate, 1) : subDays(selectedDate, 1);
      setSelectedDate(nextDate);
      setDisplayDate(nextDate);
    }
  };

  const renderCalendarContent = () => {
    if (calendarMode === 'day') {
      return (
        <div className="flex justify-center py-2">
          <button 
            className="flex flex-col items-center justify-center w-16 h-16 bg-emerald-500 text-white rounded-2xl shadow-lg"
          >
            <span className="text-[10px] font-black uppercase tracking-widest">{format(selectedDate, 'EEE', { locale: ja })}</span>
            <span className="text-2xl font-black">{format(selectedDate, 'd')}</span>
          </button>
        </div>
      );
    }

    const start = calendarMode === 'week' ? startOfWeek(displayDate) : startOfWeek(startOfMonth(displayDate));
    const end = calendarMode === 'week' ? endOfWeek(displayDate) : endOfWeek(endOfMonth(displayDate));
    const days = eachDayOfInterval({ start, end });

    return (
      <div className="grid grid-cols-7 text-center gap-y-1">
        {WEEK_DAYS.map((d, i) => (
          <div key={d} className={`text-[9px] font-bold pb-1 ${i === 0 ? 'text-red-400' : i === 6 ? 'text-blue-400' : 'text-slate-400'}`}>
            {d}
          </div>
        ))}
        {days.map((day, idx) => {
          const isSelected = isSameDay(day, selectedDate);
          const dailyLogs = logs.filter(l => l.dateStr === format(day, 'yyyy-MM-dd'));
          const hasCondition = conditions.some(c => c.dateStr === format(day, 'yyyy-MM-dd') && c.score > 0);

          return (
            <button 
              key={idx} 
              onClick={() => handleDateSelect(day)} 
              className={`flex flex-col items-center py-1 rounded-lg transition-all relative ${isSelected ? 'bg-emerald-500 text-white shadow-sm' : 'hover:bg-slate-50'}`}
            >
              <span className={`text-xs font-bold ${isToday(day) && !isSelected ? 'text-emerald-600' : ''}`}>{format(day, 'd')}</span>
              <div className="flex gap-0.5 mt-0.5 h-1">
                {dailyLogs.length > 0 && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-emerald-400'}`}></div>}
                {hasCondition && <div className={`w-1 h-1 rounded-full ${isSelected ? 'bg-white' : 'bg-blue-400'}`}></div>}
              </div>
            </button>
          );
        })}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-slate-50">
      <div className="bg-slate-50 py-1.5 safe-top border-b border-slate-200 relative shrink-0">
        <h1 className="text-center font-bold text-slate-800 text-sm">ホーム</h1>
        <div className="absolute right-4 top-1/2 -translate-y-1/2">
          <button onClick={() => setShowAddMenu(!showAddMenu)} className="bg-emerald-600 text-white px-3 py-1.5 rounded-full font-bold text-[10px] shadow-lg flex items-center gap-1 active:scale-95 transition-transform">
            <Plus size={12} /> 追加
          </button>
          {showAddMenu && (
            <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-xl border border-slate-100 py-2 z-[100] animate-in fade-in slide-in-from-top-2">
              <button onClick={() => { onOpenForm(); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                <FileText size={18} className="text-emerald-500" /> 手動入力
              </button>
              <button onClick={() => { onOpenScan(); setShowAddMenu(false); }} className="w-full px-4 py-3 flex items-center gap-3 hover:bg-slate-50 text-left text-sm font-bold text-slate-700">
                <Camera size={18} className="text-blue-500" /> 手帳スキャン
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white px-4 py-2 border-b border-slate-100 shrink-0 shadow-sm">
        <div className="flex justify-between items-center mb-2">
          <div className="flex items-center gap-2">
            <button onClick={() => navigateCalendar('prev')} className="p-1 text-slate-400 hover:text-slate-800 active:scale-90 transition-all"><ChevronLeft size={18} /></button>
            <h2 className="text-base font-black text-slate-800 min-w-[100px] text-center">{format(displayDate, 'yyyy年 M月', { locale: ja })}</h2>
            <button onClick={() => navigateCalendar('next')} className="p-1 text-slate-400 hover:text-slate-800 active:scale-90 transition-all"><ChevronRight size={18} /></button>
          </div>
          <div className="flex bg-slate-100 rounded-lg p-0.5">
            {(['month', 'week', 'day'] as CalendarMode[]).map((m) => (
              <button 
                key={m} 
                onClick={() => setCalendarMode(m)} 
                className={`px-2.5 py-0.5 text-[9px] font-bold rounded-md transition-all ${calendarMode === m ? 'bg-white shadow-sm text-emerald-700' : 'text-slate-400'}`}
              >
                {m === 'month' ? '月' : m === 'week' ? '週' : '日'}
              </button>
            ))}
          </div>
        </div>
        {renderCalendarContent()}
      </div>

      <div className="flex-1 overflow-y-auto px-4 pb-24 pt-3 no-scrollbar">
        <div className="flex items-center justify-between mb-3 px-1">
          <div className="flex flex-col">
            <h3 className="text-xl font-black text-slate-800 tracking-tighter leading-tight">
              {format(selectedDate, 'M月 d日 (EE)', { locale: ja })}
            </h3>
          </div>
          <button 
            onClick={() => setIsEditMode(!isEditMode)}
            className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl font-black text-[10px] transition-all active:scale-95 shadow-sm ${
              isEditMode 
                ? 'bg-slate-900 text-white shadow-slate-200' 
                : 'bg-white text-emerald-600 border border-emerald-100'
            }`}
          >
            {isEditMode ? (
              <><Save size={10} strokeWidth={3} /> 保存</>
            ) : (
              <><Edit3 size={10} strokeWidth={3} /> 編集</>
            )}
          </button>
        </div>

        {/* 服薬セクション: 日付の直下に配置 */}
        <div className="mb-2 px-1 border-l-4 border-emerald-500 pl-2">
          <h3 className="text-xs font-black text-slate-800 leading-none">今日の服薬</h3>
        </div>

        <div className="space-y-1.5 mb-5">
          {medications.filter(m => !m.isFolder).length === 0 ? (
            <div className="py-4 text-center bg-white rounded-[20px] border border-dashed border-slate-200">
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">お薬未登録</p>
            </div>
          ) : (
            medications.filter(m => !m.isFolder).map(med => (
              <div 
                key={med.id} 
                className={`p-2.5 rounded-[18px] border flex items-center gap-3 transition-all duration-300 ${
                  isEditMode ? 'bg-white border-emerald-100 shadow-md ring-2 ring-emerald-50' : 'bg-white border-slate-100 shadow-sm'
                }`}
              >
                <button 
                  onClick={() => toggleComplete(med.id)} 
                  disabled={!isEditMode}
                  className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 transition-all ${
                    isCompleted(med.id, selectedDate) 
                      ? 'bg-emerald-500 text-white shadow-sm' 
                      : isEditMode 
                        ? 'bg-slate-50 text-slate-200 border-2 border-slate-100' 
                        : 'bg-slate-50 text-slate-100 border border-slate-50'
                  }`}
                >
                  <Check size={18} strokeWidth={3} />
                </button>
                <div className="flex-1 min-w-0" onClick={() => !isEditMode && onEditMed(med)}>
                  <h4 className={`font-black text-sm tracking-tight leading-tight truncate ${isCompleted(med.id, selectedDate) ? 'text-slate-300 line-through' : 'text-slate-800'}`}>
                    {med.title}
                  </h4>
                  <div className="flex items-center gap-1.5 mt-0.5">
                    <span className="text-[8px] font-black text-slate-400 bg-slate-50 px-1 py-0.5 rounded-md uppercase tracking-widest leading-none">
                      {med.label}
                    </span>
                    <span className="text-[8px] font-bold text-slate-400 leading-none">
                      {med.dosage}{med.unit}
                    </span>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {/* 体調記録セクション: 服薬の後に配置 */}
        <div className="mb-2 px-1 border-l-4 border-blue-500 pl-2">
          <h3 className="text-xs font-black text-slate-800 leading-none">体調の記録</h3>
        </div>

        <HealthCard 
          condition={currentCondition} 
          onUpdate={updateCondition} 
          selectedDate={selectedDate} 
          isEditMode={isEditMode}
        />
      </div>
    </div>
  );
};

